CREATE OR ALTER PROCEDURE [dbo].[P_Manager_ProductShowManager_UPD]
	@Result		INT = 0 OUTPUT
AS
SET NOCOUNT ON;

DECLARE @EXEC_SCRIPT	NVARCHAR(MAX)
,		@SQLUser		NVARCHAR(50)

BEGIN TRAN

	UPDATE A
	SET A.CD_PRODUCTNO = B.CD_PRODUCTNO, 
		A.DT_EVENTTIME = B.DT_EVENTTIME, 
		A.DI_ISSHOW = B.DI_ISSHOW
	FROM dbo.EB_ProductShowManager AS A, GAMEMANAGE.GameManage.dbo.GM_ProductShowManager AS B
	WHERE A.CD_SHOW_NUM = B.CD_SHOW_NUM
	
	SET @Result = @@ROWCOUNT
	
	IF @@ERROR <> 0
	BEGIN    
		SELECT @Result = -1    
		GOTO FAIL_TRAN    
	END
	
COMMIT TRAN

GOTO END_PROC

FAIL_TRAN:
ROLLBACK TRAN

END_PROC:
GO
