CREATE OR ALTER PROCEDURE [dbo].[P_Manager_ProductInfo_UPD]
	@Result		INT = 0 OUTPUT
AS
SET NOCOUNT ON;

DECLARE @EXEC_SCRIPT	NVARCHAR(MAX)
,		@SQLUser		NVARCHAR(50)

BEGIN TRAN

	UPDATE A
	SET A.NO_PRODUCTID = B.NO_PRODUCTID
	,	A.DI_ISSALE = B. DI_ISSALE
	,	A.DI_ISEVENT = B.DI_ISEVENT
	,	A.DI_ISSHOW = B.DI_ISSHOW
	,	A.DI_ISCASHINVENSKIP = B.DI_ISCASHINVENSKIP
	,	A.ST_PRODUCTNAME = B.ST_PRODUCTNAME
	,	A.ST_PRODUCTNAME_LOCAL = B.ST_PRODUCTNAME_LOCAL
	,	A.CD_CATEGORYNO = B.CD_CATEGORYNO
	,	A.NO_SALEPRICE = B.NO_SALEPRICE
	,	A.NO_REALPRICE = B.NO_REALPRICE
	,	A.NO_QUANTITY = B.NO_QUANTITY
	,	A.NO_PERIOD = B.NO_PERIOD
	,	A.DI_ENABLEGIFT = B.DI_ENABLEGIFT
	,	A.NO_LIMITLEVEL = B.NO_LIMITLEVEL
	,	A.DT_ENDDATE = B.DT_ENDDATE
	FROM dbo.EB_Product AS A, GAMEMANAGE.GameManage.dbo.GM_Product AS B
	WHERE A.CD_PRODUCTNO = B.CD_PRODUCTNO
	
	SET @Result = @@ROWCOUNT
	
	IF @@ERROR <> 0
	BEGIN    
		SELECT @Result = -1    
		GOTO FAIL_TRAN    
	END
	
COMMIT TRAN
GOTO END_PROC

FAIL_TRAN:
ROLLBACK TRAN

END_PROC:
GO
CREATE OR ALTER PROCEDURE [dbo].[P_Manager_ProductInfo_INS]
	@Result		INT = 0 OUTPUT
AS
SET NOCOUNT ON;

DECLARE @EXEC_SCRIPT	NVARCHAR(MAX)
,		@SQLUser		NVARCHAR(50)

BEGIN TRAN
	
	INSERT INTO dbo.EB_Product
	(
		CD_PRODUCTNO, NO_PRODUCTID, DI_ISSALE, DI_ISEVENT, DI_ISSHOW, DI_ISCASHINVENSKIP, ST_PRODUCTNAME, 
		ST_PRODUCTNAME_LOCAL, CD_CATEGORYNO, NO_SALEPRICE, NO_REALPRICE, NO_PERIOD, NO_QUANTITY, DI_ENABLEGIFT, 
		NO_LIMITLEVEL, NO_LIMIT_USERUID, DT_STARTDATE, DT_ENDDATE
	)
	SELECT
		CD_PRODUCTNO, NO_PRODUCTID, DI_ISSALE, DI_ISEVENT, DI_ISSHOW, DI_ISCASHINVENSKIP, ST_PRODUCTNAME, 
		ST_PRODUCTNAME_LOCAL, CD_CATEGORYNO, NO_SALEPRICE, NO_REALPRICE, NO_PERIOD, NO_QUANTITY, DI_ENABLEGIFT, 
		NO_LIMITLEVEL, NO_LIMIT_USERUID, DT_STARTDATE, DT_ENDDATE
	FROM GAMEMANAGE.GameManage.dbo.GM_Product WITH(NOLOCK)
	
	SET @Result = @@ROWCOUNT
	
	IF @@ERROR <> 0
	BEGIN    
		SELECT @Result = -1    
		GOTO FAIL_TRAN    
	END
	
COMMIT TRAN
SET @Result = 0
GOTO END_PROC

FAIL_TRAN:
ROLLBACK TRAN

END_PROC:
GO
