	@CD_PRODUCTNO	BIGINT
,	@Result			INT = 0 OUTPUT
AS
SET NOCOUNT ON;

DECLARE @EXEC_SCRIPT	NVARCHAR(MAX)
,		@SQLUser		NVARCHAR(50)

BEGIN TRAN
	
	DELETE FROM dbo.EB_PRODUCT WHERE CD_PRODUCTNO = @CD_PRODUCTNO
	
	IF @@ERROR <> 0 OR @@ROWCOUNT <> 1
	BEGIN    
		SELECT @Result = -1    
		GOTO FAIL_TRAN    
	END
	
COMMIT TRAN
SET @Result = 0
GOTO END_PROC

FAIL_TRAN:
ROLLBACK TRAN

END_PROC:
GO
