CREATE OR ALTER PROCEDURE [dbo].[P_Manager_PackageInfo_UPD]
	@Result		INT = 0 OUTPUT
AS
SET NOCOUNT ON;

DECLARE @EXEC_SCRIPT	NVARCHAR(MAX)
,		@SQLUser		NVARCHAR(50)

BEGIN TRAN

	UPDATE A
	SET A.CD_PACKAGENO = B.CD_PACKAGENO_NEW
	,	A.CD_PRODUCTNO = B.CD_PRODUCTNO_NEW
	,	A.NO_REALPRICE = ISNULL(C.NO_REALPRICE, 0)
	FROM dbo.EB_ProductPackage AS A WITH(NOLOCK)
		LEFT OUTER JOIN GAMEMANAGE.GameManage.dbo.GM_ProductPackage AS B WITH(NOLOCK) 
			ON A.CD_PACKAGENO = B.CD_PACKAGENO AND A.CD_PRODUCTNO = B.CD_PRODUCTNO
		LEFT OUTER JOIN dbo.EB_Product AS C WITH(NOLOCK)
			ON B.CD_PACKAGENO_NEW = C.CD_PRODUCTNO
		
	
	SET @Result = @@ROWCOUNT
	
	IF @@ERROR <> 0
	BEGIN    
		SELECT @Result = -1    
		GOTO FAIL_TRAN    
	END
	
COMMIT TRAN
GOTO END_PROC

FAIL_TRAN:
ROLLBACK TRAN

END_PROC:
GO
