CREATE OR ALTER PROCEDURE [dbo].[EBP_ProductShowManager_SET]

AS

DECLARE @NowDate		SMALLDATETIME
SET @NowDate = GETDATE()


-- 동일 기간 중복 항목 제거 (가장 마지막에 등록된 설정만 적용)
UPDATE dbo.EB_Product
SET DI_ISSHOW = B.DI_ISSHOW
FROM dbo.EB_Product AS A WITH(NOLOCK)
JOIN dbo.EB_ProductShowManager AS B WITH(NOLOCK) ON A.CD_ProductNo = B.CD_ProductNo
WHERE B.CD_SHOW_NUM IN
(
	SELECT MAX(CD_SHOW_NUM)
	FROM dbo.EB_ProductShowManager WITH(NOLOCK)
	WHERE DT_EVENTTIME BETWEEN DATEADD(mi, -2, @NowDate) AND DATEADD(mi, 2, @NowDate)
	GROUP BY CD_PRODUCTNO
)	

IF(@@ROWCOUNT > 0)
BEGIN

	UPDATE dbo.EB_ReleaseTick
	SET NO_TICK = NO_TICK + 1, DT_SETDATE = @NowDate
	
	
	DELETE dbo.EB_ProductShowManager
		OUTPUT DELETED.CD_SHOW_NUM, DELETED.CD_PRODUCTNO, DELETED.DT_EVENTTIME, DELETED.DI_ISSHOW, DELETED.DT_REGDATE, GETDATE()
		INTO dbo.EB_ProductShowManagerLog(CD_SHOW_NUM, CD_PRODUCTNO, DT_EVENTTIME, DI_ISSHOW, DT_REGDATE, DT_DELDATE)
	WHERE CD_SHOW_NUM IN
	(
		SELECT MAX(CD_SHOW_NUM)
		FROM dbo.EB_ProductShowManager WITH(NOLOCK)
		WHERE DT_EVENTTIME BETWEEN DATEADD(mi, -2, @NowDate) AND DATEADD(mi, 2, @NowDate)
		GROUP BY CD_PRODUCTNO
	)	
	


END
GO
