/*
프로시저명 : dbo.EBP_Cash_Total_USERID_SEL
내용 : UserID로 엘소드 총 잔여 캐시 조회
작성일 : 2011-02-22
작성자 : 김병일
수정일 : 2011-09-28
수정자 : 김병일
수정내용 : 캐시, 보너스 구분하여 출력 추가
-- ## 관련 테이블 ##--
	dbo.EB_Cash
-- ## 관련 프로시저 ## --
	없음
-- ## 입력 ## --
	@ST_USERID			nvarchar(50)		-- 계정 아이디
-- ## 출력 ## --
	Output :
		@NO_TOTAL_CASH		int					-- 총 잔여 캐시
		@NO_REMAIN_CASH		int					-- 잔여 캐시
		@NO_REMAIN_BONUS	int					-- 잔여 보너스
	ReturnValue : 있음
	RecodeSet : 선택
		Result, NO_TOTAL_CASH, NO_REMAIN_CASH, NO_REMAIN_BONUS
		SP 처리 결과, 총 잔여 캐시, 잔여 캐시, 잔여 보너스
-- ## 실행 ## --
	DECLARE @Result			int
	,	@ST_USERID			nvarchar(50)		-- 계정 아이디
	,	@NO_TOTAL_CASH		int					-- 총 잔여 캐시
	,	@NO_REMAIN_CASH		int					-- 잔여 캐시
	,	@NO_REMAIN_BONUS	int					-- 잔여 보너스
	,	@DI_OUTPUT_RECORD	bit					-- 결과 RecordSet 출력 여부

	SELECT @ST_USERID		= 'TestAcc' + CAST(CAST((CAST(RAND() * 10000000000 AS bigint) / (CAST(RAND() * 100 AS tinyint) + 1)) AS bigint) + 1 AS varchar(12))

	SET @DI_OUTPUT_RECORD	= 0

	EXEC @Result = dbo.EBP_Cash_Total_USERID_SEL @ST_USERID, @NO_TOTAL_CASH OUTPUT, @NO_REMAIN_CASH OUTPUT, @NO_REMAIN_BONUS OUTPUT, @DI_OUTPUT_RECORD
	SELECT @Result AS Result, @NO_TOTAL_CASH AS NO_TOTAL_CASH, @NO_REMAIN_CASH AS NO_REMAIN_CASH, @NO_REMAIN_BONUS AS NO_REMAIN_BONUS
*/
CREATE OR ALTER PROCEDURE [dbo].[EBP_Cash_Total_USERID_SEL]
	@ST_USERID			nvarchar(50), 			-- 계정 아이디
	@NO_TOTAL_CASH		int = 0 OUTPUT ,		-- 총 잔여 캐시
	@NO_REMAIN_CASH		int = 0 OUTPUT ,		-- 잔여 캐시(2011-09-28 추가)
	@NO_REMAIN_BONUS	int = 0 OUTPUT ,		-- 잔여 보너스(2011-09-28 추가)
	@DI_OUTPUT_RECORD	bit = 1					-- 결과 RecordSet 출력 여부
AS
	SET NOCOUNT ON

	SELECT @NO_TOTAL_CASH = NO_REMAIN_CASH + NO_REMAIN_BONUS, @NO_REMAIN_CASH = NO_REMAIN_CASH, @NO_REMAIN_BONUS = NO_REMAIN_BONUS
	FROM dbo.EB_Cash WITH(NOLOCK)
	WHERE ST_USERID = @ST_USERID

	IF @@ROWCOUNT = 0
		SELECT @NO_TOTAL_CASH = 0, @NO_REMAIN_CASH = 0, @NO_REMAIN_BONUS = 0

	IF @DI_OUTPUT_RECORD = 1
		SELECT 0 AS Result, @NO_TOTAL_CASH AS NO_TOTAL_CASH, @NO_REMAIN_CASH AS NO_REMAIN_CASH, @NO_REMAIN_BONUS AS NO_REMAIN_BONUS

	RETURN 0
GO
