-- Description:	구매 사전체크 -> 퍼블리셔 캐시차감 -> 아이템구입 단계별 로그 남기기
-- =============================================
CREATE OR ALTER PROCEDURE [dbo].[EBP_BuyItemLog_INS]
	@ST_SERVERORDERID		varchar(50) ,			-- 서버 발행 주문번호('20101207204029_3_24_1' / yyyymmddhhmiss_ServerUID_UserUID_구매일련번호)
	@ST_GROUPORDERID		varchar(50) ,			-- 그룹별 발행 주문번호 (2013-04-30 추가)
	@CD_USERUID				bigint ,				-- 계정 UID
	@ST_USERID				nvarchar(50) ,			-- 계정 아이디
	@NO_SERVER_SET_ID		tinyint ,				-- 서버 그룹
	@NO_UNITUID				bigint ,				-- 캐릭터 UID
	@NO_LEVEL				tinyint ,				-- 캐릭터 레벨
	@NO_PRODUCT_NUM			bigint ,				-- 아이템(상품) 번호
	@NO_QUANTITY			smallint ,				-- 구매 수량
	@NO_PRICE				int ,					-- 구매 가격
	@DI_ITEM_KEEP			tinyint ,				-- 캐시 보관함 저장 여부(1 - 저장 : 0 - 미저장)
	@NO_TO_USERUID			bigint ,				-- 받는 계정 UID
	@NO_TO_UNITUID			bigint ,				-- 받는 캐릭터 UID
	@ST_GIFT_MESSAGE		nvarchar(50) ,			-- 선물 메시지
	@DI_BUY_CASH			tinyint ,				-- 구매 캐시 종류(0 - 통합  : 1 - 캐시 : 2 - 보너스)(2011-09-28 추가)
	@NO_CHANNEL_CODE		tinyint = 0 ,			-- 채널링 코드 (2013-05-11 추가)
	@NO_TOTAL_CASH			int = NULL,				-- 총 잔여 캐시
	@CD_TRAN_NUM			bigint = NULL,			-- 거래 고유번호
	@NO_REMAIN_CASH			int = NULL,				-- 잔여 캐시(2011-09-28 추가)
	@NO_REMAIN_BONUS		int = NULL,				-- 잔여 보너스(2011-09-28 추가)
	@DI_OUTPUT_RECORD		bit = 1					-- 결과 RecordSet 출력 여부
AS
	SET NOCOUNT ON

	-- 사용 변수 선언
	DECLARE @Result				int
	SET @Result = 0
	
	BEGIN TRAN
	
		IF NOT EXISTS (SELECT ST_SERVERORDERID FROM dbo.EB_BuyItemLog WITH(NOLOCK) WHERE ST_SERVERORDERID = @ST_SERVERORDERID)
		BEGIN
		
			INSERT INTO dbo.EB_BuyItemLog (ST_SERVERORDERID, ST_GROUPORDERID, NO_SERVER_SET_ID, NO_CHANNEL_CODE, CD_USERUID, ST_USERID, NO_UNITUID, 
											NO_LEVEL, NO_PRODUCT_NUM, NO_QUANTITY, NO_PRICE, DI_ITEM_KEEP, NO_TO_USERUID, 
											NO_TO_UNITUID, ST_GIFT_MESSAGE, DI_BUY_CASH, CD_TRAN_NUM, NO_TOTAL_CASH, NO_REMAIN_CASH, 
											NO_REMAIN_BONUS, DT_CHECKDATE, DT_ENDDATE)
			SELECT @ST_SERVERORDERID, @ST_GROUPORDERID, @NO_SERVER_SET_ID, @NO_CHANNEL_CODE, @CD_USERUID, @ST_USERID, @NO_UNITUID, 
					@NO_LEVEL, @NO_PRODUCT_NUM, @NO_QUANTITY, @NO_PRICE, @DI_ITEM_KEEP, @NO_TO_USERUID,
					@NO_TO_UNITUID, @ST_GIFT_MESSAGE, @DI_BUY_CASH, @CD_TRAN_NUM, @NO_TOTAL_CASH, @NO_REMAIN_CASH,
					@NO_REMAIN_BONUS, GETDATE(), GETDATE()
			
			IF @@ERROR <> 0 OR @@ROWCOUNT <> 1
			BEGIN	SET @Result = -1	GOTO FAIL_TRAN;	END
					
		END
		ELSE
		BEGIN
		
			UPDATE	dbo.EB_BuyItemLog
			SET		CD_TRAN_NUM = @CD_TRAN_NUM
			,		NO_TOTAL_CASH = @NO_TOTAL_CASH
			,		NO_REMAIN_CASH = @NO_REMAIN_CASH
			,		NO_REMAIN_BONUS = @NO_REMAIN_BONUS
			,		DT_ENDDATE = GETDATE()
			WHERE	ST_SERVERORDERID = @ST_SERVERORDERID
		
			IF @@ERROR <> 0 OR @@ROWCOUNT <> 1
			BEGIN	SET @Result = -2	GOTO FAIL_TRAN;	END
		
		END	
		
	COMMIT TRAN
	GOTO END_PROC;

FAIL_TRAN:
	ROLLBACK TRAN;
	
END_PROC:
	IF @DI_OUTPUT_RECORD = 1
		SELECT @Result
		
	RETURN @Result
GO
-- =============================================
-- Author:		YJ
-- Create date: 2012. 08. 08
-- Description:	대만 캐쉬 충전 오류 저장
-- =============================================
CREATE OR ALTER PROCEDURE [dbo].[EBP_CashFailLog_INS]
    @iUserUID       [int],
	@ResultCode     [tinyint],
	@OutString		[nvarchar](300)
AS

SET NOCOUNT ON;

DECLARE @Result int

BEGIN TRY

	BEGIN TRAN	
		
		INSERT INTO EB_CashFailLog (UserUID, ResultCode, OutString)
			SELECT @iUserUID, @ResultCode, @OutString

	    
	COMMIT TRAN

	SET @Result = 0	
	GOTO END_PROC
	
END TRY

BEGIN CATCH
	DECLARE @NO_XACT_STATE		smallint
	SET @NO_XACT_STATE			= XACT_STATE()		-- 트랜잭션 상태 정보

	IF @NO_XACT_STATE <> 0
		ROLLBACK TRAN
END CATCH

END_PROC:
SELECT @Result
GO
CREATE OR ALTER PROCEDURE [dbo].[bup_Update_User_Purchase_info_new]
	@iUserUID	BIGINT,
	@iEventUID	INT,
	@Cnt		INT,
	@iOK		INT	= 0

/*
	2009. 09. 16
	sutamtwo
	Cash inventory -> my inventory log, delete from cash inventory
*/


AS
SET NOCOUNT ON;

DECLARE	@sdtNow	SMALLDATETIME
SELECT	@sdtNow = GETDATE()


BEGIN TRAN

	IF NOT EXISTS (SELECT 1 FROM dbo.Bill_UserPurchaseLimitInfo WITH (NOLOCK) WHERE UserUID = @iUserUID AND EventUID = @iEventUID)
	BEGIN
		INSERT INTO dbo.Bill_UserPurchaseLimitInfo (UserUID, EventUID, PurchaseCount, RegDate)
		SELECT @iUserUID, @iEventUID, @Cnt, @sdtNow
		IF @@ERROR <> 0 OR @@ROWCOUNT <> 1
		BEGIN
			SELECT @iOK = -1	GOTO FAIL_TRAN
		END
	END
	ELSE
	BEGIN
		UPDATE dbo.Bill_UserPurchaseLimitInfo
			SET PurchaseCount = @Cnt, Regdate = @sdtNow
				WHERE UserUID = @iUserUID
					AND EventUID = @iEventUID
		IF @@ERROR <> 0 OR @@ROWCOUNT <> 1
		BEGIN
			SELECT @iOK = -2	GOTO FAIL_TRAN
		END
	END


COMMIT TRAN	

GOTO END_PROC

FAIL_TRAN:
ROLLBACK TRAN

END_PROC:
SELECT @iOK
GO
