/*
프로시저명 : dbo.EBI_Buy_Product_LimitedUser_Set
내용 : 계정 구매 수량 제한 상품 구매 수량 증가
작성일 : 2011-05-05
작성자 : KOG_M
-- ## 관련 테이블 ##--
	dbo.EB_BuyCashItemLimited_User
-- ## 관련 프로시저 ## --
	없음
-- ## 입력 ## --
	@CD_PRODUCT_SM		int				-- 상품 고유번호
	@CD_USERUID			bigint			-- 계정 UID
	@NO_SERVER_SET_ID	tinyint			-- 서버 그룹
	@NO_LIMIT_USERUID	int				-- 구매 제한 수량
-- ## 출력 ## --
	Output : 없음
	ReturnValue : 있음
	RecodeSet : 없음
-- ## 실행 ## --
	DECLARE @CD_PRODUCT_SM	int				-- 상품 고유번호
	,	@CD_USERUID			bigint			-- 계정 UID
	,	@NO_SERVER_SET_ID	tinyint			-- 서버 그룹
	,	@NO_LIMIT_USERUID	int				-- 구매 제한 수량

	SELECT @CD_PRODUCT_SM = CD_PRODUCT_SM
	,	@CD_USERUID = CD_USERUID
	FROM dbo.EB_BuyCashItemLimited_User WITH(NOLOCK)
	ORDER BY NEWID()

	IF @@ROWCOUNT = 0 BEGIN
		SELECT TOP 1 @CD_PRODUCT_SM = CD_PRODUCT_SM
		,	@CD_USERUID = CAST((CAST(RAND() * 10000000000 AS bigint) / (CAST(RAND() * 100 AS tinyint) + 1)) AS bigint) + 1
		,	@NO_LIMIT_USERUID = NO_LIMIT_USERUID
		FROM dbo.EB_ProductShopManager WITH(NOLOCK)
		WHERE CONVERT(char(8), GETDATE(), 112) BETWEEN DI_STARTDATE AND DI_ENDDATE
			AND GETDATE() BETWEEN DATEADD(mi, CAST(RIGHT(DI_STARTTIME, 2) AS tinyint), DATEADD(hh, CAST(RIGHT('0'+LEFT(DI_STARTTIME, LEN(DI_STARTTIME)-2), 2) AS tinyint), DI_STARTDATE))
				AND DATEADD(mi, CAST(RIGHT(DI_ENDTIME, 2) AS tinyint), DATEADD(hh, CAST(RIGHT('0'+LEFT(DI_ENDTIME, LEN(DI_ENDTIME)-2), 2) AS tinyint), DI_ENDDATE))
		ORDER BY NEWID()
	END
	ELSE
	BEGIN
		SELECT @NO_LIMIT_USERUID = ISNULL(NO_LIMIT_USERUID, 1)
		FROM dbo.EB_ProductShopManager WITH(NOLOCK)
		WHERE CD_PRODUCT_SM = @CD_PRODUCT_SM
	END
	
	SET @NO_SERVER_SET_ID = 1
	
	EXEC @Result = dbo.EBI_Buy_Product_LimitedUser_Set @CD_PRODUCT_SM, @CD_USERUID, @NO_SERVER_SET_ID, @NO_LIMIT_USERUID
	SELECT @Result AS Result
*/
CREATE OR ALTER PROCEDURE [dbo].[EBI_Buy_Product_LimitedUser_Set]
	@CD_PRODUCT_SM		bigint ,			-- 상품 고유번호
	@CD_USERUID			bigint ,			-- 계정 UID
	@NO_SERVER_SET_ID	tinyint ,			-- 서버 그룹
	@NO_LIMIT_USERUID	int					-- 구매 제한 수량
AS
	SET NOCOUNT ON

	BEGIN TRY
		IF EXISTS (SELECT * FROM dbo.EB_BuyCashItemLimited_User WITH(NOLOCK) WHERE CD_PRODUCT_SM = @CD_PRODUCT_SM AND CD_USERUID = @CD_USERUID AND @NO_SERVER_SET_ID = NO_SERVER_SET_ID ) BEGIN
			UPDATE dbo.EB_BuyCashItemLimited_User
			SET NO_BUY_COUNT = NO_BUY_COUNT + 1
			WHERE CD_PRODUCT_SM = @CD_PRODUCT_SM AND CD_USERUID = @CD_USERUID AND NO_SERVER_SET_ID = @NO_SERVER_SET_ID
				AND NO_BUY_COUNT < @NO_LIMIT_USERUID

			IF @@ROWCOUNT <> 1
				RETURN -26
		END
		ELSE BEGIN
			INSERT INTO dbo.EB_BuyCashItemLimited_User ( CD_PRODUCT_SM, CD_USERUID, NO_SERVER_SET_ID, NO_BUY_COUNT )
			VALUES ( @CD_PRODUCT_SM, @CD_USERUID, @NO_SERVER_SET_ID, 1 )
		END
	END TRY
	BEGIN CATCH
		RETURN -1
	END CATCH

	RETURN 0
GO
/*
프로시저명 : dbo.EBI_Buy_Product_CHK
내용 : 상품 정보 확인
작성일 : 2011-05-04
작성자 : KOG_M
-- ## 관련 테이블 ##--
	dbo.EB_Product
-- ## 관련 프로시저 ## --
	없음
-- ## 입력 ## --
	@CD_PRODUCTNO		int							-- 상품 고유번호
-- ## 출력 ## --
	Output :
		@DI_ISSALE			bit							-- 상품 판매 여부
		@DT_STARTDATE		smalldatetime				-- 판매 시작일시
		@DT_ENDDATE			smalldatetime				-- 판매 종료일시
		@DI_ENABLEGIFT		bit							-- 선물 가능여부
		@NO_SALEPRICE		int							-- 상품 가격
		@NO_REALPRICE		int							-- 상품 가격
	ReturnValue : 있음
	RecodeSet : 없음
-- ## 실행 ## --
	DECLARE @Result			int
	,	@CD_PRODUCTNO		int							-- 상품 고유번호
	,	@DI_ISSALE			bit							-- 상품 판매 여부
	,	@DT_STARTDATE		smalldatetime				-- 판매 시작일시
	,	@DT_ENDDATE			smalldatetime				-- 판매 종료일시
	,	@DI_ENABLEGIFT		bit							-- 선물 가능여부
	,	@NO_SALEPRICE		int							-- 상품 가격
	,	@NO_REALPRICE		int							-- 상품 가격

	SELECT @CD_PRODUCTNO = CD_PRODUCTNO
	FROM dbo.EB_Product WITH(NOLOCK)
	ORDER BY NEWID()

	EXEC @Result = dbo.EBI_Buy_Product_CHK @NO_PRODUCT_NUM, @DI_ISSALE OUTPUT, @DT_STARTDATE OUTPUT, @DT_ENDDATE OUTPUT, @DI_ENABLEGIFT OUTPUT, @NO_SALEPRICE OUTPUT, @NO_REALPRICE OUTPUT
	SELECT @Result AS Result, @DI_ISSALE AS DI_ISSALE, @DT_STARTDATE AS DT_STARTDATE, @DT_ENDDATE AS DT_ENDDATE, @DI_ENABLEGIFT AS DI_ENABLEGIFT, @NO_SALEPRICE AS NO_SALEPRICE, @NO_REALPRICE AS NO_REALPRICE
*/
CREATE OR ALTER PROCEDURE [dbo].[EBI_Buy_Product_CHK]
	@CD_PRODUCTNO		bigint ,							-- 상품 고유번호
	@DI_ISSALE			bit = NULL				OUTPUT ,	-- 상품 판매 여부
	@DT_STARTDATE		smalldatetime = NULL	OUTPUT ,	-- 판매 시작일시
	@DT_ENDDATE			smalldatetime = NULL	OUTPUT ,	-- 판매 종료일시
	@DI_ENABLEGIFT		bit = NULL				OUTPUT ,	-- 선물 가능여부
	@NO_SALEPRICE		int = NULL				OUTPUT ,	-- 상품 가격
	@NO_REALPRICE		int = NULL				OUTPUT ,	-- 상품 가격
	@NO_LIMIT_USERUID	int = NULL				OUTPUT		-- 계정별 구매 제한 수량
AS
	SET NOCOUNT ON

	SELECT @DT_STARTDATE = DT_STARTDATE, @DI_ISSALE = DI_ISSALE, @DT_ENDDATE = DT_ENDDATE, @DI_ENABLEGIFT = DI_ENABLEGIFT, @NO_SALEPRICE = NO_SALEPRICE, @NO_REALPRICE = NO_REALPRICE
	FROM dbo.EB_Product WITH(NOLOCK)
	WHERE CD_PRODUCTNO = @CD_PRODUCTNO

	IF @@ROWCOUNT = 0
		RETURN -99
	
	RETURN 0
GO
/*
프로시저명 : dbo.EBI_Bonus_Expire_INT
내용 : 보너스 만료 등록
작성일 : 2011-02-22
작성자 : 김병일
-- ## 관련 테이블 ##--
	dbo.EB_Bonus_Expire
-- ## 관련 프로시저 ## --
	없음
-- ## 입력 ## --
	@CD_TRAN_NUM		bigint			-- 거래 고유번호
	@CD_USERUID			bigint			-- 계정 UID
	@NO_CHARGE_BONUS	int				-- 보너스 캐시
	@DT_BONUS_EXPIRE	smalldatetime	-- 보너스 만료일시
-- ## 출력 ## --
	Output : 없음
	ReturnValue : 있음
	RecodeSet : 없음
-- ## 실행 ## --
	DECLARE @Result			int
	,	@CD_TRAN_NUM		bigint			-- 거래 고유번호
	,	@CD_USERUID			bigint			-- 계정 UID
	,	@NO_CHARGE_BONUS	int				-- 보너스 캐시
	,	@DT_BONUS_EXPIRE	smalldatetime	-- 보너스 만료일시

	SELECT @CD_USERUID		= CAST((CAST(RAND() * 10000000000 AS bigint) / (CAST(RAND() * 100 AS tinyint) + 1)) AS bigint) + 1
	,	@NO_CHARGE_BONUS	= 10
	,	@DT_BONUS_EXPIRE	= DATEADD(MI, 10, GETDATE())

	EXEC dbo.EBI_TransactionNumber_INT 1, @CD_TRAN_NUM OUTPUT

	EXEC @Result = dbo.EBI_Bonus_Expire_INT @CD_TRAN_NUM, @CD_USERUID, @NO_CHARGE_BONUS, @DT_BONUS_EXPIRE
	SELECT @Result AS Result
*/
CREATE OR ALTER PROCEDURE [dbo].[EBI_Bonus_Expire_INT]
	@CD_TRAN_NUM			bigint ,		-- 거래 고유번호
	@CD_USERUID				bigint ,		-- 계정 UID
	@NO_CHARGE_BONUS		int ,			-- 보너스 캐시
	@DT_BONUS_EXPIRE		smalldatetime	-- 보너스 만료일시
AS
	SET NOCOUNT ON

	INSERT INTO dbo.EB_Bonus_Expire ( CD_TRAN_NUM, CD_USERUID, NO_CHARGE_BONUS, NO_EXPIRE_BONUS, DT_BONUS_EXPIRE, DT_EXPIRE_DATE )
	VALUES ( @CD_TRAN_NUM, @CD_USERUID, @NO_CHARGE_BONUS, NULL, @DT_BONUS_EXPIRE, NULL )

	RETURN @@ERROR
GO
/*
프로시저명 : dbo.EBI_BillOrder_SET
내용 : 주문 등록
작성일 : 2011-02-15
작성자 : 김병일
-- ## 관련 테이블 ##--
	dbo.EB_BillOrder
-- ## 관련 프로시저 ## --
	없음
-- ## 입력 ## --
	@CD_TRAN_NUM		bigint				-- 거래 고유번호
	@ST_TRANSACTION		varchar(21)			-- 처리열 고유 문자
	@CD_USERUID			bigint				-- 계정 UID
	@ST_USERID			nvarchar(50)		-- 계정 아이디
	@NO_SERVER_SET_ID	tinyint				-- 서버 그룹
	@NO_UNITUID			bigint				-- 캐릭터 UID
	@NO_LEVEL			tinyint				-- 캐릭터 레벨
	@NO_CHARGE_CASH		int					-- 충전 캐시
	@ST_USER_IP			varchar(16)			-- 유저 아이피
	@DI_ORDER_TYPE		tinyint				-- 주문 종류
-- ## 출력 ## --
	Output : 없음
	ReturnValue : 있음
	RecodeSet : 선택
		Result
		SP 처리 결과
-- ## 실행 ## --
	DECLARE @Result			int
	,	@CD_TRAN_NUM		bigint				-- 거래 고유번호
	,	@ST_TRANSACTION		varchar(21)			-- 처리열 고유 문자
	,	@CD_USERUID			bigint				-- 계정 UID
	,	@ST_USERID			nvarchar(50)		-- 계정 아이디
	,	@NO_SERVER_SET_ID	tinyint				-- 서버 그룹
	,	@NO_UNITUID			bigint				-- 캐릭터 UID
	,	@NO_LEVEL			tinyint				-- 캐릭터 레벨
	,	@NO_CHARGE_CASH		int					-- 충전 캐시
	,	@ST_USER_IP			varchar(16)			-- 유저 아이피
	,	@DI_ORDER_TYPE		tinyint				-- 주문 종류

	SELECT @CD_USERUID		= CAST((CAST(RAND() * 10000000000 AS bigint) / (CAST(RAND() * 100 AS tinyint) + 1)) AS bigint) + 1
	,	@NO_SERVER_SET_ID	= CAST(RAND() * 10 / 2 AS tinyint) + 1
	,	@NO_UNITUID			= CAST((CAST(RAND() * 10000000000 AS bigint) / (CAST(RAND() * 100 AS tinyint) + 1)) AS bigint) + 1
	,	@NO_LEVEL			= CAST(RAND() * 58 AS tinyint) + 1
	,	@NO_CHARGE_CASH		= CAST(RAND() * 100 AS INT) * 10 + 10
	,	@ST_USER_IP			= '127.0.0.1'
	,	@DI_ORDER_TYPE		= 1

	EXEC dbo.EBI_TransactionNumber_INT @DI_ORDER_TYPE, @CD_TRAN_NUM OUTPUT

	SET @ST_TRANSACTION		= N'O'+RIGHT(REPLACE(REPLACE(REPLACE(REPLACE(CONVERT(varchar(23), GETDATE(), 121), '-', ''), ' ', ''), ':', ''), '.', '') + RIGHT('0000000000' + CAST(CAST(RAND() * 100000000000000000 AS bigint) + 1 AS varchar(20)), 10) + RIGHT(CAST(@CD_USERUID AS varchar(10)), 10), 20)
	SET @ST_USERID			= 'TestAcc' + CAST(@CD_USERUID AS varchar(12))

	EXEC @Result = dbo.EBI_BillOrder_SET @CD_TRAN_NUM, @ST_TRANSACTION, @CD_USERUID, @ST_USERID, @NO_SERVER_SET_ID, @NO_UNITUID, @NO_LEVEL, @NO_CHARGE_CASH, @ST_USER_IP, @DI_ORDER_TYPE
	SELECT @Result AS Result
*/
CREATE OR ALTER PROCEDURE [dbo].[EBI_BillOrder_SET]
	@CD_TRAN_NUM		bigint ,				-- 거래 고유번호
	@ST_TRANSACTION		varchar(21) ,			-- 처리열 고유 문자
	@CD_USERUID			bigint ,				-- 계정 UID
	@ST_USERID			nvarchar(50) ,			-- 계정 아이디
	@NO_SERVER_SET_ID	tinyint ,				-- 서버 그룹
	@NO_UNITUID			bigint ,				-- 캐릭터 UID
	@NO_LEVEL			tinyint ,				-- 캐릭터 레벨
	@NO_CHARGE_CASH		int ,					-- 충전 캐시
	@ST_USER_IP			varchar(16) ,			-- 유저 아이피
	@DI_ORDER_TYPE		tinyint					-- 주문 종류
AS
	SET NOCOUNT ON

	INSERT INTO dbo.EB_BillOrder ( CD_TRAN_NUM, ST_TRANSACTION, CD_USERUID, ST_USERID, NO_SERVER_SET_ID, NO_UNITUID, NO_LEVEL, NO_CHARGE_CASH, NO_CHARGE_BONUS, NO_CHARGE_ITEM, ST_USER_IP, DI_ORDER_TYPE, DT_ORDER_DATE, DI_ORDER_RESULT, DT_RESULT_DATE )
	VALUES ( @CD_TRAN_NUM, @ST_TRANSACTION, @CD_USERUID, @ST_USERID, @NO_SERVER_SET_ID, @NO_UNITUID, @NO_LEVEL, @NO_CHARGE_CASH, 0, 0, @ST_USER_IP, @DI_ORDER_TYPE, GETDATE(), 1, NULL )

	RETURN @@ERROR
GO
/*
프로시저명 : dbo.EBI_BillEvent_JOIN
내용 : 주문 이벤트 참여
작성일 : 2011-02-18
작성자 : 김병일
-- ## 관련 테이블 ##--
	dbo.EB_BillEventJoinLog
-- ## 관련 프로시저 ## --
	없음
-- ## 입력 ## --
	@CD_EVENT				int				-- 이벤트 고유번호
	@CD_TRAN_NUM			bigint			-- 거래 고유번호
	@CD_USERUID				int				-- 계정 UID
	@NO_LIMIT_BONUS_JOIN	int				-- 보너스 지급 제한
	@NO_LIMIT_ITEM_JOIN		int				-- 보너스 아이템 지급 제한
	@NO_CHARGE_BONUS		int				-- 충전 보너스 캐시
	@NO_BONUS_ITEM			int				-- 충전 보너스 아이템
	@DT_JOIN_DATE			datetime		-- 참여 일시(주문 시간과 맞추기)
-- ## 출력 ## --
	Output :
		@NO_CHARGE_BONUS		int				-- 실제 입력한 보너스
		@NO_BONUS_ITEM			int				-- 실제 입력한 보너스 아이템
	ReturnValue : 있음
	RecodeSet : 없음
-- ## 실행 ## --
	DECLARE @Result				int
	,	@CD_EVENT				int				-- 이벤트 고유번호
	,	@CD_TRAN_NUM			bigint			-- 거래 고유번호
	,	@CD_USERUID				int				-- 계정 UID
	,	@NO_LIMIT_BONUS_JOIN	int				-- 보너스 지급 제한
	,	@NO_LIMIT_ITEM_JOIN		int				-- 보너스 아이템 지급 제한
	,	@NO_CHARGE_BONUS		int				-- 충전 보너스 캐시
	,	@NO_BONUS_ITEM			int				-- 충전 보너스 아이템
	,	@DT_JOIN_DATE			datetime		-- 참여 일시(주문 시간과 맞추기)

	SELECT @CD_EVENT			= 1
	,	@CD_USERUID				= CAST((CAST(RAND() * 10000000000 AS bigint) / (CAST(RAND() * 100 AS tinyint) + 1)) AS bigint) + 1
	,	@NO_LIMIT_BONUS_JOIN	= CAST(RAND() * 10 AS tinyint)
	,	@NO_LIMIT_ITEM_JOIN		= CAST(RAND() * 5 AS tinyint)
	,	@NO_CHARGE_BONUS		= CAST(RAND() * 10 AS tinyint) + 1
	,	@NO_BONUS_ITEM			= CAST(RAND() * 10000 AS int)
	,	@DT_JOIN_DATE			= GETDATE()

	EXEC dbo.EBI_TransactionNumber_INT 1, @CD_TRAN_NUM OUTPUT

	EXEC @Result = dbo.EBI_BillEvent_JOIN @CD_EVENT, @CD_TRAN_NUM, @CD_USERUID, @NO_LIMIT_BONUS_JOIN, @NO_LIMIT_ITEM_JOIN, @NO_CHARGE_BONUS OUTPUT, @NO_BONUS_ITEM OUTPUT, @DT_JOIN_DATE
	SELECT @Result AS Result, @NO_CHARGE_BONUS AS NO_CHARGE_BONUS, @NO_BONUS_ITEM AS NO_BONUS_ITEM
*/
CREATE OR ALTER PROCEDURE [dbo].[EBI_BillEvent_JOIN]
	@CD_EVENT				int ,			-- 이벤트 고유번호
	@CD_TRAN_NUM			bigint ,		-- 거래 고유번호
	@CD_USERUID				int	,			-- 계정 UID
	@NO_LIMIT_BONUS_JOIN	int ,			-- 보너스 지급 제한
	@NO_LIMIT_ITEM_JOIN		int ,			-- 보너스 아이템 지급 제한
	@NO_CHARGE_BONUS		int OUTPUT ,	-- 충전 보너스
	@NO_BONUS_ITEM			bigint OUTPUT ,	-- 충전 보너스 아이템
	@DT_JOIN_DATE			datetime		-- 참여 일시(주문 시간과 맞추기)
AS
	SET NOCOUNT ON

	-- 사용 변수 선언
	DECLARE @CD_EVENT_JOIN_NUM		int				-- 이벤트 참여 횟수 번호

	-- 현재 참여 횟수 확인(이전 참여 횟수 + 1)
	SELECT @CD_EVENT_JOIN_NUM = ISNULL(MAX(CD_EVENT_JOIN_NUM), 0) + 1
	FROM dbo.EB_BillEventJoinLog WITH(NOLOCK)
	WHERE CD_EVENT = @CD_EVENT AND CD_USERUID = @CD_USERUID

	-- 참여 횟수가 보너스 캐시 지급 가능 횟수 보다 클 경우
	IF @CD_EVENT_JOIN_NUM > NULLIF(@NO_LIMIT_BONUS_JOIN, 0)
		SET @NO_CHARGE_BONUS = 0									-- 보너스 캐시 지급 안함

	-- 참여 횟수가 보너스 아이템 지급 가능 횟수 보다 클 경우
	IF @CD_EVENT_JOIN_NUM > NULLIF(@NO_LIMIT_ITEM_JOIN, 0)
		SET @NO_BONUS_ITEM = 0										-- 보너스 아이템 지급 안함

	-- 이벤트 지급 내역이 있는 경우
	IF @NO_CHARGE_BONUS > 0 OR @NO_BONUS_ITEM > 0 BEGIN
		-- 이벤트 참여 내역 기록
		INSERT INTO dbo.EB_BillEventJoinLog ( CD_EVENT, CD_USERUID, CD_EVENT_JOIN_NUM, CD_TRAN_NUM, DT_JOIN_DATE )
		VALUES ( @CD_EVENT, @CD_USERUID, @CD_EVENT_JOIN_NUM, @CD_TRAN_NUM, @DT_JOIN_DATE )
	END

	RETURN @@ERROR
GO
/*
프로시저명 : dbo.EBI_BillEvent_CHK
내용 : 주문 이벤트 확인
작성일 : 2011-02-18
작성자 : KOG_M
-- ## 관련 테이블 ##--
	dbo.EB_BillEvent
-- ## 관련 프로시저 ## --
	없음
-- ## 입력 ## --
	@NO_CHARGE_CASH			int				-- 충전 금액
-- ## 출력 ## --
	Output :
		@CD_EVENT				int				-- 이벤트 고유번호
		@NO_CHARGE_BONUS		int				-- 충전 보너스 캐시
		@DT_BONUS_EXPIRE		smalldatetime	-- 충전 보너스 캐시 만료일
		@NO_BONUS_ITEM			int				-- 충전 보너스 아이템
		@NO_LIMIT_BONUS_JOIN	smallint		-- 보너스 지급 제한
		@NO_LIMIT_ITEM_JOIN		smallint		-- 보너스 아이템 지급 제한
	ReturnValue : 없음
	RecodeSet : 없음
-- ## 실행 ## --
	DECLARE @NO_CHARGE_CASH		int				-- 충전 금액
	,	@CD_EVENT				int				-- 이벤트 고유번호
	,	@NO_CHARGE_BONUS		int				-- 충전 보너스 캐시
	,	@DT_BONUS_EXPIRE		smalldatetime	-- 충전 보너스 캐시 만료일
	,	@NO_BONUS_ITEM			int				-- 충전 보너스 아이템
	,	@NO_LIMIT_BONUS_JOIN	smallint		-- 보너스 지급 제한
	,	@NO_LIMIT_ITEM_JOIN		smallint		-- 보너스 아이템 지급 제한

	SELECT @NO_CHARGE_CASH	= 1000

	EXEC dbo.EBI_BillEvent_CHK @NO_CHARGE_CASH, @CD_EVENT OUTPUT, @NO_CHARGE_BONUS OUTPUT, @DT_BONUS_EXPIRE OUTPUT, @NO_BONUS_ITEM OUTPUT, @NO_LIMIT_BONUS_JOIN OUTPUT, @NO_LIMIT_ITEM_JOIN OUTPUT
	SELECT @CD_EVENT AS CD_EVENT, @NO_CHARGE_BONUS AS NO_CHARGE_BONUS, @DT_BONUS_EXPIRE AS DT_BONUS_EXPIRE, @NO_BONUS_ITEM AS NO_BONUS_ITEM, @NO_LIMIT_BONUS_JOIN AS NO_LIMIT_BONUS_JOIN, @NO_LIMIT_ITEM_JOIN AS NO_LIMIT_ITEM_JOIN
*/
CREATE OR ALTER PROCEDURE [dbo].[EBI_BillEvent_CHK]
	@NO_CHARGE_CASH			int ,					-- 충전 금액
	@CD_EVENT				int	OUTPUT ,			-- 이벤트 고유번호
	@NO_CHARGE_BONUS		int OUTPUT ,			-- 충전 보너스 캐시
	@DT_BONUS_EXPIRE		smalldatetime OUTPUT ,	-- 충전 보너스 캐시 만료일
	@NO_BONUS_ITEM			bigint OUTPUT ,			-- 충전 보너스 아이템
	@NO_LIMIT_BONUS_JOIN	smallint OUTPUT ,		-- 보너스 지급 제한
	@NO_LIMIT_ITEM_JOIN		smallint OUTPUT			-- 보너스 아이템 지급 제한
AS
	SET NOCOUNT ON

	SELECT @CD_EVENT = CD_EVENT
	,	@NO_CHARGE_BONUS = CASE DI_VALUE_TYPE
			WHEN 0 THEN NO_BONUS_VALUE
			WHEN 1 THEN CAST(@NO_CHARGE_CASH * (NO_BONUS_VALUE / 100.0) AS int)	-- 소숫점 이하 버림
			ELSE 0 END
	,	@DT_BONUS_EXPIRE = CASE DI_EXPIRE_TYPE
			WHEN 'D' THEN CAST(DATEADD(DD, NO_EXPIRE_VALUE, GETDATE()) AS smalldatetime)
			WHEN 'M' THEN CAST(DATEADD(MM, NO_EXPIRE_VALUE, GETDATE()) AS smalldatetime)
			WHEN 'P' THEN CAST((LEFT(CAST(NO_EXPIRE_VALUE AS varchar(10)), 4) + '-'
						+ SUBSTRING(CAST(NO_EXPIRE_VALUE AS varchar(10)), 5, 2) + '-'
						+ ISNULL(NULLIF(SUBSTRING(CAST(NO_EXPIRE_VALUE AS varchar(10)), 7, 2), ''), '01') + ' '
						+ ISNULL(NULLIF(SUBSTRING(CAST(NO_EXPIRE_VALUE AS varchar(10)), 9, 2), ''), '00') + ':00:00') AS smalldatetime)
			ELSE NULL END
	,	@NO_BONUS_ITEM = NO_BONUS_ITEM
	,	@NO_LIMIT_BONUS_JOIN = NO_LIMIT_BONUS_JOIN
	,	@NO_LIMIT_ITEM_JOIN = NO_LIMIT_ITEM_JOIN
	FROM dbo.EB_BillEvent AS A WITH(NOLOCK)
	JOIN (
		SELECT MAX(CD_EVENT) AS CD_EVENT_MAX
		FROM dbo.EB_BillEvent WITH(NOLOCK)
		WHERE CAST(GETDATE() AS smalldatetime) BETWEEN DT_EVENT_START_DATE AND DT_EVENT_END_DATE
		AND NO_LIMIT_CHARGE <= @NO_CHARGE_CASH AND DI_FLAG = 'A'
	) AS B
	ON A.CD_EVENT = B.CD_EVENT_MAX

	IF @@ROWCOUNT = 0
		SELECT @CD_EVENT = 0, @NO_CHARGE_BONUS = 0, @NO_BONUS_ITEM = 0, @DT_BONUS_EXPIRE = NULL, @NO_LIMIT_BONUS_JOIN = 0, @NO_LIMIT_ITEM_JOIN = 0
GO
CREATE OR ALTER PROCEDURE [dbo].[EBP_BuyCashItemLockerCount_CHK]
	@CD_USERUID				bigint ,			-- 계정 UID
	@NO_SERVER_SET_ID		tinyint ,			-- 서버 그룹
	@NO_PRODUCT_COUNT		INT = 1,			-- 여러개 수량 구매
	@DI_OUTPUT_RECORD		bit = 0,			-- 결과 RecordSet 출력 여부
	@NO_MAX_KEEP_COUNT		int = 200			-- 최대 보관 갯수(기본 값 200)
AS
	SET NOCOUNT ON

	-- 사용 변수 선언
	DECLARE @Result				int
	DECLARE @NO_LOCKER_COUNT	INT
	
	SELECT @NO_LOCKER_COUNT = COUNT(*)
	FROM dbo.EB_BuyCashItemLocker WITH(NOLOCK)
	WHERE CD_USERUID = @CD_USERUID AND NO_SERVER_SET_ID = @NO_SERVER_SET_ID
	
	IF @NO_LOCKER_COUNT + @NO_PRODUCT_COUNT > @NO_MAX_KEEP_COUNT AND @NO_MAX_KEEP_COUNT > 0 BEGIN	-- @NO_MAX_KEEP_COUNT 가 0 이면 무제한
		-- 보관함 보관 갯수 초과 오류
		SET @Result = -22
	END
	ELSE BEGIN
		SET @Result = 0
	END
	
END_PROC:
	IF @DI_OUTPUT_RECORD = 1
		SELECT @Result AS Result
	
	RETURN @Result
GO
/*
프로시저명 : dbo.EBP_BuyCashItemLocker_SEL
내용 : 캐시 아이템 보관함
작성일 : 2011-02-22
작성자 : 김병일
-- ## 관련 테이블 ##--
