	EXEC dbo.EBP_BuyCashItemLocker_SEL @CD_USERUID, @NO_SERVER_SET_ID
-- ## 참고 SP ## --
	dbo.bup_get_order_info
*/
CREATE OR ALTER PROCEDURE [dbo].[EBP_BuyCashItemLocker_SEL]
	@CD_USERUID				bigint ,			-- 계정 UID
	@NO_SERVER_SET_ID		tinyint				-- 서버 그룹
