/*
프로시저명 : dbo.EBP_BuyCashItemLocker_Package_SEL
내용 : 캐시 아이템 보관함 구매 패키지의 잔여 구성물 확인
작성일 : 2011-09-15
작성자 : 김병일
-- ## 관련 테이블 ##--
	dbo.EB_BuyCashItemLockerPackage
	dbo.EB_BuyCashItemLocker
-- ## 관련 프로시저 ## --
	없음
-- ## 입력 ## --
	@CD_USERUID					bigint			-- 계정 UID
	@NO_SERVER_SET_ID			tinyint			-- 서버 그룹
-- ## 출력 ## --
	Output : 없음
	ReturnValue : 없음
	RecodeSet : 선택
		CD_TRAN_NUM, NO_PRODUCT_NUM
		거래 고유번호, 아이템 고유번호
-- ## 실행 ## --
	DECLARE @CD_USERUID			bigint			-- 계정 UID
	,	@NO_SERVER_SET_ID		tinyint

	SELECT TOP 1 @CD_USERUID = CD_USERUID, @NO_SERVER_SET_ID = NO_SERVER_SET_ID
	FROM dbo.EB_BuyCashItemLocker WITH(NOLOCK)
	ORDER BY NEWID()

	EXEC dbo.EBP_BuyCashItemLocker_Package_SEL @CD_USERUID, @NO_SERVER_SET_ID
-- ## 참고 SP ## --
	dbo.bup_get_order_info
*/
CREATE OR ALTER PROCEDURE [dbo].[EBP_BuyCashItemLocker_Package_SEL]
	@CD_USERUID						bigint				-- 계정 UID
,	@NO_SERVER_SET_ID				tinyint				-- 서버 그룹
AS
	SET NOCOUNT ON

	SELECT CD_TRAN_NUM, NO_PRODUCT_NUM
	FROM dbo.EB_BuyCashItemLockerPackage AS A WITH(NOLOCK)
	WHERE EXISTS ( SELECT * FROM dbo.EB_BuyCashItemLocker WITH(NOLOCK) WHERE CD_TRAN_NUM = A.CD_TRAN_NUM AND CD_USERUID = @CD_USERUID AND NO_SERVER_SET_ID = @NO_SERVER_SET_ID )
GO
--구매제한 체크

CREATE OR ALTER PROCEDURE [dbo].[EBP_Buy_Product_LimitedUser_CHK]
	@CD_PRODUCTNO		bigint ,				-- 상품 고유번호
	@CD_USERUID			bigint ,				-- 계정 UID
	@NO_SERVER_SET_ID	tinyint ,				-- 서버 그룹
	@CD_PRODUCT_SM		int = NULL	OUTPUT ,	-- 상품 추가 설정 고유번호
	@NO_LIMIT_COUNT		int = NULL	OUTPUT ,	-- 구매 제한 수량
	@DI_OUTPUT_RECORD	bit = 1					-- 결과 RecordSet 출력 여부
AS
SET NOCOUNT ON

DECLARE @Result				int
DECLARE @NowDate		SMALLDATETIME
SET @NowDate = GETDATE()

-- 동일 기간 중복 항목 제거 (가장 마지막에 등록된 설정만 적용)
SELECT @CD_PRODUCT_SM = MAX(CD_PRODUCT_SM)
FROM dbo.EB_ProductLimit WITH(NOLOCK)
WHERE CD_PRODUCTNO = @CD_PRODUCTNO
AND @NowDate >= DT_STARTDATE 
AND @NowDate < DT_ENDDATE



IF @@ROWCOUNT = 1 BEGIN
	SELECT @NO_LIMIT_COUNT = NO_LIMIT_COUNT
	FROM dbo.EB_ProductLimit WITH(NOLOCK)
	WHERE CD_PRODUCT_SM = @CD_PRODUCT_SM
	
	SELECT @Result = CASE WHEN NO_BUY_COUNT < @NO_LIMIT_COUNT THEN 0 ELSE -26 END
	FROM dbo.EB_BuyCashItemLimited_User WITH(NOLOCK)
	WHERE CD_PRODUCT_SM = @CD_PRODUCT_SM AND CD_USERUID = @CD_USERUID
		AND NO_SERVER_SET_ID = @NO_SERVER_SET_ID

	IF @@ROWCOUNT = 0
		SET @Result = 0
END
ELSE
	SET @Result = 0

IF @DI_OUTPUT_RECORD = 1
	SELECT @Result AS Result

RETURN @Result
GO
/*
프로시저명 : dbo.EBP_BillEvent_SEL
내용 : 등록된 이벤트 목록
작성일 : 2011-10-04
작성자 : 김병일
-- ## 관련 테이블 ##--
	dbo.EB_BillEvent
-- ## 관련 프로시저 ## --
	없음
-- ## 입력 ## --
	없음
-- ## 출력 ## --
	Output : 없음
	ReturnValue : 없음
	RecodeSet : 선택
		DT_EVENT_START_DATE, DT_EVENT_END_DATE, DBTime
		이벤트 시작 일시, 이벤트 종료 일시, DB현재 시간
-- ## 실행 ## --
	EXEC dbo.EBP_BillEvent_SEL
*/
CREATE OR ALTER PROCEDURE [dbo].[EBP_BillEvent_SEL]
AS
	SET NOCOUNT ON

	SELECT CONVERT(varchar(19), DT_EVENT_START_DATE, 120) AS DT_EVENT_START_DATE
	, CONVERT(varchar(19), DT_EVENT_END_DATE, 120) AS DT_EVENT_END_DATE
	, CONVERT(varchar(19), GETDATE(), 120) AS DBTime
	FROM dbo.EB_BillEvent WITH(NOLOCK)
	WHERE DT_EVENT_END_DATE > GETDATE() AND DI_FLAG = 'A'
GO
/*
프로시저명 : dbo.EBJ_ProductShopManager_SET
내용 : 캐시샵 상품 On/Off
작성일 : 2011-10-25
작성자 : KOG_M
-- ## 관련 테이블 ##--
	dbo.EB_ProductShopManager / dbo.EB_Product / dbo.EB_ReleaseTick
-- ## 관련 프로시저 ## --
	없음
-- ## 입력 ## --
	@getDate		smalldatetime		-- 일시
-- ## 출력 ## --
	Output : 없음
	ReturnValue : 없음
	RecodeSet : 없음
-- ## 실행 ## --
	EXEC dbo.EBJ_ProductShopManager_SET
-- ## JOB Name : ProductShopManager ## --
-- ## JOB Time : Every 10 minimuminus ## --
*/
CREATE OR ALTER PROCEDURE [dbo].[EBJ_ProductShopManager_SET]
	@getDate	smalldatetime = NULL		-- 일시
AS
	SET NOCOUNT ON
	
	DECLARE @NowDay		char(8)
	,	@NowTime		char(4)
	
	IF @getDate IS NULL
		SET @getDate = GETDATE()
	
	-- 주 시작일 확인(월요일이 1이 아니면 월요일을 1로 지정
	IF DATEPART(dw, '2007-01-01') <> 1
		SET DATEFIRST 1
	
	SET @NowDay = CONVERT(char(8), @getDate, 112)
	SET @NowTime = REPLACE(CONVERT(char(5), @getDate, 114), ':', '')

	UPDATE dbo.EB_Product
	SET DI_ISSHOW = B.DI_ISSHOW
	,	DT_ENDDATE = CASE WHEN B.DI_ISSHOW = 1 THEN '2050-12-01 00:00:00' ELSE GETDATE() END
	FROM dbo.EB_Product AS A WITH(NOLOCK)
	JOIN (
		SELECT CD_PRODUCTNO
			, CASE
			WHEN DI_RUN_TYPE = 1 THEN CASE 
				WHEN @getDate >= DATEADD(mi, CAST(RIGHT(DI_STARTTIME, 2) AS tinyint), DATEADD(hh, CAST(RIGHT('0'+LEFT(DI_STARTTIME, LEN(DI_STARTTIME)-2), 2) AS tinyint), DI_STARTDATE))
					AND @getDate < DATEADD(mi, CAST(RIGHT(DI_ENDTIME, 2) AS tinyint), DATEADD(hh, CAST(RIGHT('0'+LEFT(DI_ENDTIME, LEN(DI_ENDTIME)-2), 2) AS tinyint), DI_ENDDATE)) THEN 1
				ELSE 0 END
			WHEN DI_RUN_TYPE = 4 THEN CASE 
				WHEN DATEDIFF(dd, @NowDay, DI_STARTDATE) % DI_RUN_INTERVAL = 0
					AND DI_STARTTIME <= @NowTime AND DI_ENDTIME > @NowTime THEN 1
				ELSE 0 END
			WHEN DI_RUN_TYPE = 8 THEN CASE 
				WHEN DI_STARTTIME <= @NowTime AND DI_ENDTIME > @NowTime THEN CASE
					WHEN DI_RUN_INTERVAL & CASE DATEPART(dw, @getDate) 
						WHEN 1 THEN 1
						WHEN 2 THEN 2
						WHEN 3 THEN 4
						WHEN 4 THEN 8
						WHEN 5 THEN 16
						WHEN 6 THEN 32
						WHEN 7 THEN 64
						ELSE 0 END = 0 THEN 0
					ELSE 1 END
				ELSE 0 END
			WHEN DI_RUN_TYPE = 16 THEN CASE 
				WHEN DI_STARTTIME <= @NowTime AND DI_ENDTIME > @NowTime AND DI_RUN_INTERVAL = DATEPART(dd, @getDate) THEN 1
				ELSE 0 END
			ELSE 0 END AS DI_ISSHOW
			, DATEADD(mi, CAST(RIGHT(DI_STARTTIME, 2) AS tinyint), DATEADD(hh, CAST(RIGHT('0'+LEFT(DI_STARTTIME, LEN(DI_STARTTIME)-2), 2) AS tinyint), DI_STARTDATE)) AS DI_STARTDATE
			, DATEADD(mi, CAST(RIGHT(DI_ENDTIME, 2) AS tinyint), DATEADD(hh, CAST(RIGHT('0'+LEFT(DI_ENDTIME, LEN(DI_ENDTIME)-2), 2) AS tinyint), DI_ENDDATE)) AS DI_ENDDATE
		FROM dbo.EB_ProductShopManager AS A WITH(NOLOCK)
		JOIN (
			-- 동일 기간 중복 항목 제거 (가장 마지막에 등록된 설정만 적용)
			SELECT MAX(CD_PRODUCT_SM) AS CD_PRODUCT_SM
			FROM dbo.EB_ProductShopManager WITH(NOLOCK)
			WHERE @NowDay BETWEEN DI_STARTDATE AND DI_ENDDATE
				AND @getDate BETWEEN DATEADD(mi, CAST(RIGHT(DI_STARTTIME, 2) AS tinyint), DATEADD(hh, CAST(RIGHT('0'+LEFT(DI_STARTTIME, LEN(DI_STARTTIME)-2), 2) AS tinyint), DI_STARTDATE))
					AND DATEADD(mi, CAST(RIGHT(DI_ENDTIME, 2) AS tinyint), DATEADD(hh, CAST(RIGHT('0'+LEFT(DI_ENDTIME, LEN(DI_ENDTIME)-2), 2) AS tinyint), DI_ENDDATE))
			GROUP BY CD_PRODUCTNO
		) AS B
		ON A.CD_PRODUCT_SM = B.CD_PRODUCT_SM
	) AS B
	ON A.CD_PRODUCTNO = B.CD_PRODUCTNO
		AND A.DI_ISSHOW <> B.DI_ISSHOW
	
	IF @@ROWCOUNT > 0 BEGIN
		UPDATE dbo.EB_ReleaseTick
		SET NO_Tick = NO_Tick + 1
		,	DT_SetDate = @getDate
		WHERE DI_TickType = 0
	END
GO
/*
프로시저명 : dbo.EBI_SP_ErrorLog_INT
내용 : DB 오류 기록
작성일 : 2011-02-11
작성자 : 김병일
-- ## 관련 테이블 ##--
	dbo.EB_SP_ErrorLog
-- ## 관련 프로시저 ## --
	없음
-- ## 입력 ## --
	@NO_XACT_STATE		smallint					-- 트랜잭션 상태 정보
-- ## 출력 ## --
	Output : 없음
	ReturnValue : 없음
	RecodeSet : 없음
-- ## 예제 ## --
	IF OBJECT_ID('_TestTable') IS NOT NULL
		DROP TABLE dbo.[_TestTable]

	CREATE TABLE dbo.[_TestTable] (
		col1			int
	)

	SELECT * FROM dbo.[_TestTable]

	BEGIN TRY
		BEGIN TRAN

		INSERT INTO dbo.[_TestTable]
		VALUES (1/0)

		COMMIT TRAN AL
	END TRY
	BEGIN CATCH
		DECLARE @NO_XACT_STATE		smallint
		SET @NO_XACT_STATE			= XACT_STATE()		-- 트랜잭션 상태 정보

		IF @NO_XACT_STATE <> 0
			ROLLBACK TRAN

		EXEC dbo.EBI_SP_ErrorLog_INT @NO_XACT_STATE
	END CATCH

	SELECT * FROM dbo.[_TestTable]
	SELECT * FROM dbo.EB_SP_ErrorLog
*/
CREATE OR ALTER PROCEDURE [dbo].[EBI_SP_ErrorLog_INT]
	@NO_XACT_STATE		smallint ,					-- 트랜잭션 상태 정보
	@ST_SYSTEM_USER		nvarchar(128) = NULL		-- 사용자 계정(DB 접속 계정)
AS
	SET NOCOUNT ON

	-- 변수 선언
	DECLARE	@NO_ERROR_LINE		int,
		@ST_ERROR_MESSAGE		nvarchar(2048),
		@ST_ERROR_PROCEDURE		nvarchar(126),
		@NO_ERROR_NUMBER		int,
		@NO_ERROR_SEVERITY		int,
		@NO_ERROR_STATE			int

	-- 변수 값 입력
	SET @NO_ERROR_LINE			= ERROR_LINE()		-- 오류 발생 줄
	SET @ST_ERROR_MESSAGE		= ERROR_MESSAGE()	-- 오류 메시지
	SET @ST_ERROR_PROCEDURE		= ERROR_PROCEDURE()	-- 오류 프로시저명
	SET @NO_ERROR_NUMBER		= ERROR_NUMBER()	-- 오류 번호
	SET @NO_ERROR_SEVERITY		= ERROR_SEVERITY()	-- 오류 심각도
	SET @NO_ERROR_STATE			= ERROR_STATE()		-- 오류 상태 번호

	IF @ST_SYSTEM_USER IS NULL
		SET @ST_SYSTEM_USER = SYSTEM_USER

	BEGIN TRY
		-- 저장
		INSERT INTO dbo.EB_SP_ErrorLog ( NO_ERROR_LINE, ST_ERROR_MESSAGE, NO_ERROR_NUMBER, ST_ERROR_PROCEDURE, NO_ERROR_SEVERITY, NO_ERROR_STATE, NO_XACT_STATE, ST_SYSTEM_USER, DT_ERROR_DATE )
		VALUES ( @NO_ERROR_LINE, @ST_ERROR_MESSAGE, @NO_ERROR_NUMBER, @ST_ERROR_PROCEDURE, @NO_ERROR_SEVERITY, @NO_ERROR_STATE, @NO_XACT_STATE, @ST_SYSTEM_USER, GETDATE() )
	END TRY
	BEGIN CATCH
		-- 저장 실패시 오류 로그에 기록
		RAISERROR(N'Procedure error [SP-%s][NUM-%d][MSG-%s][LINE-%d][USER-%s]', 16, @NO_ERROR_STATE, @ST_ERROR_PROCEDURE, @NO_ERROR_NUMBER, @ST_ERROR_MESSAGE, @NO_ERROR_LINE, @ST_SYSTEM_USER) WITH LOG
	END CATCH
GO
/*
프로시저명 : dbo.EBI_CashLog_INT
내용 : 캐시 충전/소진 로그 기록
작성일 : 2011-02-21
작성자 : 김병일
-- ## 관련 테이블 ##--
	dbo.EB_CashLog
-- ## 관련 프로시저 ## --
	없음
-- ## 입력 ## --
	@CD_TRAN_NUM			bigint			-- 거래 고유번호
	@ST_TRANSACTION			varchar(50)		-- 처리열 고유 문자
	@CD_USERUID				bigint			-- 계정 UID
	@ST_USERID				nvarchar(50)	-- 계정 아이디
	@NO_SERVER_SET_ID		tinyint			-- 서버 그룹
	@NO_UNITUID				bigint			-- 캐릭터 UID
	@NO_LEVEL				tinyint			-- 캐릭터 래벨
	@DI_CASH_LOG_TYPE		smallint			-- 처리 구분
	@NO_PRODUCT_NUM			int				-- 상품 고유 번호
	@NO_QUANTITY			smallint		-- 상품 수량
	@NO_CASH_VALUE			int				-- 캐시 금액
	@NO_BONUS_VALUE			int				-- 보너스 금액
	@NO_REMAIN_CASH			int				-- 처리 후 잔여 캐시
	@NO_REMAIN_BONUS		int				-- 처리 후 잔여 보너스
	@DT_LOG_DATE			datetime		-- 처리 일시
-- ## 출력 ## --
	Output : 없음
	ReturnValue : 있음
	RecodeSet : 없음
-- ## 실행 ## --
	DECLARE @Result	int
	,	@CD_TRAN_NUM			bigint			-- 거래 고유번호
	,	@ST_TRANSACTION			varchar(50)		-- 처리열 고유 문자
	,	@CD_USERUID				bigint			-- 계정 UID
	,	@ST_USERID				nvarchar(50)	-- 계정 아이디
	,	@NO_SERVER_SET_ID		tinyint			-- 서버 그룹
	,	@NO_UNITUID				bigint			-- 캐릭터 UID
	,	@NO_LEVEL				tinyint			-- 캐릭터 래벨
	,	@NO_TO_USERUID			bigint			-- 받는 계정 UID
	,	@NO_TO_UNITUID			bigint			-- 받는 캐릭터 UID
	,	@DI_CASH_LOG_TYPE		smallint		-- 처리 구분
	,	@NO_PRODUCT_NUM			int				-- 상품 고유 번호
	,	@NO_QUANTITY			smallint		-- 상품 수량
	,	@NO_CASH_VALUE			int				-- 캐시 금액
	,	@NO_BONUS_VALUE			int				-- 보너스 금액
	,	@NO_REMAIN_CASH			int				-- 처리 후 잔여 캐시
	,	@NO_REMAIN_BONUS		int				-- 처리 후 잔여 보너스
	,	@DT_LOG_DATE			datetime		-- 처리 일시
	,	@DI_ORDER_TYPE			smallint				-- 주문 종류

	SELECT @DI_CASH_LOG_TYPE = CAST(RAND() * 7 AS tinyint) + 1
	,	@CD_USERUID = CAST((CAST(RAND() * 10000000000 AS bigint) / (CAST(RAND() * 100 AS tinyint) + 1)) AS bigint) + 1
	,	@NO_SERVER_SET_ID = CAST(RAND() * 10 / 2 AS tinyint) + 1
	,	@NO_UNITUID = CAST((CAST(RAND() * 10000000000 AS bigint) / (CAST(RAND() * 100 AS tinyint) + 1)) AS bigint) + 1
	,	@NO_LEVEL = CAST(RAND() * 58 AS tinyint) + 1
	,	@NO_TO_USERUID = CASE WHEN CAST(RAND() * 2 AS tinyint) = 1 THEN CAST((CAST(RAND() * 10000000000 AS bigint) / (CAST(RAND() * 100 AS tinyint) + 1)) AS bigint) + 1 ELSE 0 END
	,	@NO_PRODUCT_NUM = CAST(RAND() * 10000 AS int)
	,	@NO_QUANTITY = 1
	,	@NO_CASH_VALUE = CAST(RAND() * 100 AS INT) * 10 + 10
	,	@NO_BONUS_VALUE = CAST(RAND() * 100 AS INT) * 10 + 10
	,	@NO_REMAIN_CASH = CAST(RAND() * 100 AS INT) * 10 + 100
	,	@NO_REMAIN_BONUS = CAST(RAND() * 100 AS INT) * 10 + 100
	,	@DT_LOG_DATE = GETDATE()

	SET @ST_TRANSACTION		= LEFT(REPLACE(REPLACE(REPLACE(REPLACE(CONVERT(varchar(23), GETDATE(), 121), '-', ''), ' ', ''), ':', ''), '.', '') + RIGHT(CAST(@CD_USERUID AS varchar(10)), 10) + RIGHT('0000000000' + CAST(CAST(RAND() * 100000000000000000 AS bigint) + 1 AS varchar(20)), 10), 20)
	SET @ST_USERID = 'TestAcc' + CAST(@CD_USERUID AS varchar(12))
	IF @NO_TO_USERUID > 0 BEGIN
		SET @NO_TO_UNITUID = CAST((CAST(RAND() * 10000000000 AS bigint) / (CAST(RAND() * 100 AS tinyint) + 1)) AS bigint) + 1
		SET @DI_CASH_LOG_TYPE = CASE WHEN @NO_TO_USERUID > 0 THEN -10 ELSE -1 END
		SET @ST_TRANSACTION = N'B'+@ST_TRANSACTION
	END
	ELSE BEGIN
		SET @NO_TO_UNITUID = 0
		SET @ST_TRANSACTION = N'0'+@ST_TRANSACTION
	END

	EXEC dbo.EBI_TransactionNumber_INT @DI_CASH_LOG_TYPE, @CD_TRAN_NUM OUTPUT

	EXEC @Result = dbo.EBI_CashLog_INT @CD_TRAN_NUM, @ST_TRANSACTION, @CD_USERUID, @ST_USERID, @NO_SERVER_SET_ID, @NO_UNITUID, @NO_LEVEL, @NO_TO_USERUID, @NO_TO_UNITUID, @DI_CASH_LOG_TYPE, @NO_PRODUCT_NUM, @NO_QUANTITY, @NO_CASH_VALUE, @NO_BONUS_VALUE, @NO_REMAIN_CASH, @NO_REMAIN_BONUS, @DT_LOG_DATE
	SELECT @Result AS Result
*/
CREATE OR ALTER PROCEDURE [dbo].[EBI_CashLog_INT]
	@CD_TRAN_NUM			bigint ,			-- 거래 고유번호
	@ST_TRANSACTION			varchar(50) ,		-- 처리열 고유 문자
	@ST_GROUP_TRANSACTION	varchar(50) ,		-- 그룹별 발행 주문번호 (퍼블리셔 대조용) (2013-04-30 추가)
	@CD_USERUID				bigint ,			-- 계정 UID
	@ST_USERID				nvarchar(50) ,		-- 계정 아이디
	@NO_SERVER_SET_ID		tinyint ,			-- 서버 그룹
	@NO_UNITUID				bigint ,			-- 캐릭터 UID
	@NO_LEVEL				tinyint ,			-- 캐릭터 래벨
	@NO_TO_USERUID			bigint ,			-- 받는 계정 UID
	@NO_TO_UNITUID			bigint ,			-- 받는 캐릭터 UID
	@DI_CASH_LOG_TYPE		smallint ,			-- 처리 구분
	@NO_PRODUCT_NUM			bigint ,			-- 상품 고유 번호
	@NO_QUANTITY			smallint ,			-- 상품 수량
	@NO_CASH_VALUE			int ,				-- 캐시 금액
	@NO_BONUS_VALUE			int ,				-- 보너스 금액
	@NO_REMAIN_CASH			int ,				-- 처리 후 잔여 캐시
	@NO_REMAIN_BONUS		int ,				-- 처리 후 잔여 보너스
	@DT_LOG_DATE			datetime = NULL,	-- 처리 일시
	@NO_CHANNEL_CODE		tinyint = 0 		-- 채널링 코드 (2013-05-11 추가)
AS
	SET NOCOUNT ON

	-- 사용 변수 선언
	DECLARE @Result					int
	, @NO_CASH_TOTAL				int			-- 총 변경 캐시

	SET @NO_CASH_TOTAL = @NO_CASH_VALUE + @NO_BONUS_VALUE

	IF @DT_LOG_DATE IS NULL
		SET @DT_LOG_DATE = GETDATE()

	-- 캐시 내역 기록
	INSERT INTO dbo.EB_CashLog ( CD_TRAN_NUM, ST_TRANSACTION, ST_GROUP_TRANSACTION, NO_CHANNEL_CODE, CD_USERUID, ST_USERID, NO_SERVER_SET_ID, NO_UNITUID, NO_LEVEL, NO_TO_USERUID, NO_TO_UNITUID, DI_CASH_LOG_TYPE, NO_PRODUCT_NUM, NO_QUANTITY, NO_CASH_TOTAL, NO_CASH_VALUE, NO_BONUS_VALUE, NO_REMAIN_CASH, NO_REMAIN_BONUS, DT_LOG_DATE )
	VALUES ( @CD_TRAN_NUM, @ST_TRANSACTION, @ST_GROUP_TRANSACTION, @NO_CHANNEL_CODE, @CD_USERUID, @ST_USERID, @NO_SERVER_SET_ID, @NO_UNITUID, @NO_LEVEL, @NO_TO_USERUID, @NO_TO_UNITUID, @DI_CASH_LOG_TYPE, @NO_PRODUCT_NUM, @NO_QUANTITY, @NO_CASH_TOTAL, @NO_CASH_VALUE, @NO_BONUS_VALUE, @NO_REMAIN_CASH, @NO_REMAIN_BONUS, @DT_LOG_DATE )

	RETURN @@ERROR
GO
/*
프로시저명 : dbo.EBI_Cash_UseRealCashOnly
내용 : 리얼 캐시 사용(아이템 구매 - 리얼 캐시 차감)
작성일 : 2011-09-28
작성자 : 김병일
-- ## 관련 테이블 ##--
	dbo.EB_Cash
-- ## 관련 프로시저 ## --
	없음
-- ## 입력 ## --
	@CD_USERUID			bigint			-- 계정 UID
	@ST_USERID			nvarchar(50)	-- 계정 아이디
	@NO_PRICE			int				-- 구매 금액
	@DT_USE_DATE		datetime		-- 사용 일시
-- ## 출력 ## --
	Output :
		@NO_REMAIN_CASH		int				-- 잔여 캐시
		@NO_REMAIN_BONUS	int				-- 잔여 보너스
		@NO_BEFOR_CASH		int				-- 사용전 캐시
		@NO_BEFOR_BONUS		int				-- 사용전 보너스
	ReturnValue : 있음
	RecodeSet : 없음
-- ## 실행 ## --
	DECLARE @Result			int
	,	@CD_USERUID			bigint			-- 계정 UID
	,	@ST_USERID			nvarchar(50)	-- 계정 아이디
	,	@NO_PRICE			int				-- 구매 금액
	,	@DT_USE_DATE		datetime		-- 사용 일시
	,	@NO_REMAIN_CASH		int				-- 잔여 캐시
	,	@NO_REMAIN_BONUS	int				-- 잔여 보너스
	,	@NO_BEFOR_CASH		int				-- 사용전 캐시
	,	@NO_BEFOR_BONUS		int				-- 사용전 보너스

	SELECT TOP 1 @CD_USERUID = CD_USERUID, @ST_USERID = ST_USERID
	,	@NO_PRICE = CASE WHEN CAST((RAND() * 10) / 2 AS tinyint) = 1 THEN 1 ELSE NO_REMAIN_CASH + 1 END
	,	@DT_USE_DATE = GETDATE()
	FROM dbo.EB_Cash WITH(NOLOCK)
	ORDER BY NEWID()

	IF @@ROWCOUNT = 1 AND @NO_PRICE > 0 BEGIN
		EXEC @Result = dbo.EBI_Cash_UseRealCashOnly @CD_USERUID, @ST_USERID, @NO_PRICE, @DT_USE_DATE, @NO_REMAIN_CASH OUTPUT, @NO_REMAIN_BONUS OUTPUT, @NO_BEFOR_CASH OUTPUT, @NO_BEFOR_BONUS OUTPUT
		
		SELECT @Result AS Result, @NO_REMAIN_CASH AS NO_REMAIN_CASH, @NO_REMAIN_BONUS AS NO_REMAIN_BONUS, @NO_BEFOR_CASH AS NO_BEFOR_CASH, @NO_BEFOR_BONUS AS NO_BEFOR_BONUS
	END

	SELECT *, @NO_PRICE AS NO_PRICE
	FROM dbo.EB_Cash WITH(NOLOCK)
	WHERE CD_USERUID = @CD_USERUID
*/
CREATE OR ALTER PROCEDURE [dbo].[EBI_Cash_UseRealCashOnly]
	@CD_USERUID			bigint ,				-- 계정 UID
	@ST_USERID			nvarchar(50) ,			-- 계정 아이디
	@NO_PRICE			int ,					-- 구매 금액
	@DT_USE_DATE		datetime ,				-- 사용 일시
	@NO_REMAIN_CASH		int OUTPUT ,			-- 잔여 캐시
	@NO_REMAIN_BONUS	int OUTPUT ,			-- 잔여 보너스
	@NO_BEFOR_CASH		int OUTPUT ,			-- 사용전 캐시
	@NO_BEFOR_BONUS		int OUTPUT				-- 사용전 보너스
AS
	SET NOCOUNT ON

	UPDATE dbo.EB_Cash
	SET @NO_REMAIN_CASH = NO_REMAIN_CASH = (NO_REMAIN_CASH - @NO_PRICE)			-- 리얼캐시 차감
	,	DT_USE_DATE = @DT_USE_DATE												-- 최종 사용일 갱신
	,	@NO_BEFOR_CASH = NO_REMAIN_CASH
	,	@NO_BEFOR_BONUS = NO_REMAIN_BONUS										-- 보너스 확인
	,	@NO_REMAIN_BONUS = NO_REMAIN_BONUS										-- 보너스 확인
	WHERE CD_USERUID = @CD_USERUID AND ST_USERID = @ST_USERID
		AND NO_REMAIN_CASH >= @NO_PRICE

	IF @@ROWCOUNT = 0 BEGIN
		IF @NO_PRICE > 0
			SELECT @NO_REMAIN_CASH = -1, @NO_REMAIN_BONUS = -1, @NO_BEFOR_CASH = 0, @NO_BEFOR_BONUS = 0
		ELSE
			SELECT @NO_REMAIN_CASH = 0, @NO_REMAIN_BONUS = 0, @NO_BEFOR_CASH = 0, @NO_BEFOR_BONUS = 0
	END

	RETURN @@ERROR
GO
/*
프로시저명 : dbo.EBI_Cash_UseFirstCash
내용 : 캐시 사용(아이템 구매 - 캐시 우선 차감)
작성일 : 2011-02-21
작성자 : 김병일
-- ## 관련 테이블 ##--
	dbo.EB_Cash
-- ## 관련 프로시저 ## --
	없음
-- ## 입력 ## --
	@CD_USERUID			bigint			-- 계정 UID
	@ST_USERID			nvarchar(50)	-- 계정 아이디
	@NO_PRICE			int				-- 구매 금액
	@DT_USE_DATE		datetime		-- 사용 일시
-- ## 출력 ## --
	Output :
		@NO_REMAIN_CASH		int				-- 잔여 캐시
		@NO_REMAIN_BONUS	int				-- 잔여 보너스
		@NO_BEFOR_CASH		int				-- 사용전 캐시
		@NO_BEFOR_BONUS		int				-- 사용전 보너스
	ReturnValue : 있음
	RecodeSet : 없음
-- ## 실행 ## --
	DECLARE @Result			int
	,	@CD_USERUID			bigint			-- 계정 UID
	,	@ST_USERID			nvarchar(50)	-- 계정 아이디
	,	@NO_PRICE			int				-- 구매 금액
	,	@DT_USE_DATE		datetime		-- 사용 일시
	,	@NO_REMAIN_CASH		int				-- 잔여 캐시
	,	@NO_REMAIN_BONUS	int				-- 잔여 보너스
	,	@NO_BEFOR_CASH		int				-- 사용전 캐시
	,	@NO_BEFOR_BONUS		int				-- 사용전 보너스

	SELECT @CD_USERUID		= CAST((CAST(RAND() * 10000000000 AS bigint) / (CAST(RAND() * 100 AS tinyint) + 1)) AS bigint) + 1
	,	@NO_PRICE			= CAST(RAND() * 10 AS INT) * 10
	,	@DT_USE_DATE		= GETDATE()

	SET @ST_USERID			= 'TestAcc' + CAST(@CD_USERUID AS varchar(12))

	EXEC @Result = dbo.EBI_Cash_UseFirstCash @CD_USERUID, @ST_USERID, @NO_PRICE, @DT_USE_DATE, @NO_REMAIN_CASH OUTPUT, @NO_REMAIN_BONUS OUTPUT, @NO_BEFOR_CASH OUTPUT, @NO_BEFOR_BONUS OUTPUT
	SELECT @Result AS Result, @NO_REMAIN_CASH AS NO_REMAIN_CASH, @NO_REMAIN_BONUS AS NO_REMAIN_BONUS, @NO_BEFOR_CASH AS NO_BEFOR_CASH, @NO_BEFOR_BONUS AS NO_BEFOR_BONUS
*/
CREATE OR ALTER PROCEDURE [dbo].[EBI_Cash_UseFirstCash]
	@CD_USERUID			bigint ,				-- 계정 UID
	@ST_USERID			nvarchar(50) ,			-- 계정 아이디
	@NO_PRICE			int ,					-- 구매 금액
	@DT_USE_DATE		datetime ,				-- 사용 일시
	@NO_REMAIN_CASH		int OUTPUT ,			-- 잔여 캐시
	@NO_REMAIN_BONUS	int OUTPUT ,			-- 잔여 보너스
	@NO_BEFOR_CASH		int OUTPUT ,			-- 사용전 캐시
	@NO_BEFOR_BONUS		int OUTPUT				-- 사용전 보너스
AS
	SET NOCOUNT ON

	UPDATE dbo.EB_Cash
	SET NO_REMAIN_CASH = CASE
			WHEN NO_REMAIN_CASH < @NO_PRICE THEN 0			-- 캐시가 구매 금액 보다 작으면 0
			ELSE NO_REMAIN_CASH - @NO_PRICE END				-- 캐시 차감
	,	NO_REMAIN_BONUS = CASE
			WHEN NO_REMAIN_CASH < @NO_PRICE THEN CASE		-- 캐시가 구매 금액 보다 작으면 보너스 캐시 사용
				WHEN NO_REMAIN_BONUS < ( CASE WHEN NO_REMAIN_CASH = 0 THEN @NO_PRICE ELSE @NO_PRICE - NO_REMAIN_CASH END ) THEN -1		-- 보너스 캐시가 차감해야 하는 금액 보다 작으면 -1(잔액 부족)
				ELSE NO_REMAIN_BONUS - ( CASE WHEN NO_REMAIN_CASH = 0 THEN @NO_PRICE ELSE @NO_PRICE - NO_REMAIN_CASH END ) END			-- 보너스 캐시 차감
			ELSE NO_REMAIN_BONUS END						-- 보너스 차감 없음
	,	DT_USE_DATE = @DT_USE_DATE							-- 최종 사용일 갱신
	,	@NO_REMAIN_CASH = CASE								-- 캐시 차감과 같음
			WHEN NO_REMAIN_CASH < @NO_PRICE THEN 0
			ELSE NO_REMAIN_CASH - @NO_PRICE END
	,	@NO_REMAIN_BONUS = CASE								-- 보너스 차감과 동일
			WHEN NO_REMAIN_CASH < @NO_PRICE THEN CASE
				WHEN NO_REMAIN_BONUS < ( CASE WHEN NO_REMAIN_CASH = 0 THEN @NO_PRICE ELSE @NO_PRICE - NO_REMAIN_CASH END ) THEN -1
				ELSE NO_REMAIN_BONUS - ( CASE WHEN NO_REMAIN_CASH = 0 THEN @NO_PRICE ELSE @NO_PRICE - NO_REMAIN_CASH END ) END
			ELSE NO_REMAIN_BONUS END
	,	@NO_BEFOR_CASH = NO_REMAIN_CASH
	,	@NO_BEFOR_BONUS = NO_REMAIN_BONUS
	WHERE CD_USERUID = @CD_USERUID AND ST_USERID = @ST_USERID
		AND ((NO_REMAIN_CASH >= @NO_PRICE) OR (NO_REMAIN_BONUS >= (@NO_PRICE-NO_REMAIN_CASH)))

	IF @@ROWCOUNT = 0 BEGIN
		IF @NO_PRICE > 0
			SELECT @NO_REMAIN_CASH = -1, @NO_REMAIN_BONUS = -1, @NO_BEFOR_CASH = 0, @NO_BEFOR_BONUS = 0
		ELSE
			SELECT @NO_REMAIN_CASH = 0, @NO_REMAIN_BONUS = 0, @NO_BEFOR_CASH = 0, @NO_BEFOR_BONUS = 0
	END

	RETURN @@ERROR
GO
/*
프로시저명 : dbo.EBI_Cash_UseBonusCashOnly
내용 : 보너스 캐시 사용(아이템 구매 - 보너스 캐시 차감)
작성일 : 2011-09-28
작성자 : 김병일
-- ## 관련 테이블 ##--
	dbo.EB_Cash
-- ## 관련 프로시저 ## --
	없음
-- ## 입력 ## --
	@CD_USERUID			bigint			-- 계정 UID
	@ST_USERID			nvarchar(50)	-- 계정 아이디
	@NO_PRICE			int				-- 구매 금액
	@DT_USE_DATE		datetime		-- 사용 일시
-- ## 출력 ## --
	Output :
		@NO_REMAIN_CASH		int				-- 잔여 캐시
		@NO_REMAIN_BONUS	int				-- 잔여 보너스
		@NO_BEFOR_CASH		int				-- 사용전 캐시
		@NO_BEFOR_BONUS		int				-- 사용전 보너스
	ReturnValue : 있음
	RecodeSet : 없음
-- ## 실행 ## --
	DECLARE @Result			int
	,	@CD_USERUID			bigint			-- 계정 UID
	,	@ST_USERID			nvarchar(50)	-- 계정 아이디
	,	@NO_PRICE			int				-- 구매 금액
	,	@DT_USE_DATE		datetime		-- 사용 일시
	,	@NO_REMAIN_CASH		int				-- 잔여 캐시
	,	@NO_REMAIN_BONUS	int				-- 잔여 보너스
	,	@NO_BEFOR_CASH		int				-- 사용전 캐시
	,	@NO_BEFOR_BONUS		int				-- 사용전 보너스

	SELECT TOP 1 @CD_USERUID = CD_USERUID, @ST_USERID = ST_USERID
	,	@NO_PRICE = CASE WHEN CAST((RAND() * 10) / 2 AS tinyint) = 1 THEN 1 ELSE NO_REMAIN_BONUS + 1 END
	,	@DT_USE_DATE = GETDATE()
	FROM dbo.EB_Cash WITH(NOLOCK)
	ORDER BY NEWID()

	IF @@ROWCOUNT = 1 AND @NO_PRICE > 0 BEGIN
		EXEC @Result = dbo.EBI_Cash_UseBonusCashOnly @CD_USERUID, @ST_USERID, @NO_PRICE, @DT_USE_DATE, @NO_REMAIN_CASH OUTPUT, @NO_REMAIN_BONUS OUTPUT, @NO_BEFOR_CASH OUTPUT, @NO_BEFOR_BONUS OUTPUT
		
		SELECT @Result AS Result, @NO_REMAIN_CASH AS NO_REMAIN_CASH, @NO_REMAIN_BONUS AS NO_REMAIN_BONUS, @NO_BEFOR_CASH AS NO_BEFOR_CASH, @NO_BEFOR_BONUS AS NO_BEFOR_BONUS
	END

	SELECT *, @NO_PRICE AS NO_PRICE
	FROM dbo.EB_Cash WITH(NOLOCK)
	WHERE CD_USERUID = @CD_USERUID
*/
CREATE OR ALTER PROCEDURE [dbo].[EBI_Cash_UseBonusCashOnly]
	@CD_USERUID			bigint ,				-- 계정 UID
	@ST_USERID			nvarchar(50) ,			-- 계정 아이디
	@NO_PRICE			int ,					-- 구매 금액
	@DT_USE_DATE		datetime ,				-- 사용 일시
	@NO_REMAIN_CASH		int OUTPUT ,			-- 잔여 캐시
	@NO_REMAIN_BONUS	int OUTPUT ,			-- 잔여 보너스
	@NO_BEFOR_CASH		int OUTPUT ,			-- 사용전 캐시
	@NO_BEFOR_BONUS		int OUTPUT				-- 사용전 보너스
AS
	SET NOCOUNT ON

	UPDATE dbo.EB_Cash
	SET @NO_REMAIN_BONUS = NO_REMAIN_BONUS = (NO_REMAIN_BONUS - @NO_PRICE)		-- 보너스 차감
	,	DT_USE_DATE = @DT_USE_DATE												-- 최종 사용일 갱신
	,	@NO_BEFOR_BONUS = NO_REMAIN_BONUS
	,	@NO_REMAIN_CASH = NO_REMAIN_CASH										-- 리얼캐시 확인
	,	@NO_BEFOR_CASH = NO_REMAIN_CASH											-- 리얼캐시 확인
	WHERE CD_USERUID = @CD_USERUID AND ST_USERID = @ST_USERID
		AND NO_REMAIN_BONUS >= @NO_PRICE

	IF @@ROWCOUNT = 0 BEGIN
		IF @NO_PRICE > 0
			SELECT @NO_REMAIN_CASH = -1, @NO_REMAIN_BONUS = -1, @NO_BEFOR_CASH = 0, @NO_BEFOR_BONUS = 0
		ELSE
			SELECT @NO_REMAIN_CASH = 0, @NO_REMAIN_BONUS = 0, @NO_BEFOR_CASH = 0, @NO_BEFOR_BONUS = 0
	END

	RETURN @@ERROR
GO
/*
프로시저명 : dbo.EBI_Cash_Detial_SEL
내용 : 엘소드 캐시 상세 상태
작성일 : 2011-02-22
작성자 : 김병일
-- ## 관련 테이블 ##--
	dbo.EB_Cash
-- ## 관련 프로시저 ## --
	없음
-- ## 입력 ## --
	@CD_USERUID			bigint			-- 계정 UID
-- ## 출력 ## --
	Output :
		@NO_REMAIN_CASH			int			-- 총 잔여 캐시
		@NO_REMAIN_BONUS		int			-- 총 잔여 보너스
		@NO_TOTAL_CHARGE_CASH	int			-- 총 충전 캐시
		@NO_TOTAL_CHARGE_BONUS	int			-- 총 충전 보너스
	ReturnValue : 없음
	RecodeSet : 없음
-- ## 실행 ## --
	DECLARE @CD_USERUID			bigint		-- 계정 UID
	,	@NO_REMAIN_CASH			int			-- 총 잔여 캐시
	,	@NO_REMAIN_BONUS		int			-- 총 잔여 보너스
	,	@NO_TOTAL_CHARGE_CASH	int			-- 총 충전 캐시
	,	@NO_TOTAL_CHARGE_BONUS	int			-- 총 충전 보너스

	SELECT @CD_USERUID		= CAST((CAST(RAND() * 10000000000 AS bigint) / (CAST(RAND() * 100 AS tinyint) + 1)) AS bigint) + 1

	EXEC dbo.EBI_Cash_Detial_SEL @CD_USERUID, @NO_REMAIN_CASH OUTPUT, @NO_REMAIN_BONUS OUTPUT, @NO_TOTAL_CHARGE_CASH OUTPUT, @NO_TOTAL_CHARGE_BONUS OUTPUT
	SELECT @NO_REMAIN_CASH AS NO_REMAIN_CASH, @NO_REMAIN_BONUS AS NO_REMAIN_BONUS, @NO_TOTAL_CHARGE_CASH AS NO_TOTAL_CHARGE_CASH, @NO_TOTAL_CHARGE_BONUS AS NO_TOTAL_CHARGE_BONUS
*/
CREATE OR ALTER PROCEDURE [dbo].[EBI_Cash_Detial_SEL]
	@CD_USERUID				bigint ,				-- 계정 UID
	@NO_REMAIN_CASH			int = 0 OUTPUT ,		-- 총 잔여 캐시
	@NO_REMAIN_BONUS		int = 0 OUTPUT ,		-- 총 잔여 보너스
	@NO_TOTAL_CHARGE_CASH	int = 0 OUTPUT ,		-- 총 충전 캐시
	@NO_TOTAL_CHARGE_BONUS	int = 0 OUTPUT			-- 총 충전 보너스
AS
	SET NOCOUNT ON

	SELECT @NO_TOTAL_CHARGE_CASH = NO_TOTAL_CHARGE_CASH, @NO_TOTAL_CHARGE_BONUS = NO_TOTAL_CHARGE_BONUS, @NO_REMAIN_CASH = NO_REMAIN_CASH, @NO_REMAIN_BONUS = NO_REMAIN_BONUS
	FROM dbo.EB_Cash WITH(NOLOCK)
	WHERE CD_USERUID = @CD_USERUID

	IF @@ROWCOUNT = 0
		SELECT @NO_REMAIN_CASH = 0, @NO_REMAIN_BONUS = 0, @NO_TOTAL_CHARGE_CASH = 0, @NO_TOTAL_CHARGE_BONUS = 0
GO
/*
프로시저명 : dbo.EBI_Cash_Charge_SET
내용 : 캐시 충전
작성일 : 2011-03-09
작성자 : 김병일
-- ## 관련 테이블 ##--
	dbo.EB_Cash
-- ## 관련 프로시저 ## --
	없음
-- ## 입력 ## --
	@CD_USERUID				bigint			-- 계정 UID
	@ST_USERID				nvarchar(50)	-- 계정 아이디
	@NO_CHARGE_CASH			int				-- 충전 캐시
	@NO_CHARGE_BONUS		int				-- 충전 보너스
	@DT_CHARGE_DATE			datetime		-- 충전 일시
-- ## 출력 ## --
	Output : 없음
	ReturnValue : 있음
	RecodeSet : 없음
-- ## 실행 ## --
	DECLARE @Result				int
	,	@CD_USERUID				bigint			-- 계정 UID
	,	@ST_USERID				nvarchar(50)	-- 계정 아이디
	,	@NO_CHARGE_CASH			int				-- 충전 캐시
	,	@NO_CHARGE_BONUS		int				-- 충전 보너스
	,	@DT_CHARGE_DATE			datetime		-- 충전 일시
	,	@NO_REMAIN_CASH			int				-- 충전 후 잔여 캐시
	,	@NO_REMAIN_BONUS		int				-- 충전 후 잔여 보너스

	SELECT @CD_USERUID			= CAST((CAST(RAND() * 10000000000 AS bigint) / (CAST(RAND() * 100 AS tinyint) + 1)) AS bigint) + 1
	,	@NO_CHARGE_CASH			= CAST(RAND() * 100 AS INT) * 10 + 10
	,	@NO_CHARGE_BONUS		= CAST(RAND() * 100 AS INT) * 10 + 10
	,	@DT_CHARGE_DATE			= GETDATE()

	SET @ST_USERID			= 'TestAcc' + CAST(@CD_USERUID AS varchar(12))

	EXEC @Result = dbo.EBI_Cash_Charge_SET @CD_USERUID, @ST_USERID, @NO_CHARGE_CASH, @NO_CHARGE_BONUS, @DT_CHARGE_DATE, @NO_REMAIN_CASH OUTPUT, @NO_REMAIN_BONUS OUTPUT
	SELECT @Result AS Result, @NO_REMAIN_CASH AS NO_REMAIN_CASH, @NO_REMAIN_BONUS AS NO_REMAIN_BONUS
*/
CREATE OR ALTER PROCEDURE [dbo].[EBI_Cash_Charge_SET]
	@CD_USERUID				bigint ,			-- 계정 UID
	@ST_USERID				nvarchar(50) ,		-- 계정 아이디
	@NO_CHARGE_CASH			int ,				-- 충전 캐시
	@NO_CHARGE_BONUS		int ,				-- 충전 보너스
	@DT_CHARGE_DATE			datetime = NULL ,	-- 충전 일시
	@NO_REMAIN_CASH			int = 0 OUTPUT ,	-- 충전 후 잔여 캐시
	@NO_REMAIN_BONUS		int = 0 OUTPUT		-- 충전 후 잔여 보너스
AS
	SET NOCOUNT ON

	DECLARE @Result		int

	IF @DT_CHARGE_DATE IS NULL
		SET @DT_CHARGE_DATE = GETDATE()

	IF EXISTS (SELECT * FROM dbo.EB_Cash WITH(NOLOCK) WHERE CD_USERUID = @CD_USERUID ) BEGIN
		-- 계정 잔액 캐시 업데이트
		UPDATE dbo.EB_Cash
		SET NO_TOTAL_CHARGE_CASH = NO_TOTAL_CHARGE_CASH + @NO_CHARGE_CASH
		,	NO_TOTAL_CHARGE_BONUS = NO_TOTAL_CHARGE_BONUS + @NO_CHARGE_BONUS
		,	NO_REMAIN_CASH = NO_REMAIN_CASH + @NO_CHARGE_CASH
		,	NO_REMAIN_BONUS = NO_REMAIN_BONUS + @NO_CHARGE_BONUS
		,	DT_RECHARGE_DATE = @DT_CHARGE_DATE
		,	@NO_REMAIN_CASH = NO_REMAIN_CASH + @NO_CHARGE_CASH
		,	@NO_REMAIN_BONUS = NO_REMAIN_BONUS + @NO_CHARGE_BONUS
		WHERE CD_USERUID = @CD_USERUID

		SET @Result = @@ERROR
	END
	ELSE BEGIN
		-- 계정 잔액 캐시 입력
		INSERT INTO dbo.EB_Cash ( CD_USERUID, ST_USERID, NO_TOTAL_CHARGE_CASH, NO_TOTAL_CHARGE_BONUS, NO_REMAIN_CASH, NO_REMAIN_BONUS, DT_FIRST_CHARGE_DATE, DT_RECHARGE_DATE )
		VALUES ( @CD_USERUID, @ST_USERID, @NO_CHARGE_CASH, @NO_CHARGE_BONUS, @NO_CHARGE_CASH, @NO_CHARGE_BONUS, @DT_CHARGE_DATE, @DT_CHARGE_DATE )

		SET @Result = @@ERROR

		SELECT @NO_REMAIN_CASH = @NO_CHARGE_CASH, @NO_REMAIN_BONUS = @NO_CHARGE_BONUS
	END

	RETURN @Result
GO
/*
프로시저명 : dbo.EBI_BuyCashItemLocker_SET
내용 : 캐시 아이템 보관함 저장
작성일 : 2011-03-08
작성자 : 김병일
-- ## 관련 테이블 ##--
	dbo.EB_BuyCashItemLockerCount
	dbo.EB_BuyCashItemLocker
	dbo.EB_BuyCashItemLockerPackage
-- ## 관련 프로시저 ## --
	dbo.EBI_SP_ErrorLog_INT
-- ## 입력 ## --
	@CD_TRAN_NUM			bigint			-- 거래 고유번호
	@CD_USERUID				bigint			-- 계정 UID
	@NO_SERVER_SET_ID		tinyint			-- 서버 번호
	@NO_PRODUCT_NUM			int				-- 상품 고유 번호
	@NO_QUANTITY			int				-- 수량
	@NO_FROM_UNITUID		bigint			-- 보낸 계정 UID
	@ST_GIFT_MESSAGE		nvarchar(50)	-- 선물 메시지
	@NO_MAX_KEEP_COUNT		int				-- 최대 보관 갯수(기본 값 200)
-- ## 출력 ## --
	Output : 없음
	ReturnValue : 있음
	RecodeSet : 없음
-- ## 실행 ## --
	DECLARE @Result				int
	,	@CD_TRAN_NUM			bigint			-- 거래 고유번호
	,	@CD_USERUID				bigint			-- 계정 UID
	,	@NO_SERVER_SET_ID		tinyint			-- 서버 번호
	,	@NO_PRODUCT_NUM			int				-- 상품 고유 번호
	,	@NO_QUANTITY			int				-- 수량
	,	@NO_FROM_UNITUID		bigint			-- 보낸 계정 UID
	,	@ST_GIFT_MESSAGE		nvarchar(50)	-- 선물 메시지
	,	@NO_MAX_KEEP_COUNT		int				-- 최대 보관 갯수(기본 값 200)

	SELECT @CD_USERUID			= CAST((CAST(RAND() * 10000000000 AS bigint) / (CAST(RAND() * 100 AS tinyint) + 1)) AS bigint) + 1
	,	@NO_SERVER_SET_ID		= CAST(RAND() * 10 / 2 AS tinyint) + 1
	,	@NO_PRODUCT_NUM			= CAST(RAND() * 10000 AS int)
	,	@NO_QUANTITY			= 1
	,	@NO_FROM_UNITUID		= (CAST((CAST(RAND() * 10000000000 AS bigint) / (CAST(RAND() * 100 AS tinyint) + 1)) AS bigint) + 1) * CAST(RAND() * 2 AS tinyint)
	,	@NO_MAX_KEEP_COUNT		= CAST(RAND() * 200 AS tinyint) + 1

	SET @ST_GIFT_MESSAGE		= CASE WHEN @NO_FROM_UNITUID > 0 THEN N'Gift Item' ELSE N'' END

	EXEC dbo.EBI_TransactionNumber_INT 1, @CD_TRAN_NUM OUTPUT

	EXEC @Result = dbo.EBI_BuyCashItemLocker_SET @CD_TRAN_NUM, @CD_USERUID, @NO_SERVER_SET_ID, @NO_PRODUCT_NUM, @NO_QUANTITY, @NO_FROM_UNITUID, @ST_GIFT_MESSAGE, @NO_MAX_KEEP_COUNT
	SELECT @Result AS Result
*/
CREATE OR ALTER PROCEDURE [dbo].[EBI_BuyCashItemLocker_SET]
	@CD_TRAN_NUM			bigint ,			-- 거래 고유번호
	@CD_USERUID				bigint ,			-- 계정 UID
	@NO_SERVER_SET_ID		tinyint ,			-- 서버 번호
	@NO_PRODUCT_NUM			bigint ,			-- 상품 고유 번호
	@NO_QUANTITY			int ,				-- 수량
	@NO_FROM_UNITUID		bigint ,			-- 보낸 계정 UID
	@ST_GIFT_MESSAGE		nvarchar(50) ,		-- 선물 메시지
	@NO_MAX_KEEP_COUNT		int = 200			-- 최대 보관 갯수(기본 값 200)
AS
	SET NOCOUNT ON

	DECLARE @Result				int
	DECLARE @ST_ErrorMSG		nvarchar(2048)	-- 오류 메시지
	DECLARE @NO_LOCKER_COUNT	int
	DECLARE @DI_PACKAGE			bit				-- 패키지 여부
	,	@NO_NUMBER_PACKAGE		tinyint			-- 패키지 상품의 포함 상품수

	SET @ST_ErrorMSG = N'[%s] dbo.EBI_BuyCashItemLocker_SET %I64d, %I64d, %d, %d, %d, %d, %I64d, ''%s'', %d'

	IF EXISTS (SELECT * FROM dbo.EB_ProductPackage WITH(NOLOCK) WHERE CD_PACKAGENO = @NO_PRODUCT_NUM )
		SET @DI_PACKAGE = 1
	ELSE
		SET @DI_PACKAGE = 0
		
	IF @NO_MAX_KEEP_COUNT > 0 AND @NO_MAX_KEEP_COUNT <= ( SELECT COUNT(*) FROM dbo.EB_BuyCashItemLocker WITH(NOLOCK) WHERE CD_USERUID = @CD_USERUID AND NO_SERVER_SET_ID = @NO_SERVER_SET_ID )
	BEGIN
		-- 보관함 보관 갯수 초과 오류
		SET @Result = -22
		RAISERROR(@ST_ErrorMSG, 15, 1, N'MaxCount Over ItemLocker', @CD_TRAN_NUM, @CD_USERUID, @NO_SERVER_SET_ID, @NO_PRODUCT_NUM, @NO_QUANTITY, @NO_FROM_UNITUID, @ST_GIFT_MESSAGE, @NO_MAX_KEEP_COUNT) WITH SETERROR
	END

	BEGIN TRY
		BEGIN TRAN

		IF @DI_PACKAGE = 1 BEGIN
			INSERT INTO dbo.EB_BuyCashItemLockerPackage ( CD_TRAN_NUM, NO_PRODUCT_NUM )
			SELECT @CD_TRAN_NUM, CD_PRODUCTNO
			FROM dbo.EB_ProductPackage WITH(NOLOCK)
			WHERE CD_PACKAGENO = @NO_PRODUCT_NUM

			SET @NO_NUMBER_PACKAGE = @@ROWCOUNT
		END
		ELSE
			SET @NO_NUMBER_PACKAGE = 0

		INSERT INTO dbo.EB_BuyCashItemLocker ( CD_TRAN_NUM, CD_USERUID, NO_SERVER_SET_ID, NO_PRODUCT_NUM, NO_QUANTITY, DI_PACKAGE, NO_NUMBER_PACKAGE, NO_FROM_UNITUID, ST_GIFT_MESSAGE )
		VALUES ( @CD_TRAN_NUM, @CD_USERUID, @NO_SERVER_SET_ID, @NO_PRODUCT_NUM, @NO_QUANTITY, @DI_PACKAGE, @NO_NUMBER_PACKAGE, @NO_FROM_UNITUID, @ST_GIFT_MESSAGE )

		COMMIT TRAN

		SET @Result = 0
	END TRY
	BEGIN CATCH
		DECLARE @NO_XACT_STATE		smallint
		SET @NO_XACT_STATE			= XACT_STATE()		-- 트랜잭션 상태 정보

		IF @NO_XACT_STATE <> 0
			ROLLBACK TRAN

		EXEC dbo.EBI_SP_ErrorLog_INT @NO_XACT_STATE

		IF ISNULL(@Result, 0) = 0
			SET @Result = -1
	END CATCH

	RETURN @Result
GO
/*
프로시저명 : dbo.EBI_TransactionNumber_INT
내용 : 엘소드 캐시 충전용 거래 고유번호 발행
작성일 : 2011-02-15
작성자 : 김병일
-- ## 관련 테이블 ##--
	dbo.EB_TransactionNumber
-- ## 관련 프로시저 ## --
	dbo.EBI_SP_ErrorLog_INT
-- ## 입력 ## --
	@DI_CASH_LOG_TYPE	smallint 			-- 캐시 충전/이용 구분
-- ## 출력 ## --
	Output :
		@CD_TRAN_NUM		biginy				-- 발행 거래 고유번호
	ReturnValue : 있음
	RecodeSet : Result, CD_TRAN_NUM
			  : SP 처리 결과, 거래 고유번호 오류
-- ## 실행 ## --
	DECLARE @Result			int
	,	@DI_CASH_LOG_TYPE	smallint			-- 사용 구분
	,	@CD_TRAN_NUM		bigint				-- 발행 거래 고유번호

	SET @DI_CASH_LOG_TYPE = 1

	EXEC @Result = dbo.EBI_TransactionNumber_INT @DI_CASH_LOG_TYPE, @CD_TRAN_NUM OUTPUT
	SELECT @Result AS Result, @CD_TRAN_NUM AS CD_TRAN_NUM
*/
CREATE OR ALTER PROCEDURE [dbo].[EBI_TransactionNumber_INT]
	@DI_CASH_LOG_TYPE	smallint ,			-- 사용 구분
	@CD_TRAN_NUM		bigint OUTPUT		-- 발행 거래 고유번호
AS
	SET NOCOUNT ON

	-- 사용 변수 선언
	DECLARE @Result				int		-- 처리 결과

	BEGIN TRY
		BEGIN TRAN

		-- 거래 고유번호 발행 테이블 데이터 입력
		INSERT INTO dbo.EB_TransactionNumber ( DI_CASH_LOG_TYPE, DT_INSERT_DATE )
		VALUES ( @DI_CASH_LOG_TYPE, GETDATE() )

		COMMIT TRAN

		SET @Result = 0	-- 출력 값 설정
	END TRY
	BEGIN CATCH
		DECLARE @NO_XACT_STATE		smallint
		SET @NO_XACT_STATE			= XACT_STATE()		-- 트랜잭션 상태 정보

		IF @@TRANCOUNT < 2 BEGIN
			IF @NO_XACT_STATE <> 0
				ROLLBACK TRAN

			EXEC dbo.EBI_SP_ErrorLog_INT @NO_XACT_STATE
		END
		ELSE
			COMMIT TRAN

		SET @Result = -1
	END CATCH

	SET @CD_TRAN_NUM = ISNULL(SCOPE_IDENTITY(), 0)
	RETURN @Result
GO
/*
프로시저명 : dbo.EBP_TranNumberServer_INT
내용 : 일별 서버 트랙잭션 고유번호 발행
작성일 : 2011-03-07
작성자 : 김병일
--## 2011-08-11 수정 ##--
수정자 : 김병일
수정내용 : @NO_DATE_SECOND
-- ## 관련 테이블 ##--
	dbo.EB_TranNumberServer
-- ## 관련 프로시저 ## --
	dbo.EBI_SP_ErrorLog_INT
	dbo.EBP_TranNumberServer_INT
-- ## 입력 ## --
	없음
-- ## 출력 ## --
	Output : 있음
		@NO_DATE_TRAN_NUM	int			-- 일별 발행 번호
	ReturnValue : 없음
	RecodeSet : 선택
		Result, NO_DATE_TRAN_NUM
		SP 처리 결과, 일별 발행 번호
-- ## 실행 ## --
	DECLARE @Result			int
	,	@NO_DATE_TRAN_NUM	int			-- 일별 발행 번호
	,	@NO_DATE_SECOND		int			-- 1970-01-01 부터 지난 초
	,	@DI_OUTPUT_RECORD	bit			-- 결과 RecordSet 출력 여부

	SET @DI_OUTPUT_RECORD	= 0

	EXEC @Result = dbo.EBP_TranNumberServer_INT @NO_DATE_TRAN_NUM OUTPUT, @NO_DATE_SECOND OUTPUT, @DI_OUTPUT_RECORD
	SELECT @Result AS Result, @NO_DATE_TRAN_NUM AS NO_DATE_TRAN_NUM, @NO_DATE_SECOND AS NO_DATE_SECOND
-- ## 참고 SP ## --
*/
CREATE OR ALTER PROCEDURE [dbo].[EBP_TranNumberServer_INT]
	@NO_DATE_TRAN_NUM	int	= NULL		OUTPUT ,	-- 일별 발행 번호
	@NO_DATE_SECOND		int = NULL 		OUTPUT ,	-- 1970-01-01 부터 지난 초
	@DI_OUTPUT_RECORD	bit = 1 ,					-- 결과 RecordSet 출력 여부
	@NO_TRY_COUNT		tinyint = 0					-- 내부 사용[오류시 제사용]
AS
	SET NOCOUNT ON

	DECLARE @Result			int
	DECLARE @CD_DATE		datetime

	SET @CD_DATE = CAST(CONVERT(varchar(19), GETDATE(), 120) AS datetime)

	BEGIN TRY
		BEGIN TRAN
			SELECT @NO_DATE_TRAN_NUM = ISNULL(MAX(NO_DATE_TRAN_NUM), 0) + 1
			FROM dbo.EB_TranNumberServer WITH(NOLOCK)
			WHERE CD_DATE = @CD_DATE

			INSERT INTO dbo.EB_TranNumberServer ( CD_DATE, NO_DATE_TRAN_NUM )
			VALUES ( @CD_DATE, @NO_DATE_TRAN_NUM )
		COMMIT TRAN

		SET @NO_DATE_SECOND = DATEDIFF(ss, '1970-01-01', @CD_DATE)
		SET @Result = 0
	END TRY
	BEGIN CATCH
		DECLARE @NO_XACT_STATE		smallint
		SET @NO_XACT_STATE			= XACT_STATE()		-- 트랜잭션 상태 정보

		IF @NO_XACT_STATE <> 0
			ROLLBACK TRAN

		-- 오류시 10회까지 다시 호출
		IF @NO_TRY_COUNT IS NULL OR @NO_TRY_COUNT < 10 BEGIN
			SET @NO_TRY_COUNT = ISNULL(@NO_TRY_COUNT, 0) + 1
			EXEC @Result = dbo.EBP_TranNumberServer_INT @NO_DATE_TRAN_NUM OUTPUT, @NO_DATE_SECOND OUTPUT, 0, @NO_TRY_COUNT
		END
		ELSE BEGIN
			EXEC dbo.EBI_SP_ErrorLog_INT @NO_XACT_STATE

			SET @NO_DATE_SECOND = NULL
			SET @NO_DATE_TRAN_NUM = NULL
			SET @Result = -1
		END
	END CATCH

	IF @DI_OUTPUT_RECORD = 1
		SELECT @Result AS Result, @NO_DATE_TRAN_NUM AS NO_DATE_TRAN_NUM, @NO_DATE_SECOND AS NO_DATE_SECOND

	RETURN @Result
GO
/*
프로시저명 : dbo.EBP_Cash_Total_USERUID_SEL
내용 : UserUID로 엘소드 총 잔여 캐시 조회
작성일 : 2011-02-22
작성자 : 김병일
수정일 : 2011-09-28
수정자 : 김병일
수정내용 : 캐시, 보너스 구분하여 출력 추가
-- ## 관련 테이블 ##--
	없음
-- ## 관련 프로시저 ## --
	dbo.EBI_Cash_Detial_SEL
-- ## 입력 ## --
	@CD_USERUID			bigint			-- 계정 UID
-- ## 출력 ## --
	Output :
		@NO_TOTAL_CASH		int				-- 총 잔여 캐시
		@NO_REMAIN_CASH		int					-- 잔여 캐시
		@NO_REMAIN_BONUS	int					-- 잔여 보너스
	ReturnValue : 있음
	RecodeSet : 선택
		Result, NO_TOTAL_CASH, NO_REMAIN_CASH, NO_REMAIN_BONUS
		SP 처리 결과, 총 잔여 캐시, 잔여 캐시, 잔여 보너스
-- ## 실행 ## --
	DECLARE @Result			int
	,	@CD_USERUID			bigint			-- 계정 UID
	,	@NO_TOTAL_CASH		int				-- 총 잔여 캐시
	,	@NO_REMAIN_CASH		int					-- 잔여 캐시
	,	@NO_REMAIN_BONUS	int					-- 잔여 보너스
	,	@DI_OUTPUT_RECORD	bit				-- 결과 RecordSet 출력 여부

	SELECT @CD_USERUID		= CAST((CAST(RAND() * 10000000000 AS bigint) / (CAST(RAND() * 100 AS tinyint) + 1)) AS bigint) + 1

	SET @DI_OUTPUT_RECORD	= 0

	EXEC @Result = dbo.EBP_Cash_Total_USERUID_SEL @CD_USERUID, @NO_TOTAL_CASH OUTPUT, @NO_REMAIN_CASH OUTPUT, @NO_REMAIN_BONUS OUTPUT, @DI_OUTPUT_RECORD
	SELECT @Result AS Result, @NO_TOTAL_CASH AS NO_TOTAL_CASH, @NO_REMAIN_CASH AS NO_REMAIN_CASH, @NO_REMAIN_BONUS AS NO_REMAIN_BONUS
*/
CREATE OR ALTER PROCEDURE [dbo].[EBP_Cash_Total_USERUID_SEL]
	@CD_USERUID			bigint ,				-- 계정 UID
	@NO_TOTAL_CASH		int = 0 OUTPUT ,		-- 총 잔여 캐시
	@NO_REMAIN_CASH		int = 0 OUTPUT ,		-- 잔여 캐시(2011-09-28 추가)
	@NO_REMAIN_BONUS	int = 0 OUTPUT ,		-- 잔여 보너스(2011-09-28 추가)
	@DI_OUTPUT_RECORD	bit = 1					-- 결과 RecordSet 출력 여부
AS
	SET NOCOUNT ON

	EXEC dbo.EBI_Cash_Detial_SEL @CD_USERUID, @NO_REMAIN_CASH OUTPUT, @NO_REMAIN_BONUS OUTPUT

	SET @NO_TOTAL_CASH = @NO_REMAIN_CASH  + @NO_REMAIN_BONUS

	IF @DI_OUTPUT_RECORD = 1
		SELECT 0 AS Result, @NO_TOTAL_CASH AS NO_TOTAL_CASH, @NO_REMAIN_CASH AS NO_REMAIN_CASH, @NO_REMAIN_BONUS AS NO_REMAIN_BONUS

	RETURN 0
GO
/*
프로시저명 : dbo.EBP_Prepare_Gift_Product_CHK
내용 : 구매 제한 상품의 구매 가능 여부 확인
작성일 : 2011-05-05
작성자 : KOG_M
-- ## 관련 테이블 ##--
	dbo.EB_BuyCashItemLimited_User / dbo.EB_Product
-- ## 관련 프로시저 ## --
	없음
-- ## 입력 ## --
	@CD_PRODUCTNO		INT			-- 상품 고유번호
	@CD_SEND_USERUID	BIGINT		-- 보내는 계정 UID
	@CD_SEND_UNITUID	BIGINT		-- 보내는 캐릭터 UID
	@CD_RECV_USERUID	BIGINT		-- 받는 계정 UID
	@CD_RECV_UNITUID	BIGINT		-- 받는 캐릭터 UID
	@NO_SERVER_SET_ID	TINYINT		-- 서버 그룹
-- ## 출력 ## --
	Output : 없음
	ReturnValue : 있음
	RecodeSet : 선택
		Result
		SP 처리 결과
-- ## 실행 ## --

*/
CREATE OR ALTER PROCEDURE [dbo].[EBP_Prepare_Gift_Product_CHK]
	@ST_SERVERORDERID		varchar(50) ,			-- 서버 발행 주문번호('20101207204029_3_24_1' / yyyymmddhhmiss_ServerUID_UserUID_구매일련번호)
	@ST_GROUPORDERID		varchar(50) ,			-- 그룹별 발행 주문번호 (2013-04-30 추가)
	@CD_USERUID				bigint ,				-- 계정 UID
	@ST_USERID				nvarchar(50) ,			-- 계정 아이디
	@NO_SERVER_SET_ID		tinyint ,				-- 서버 그룹
	@NO_UNITUID				bigint ,				-- 캐릭터 UID
	@NO_LEVEL				tinyint ,				-- 캐릭터 레벨
	@NO_PRODUCT_NUM			bigint ,				-- 아이템(상품) 번호
	@NO_QUANTITY			smallint ,				-- 구매 수량
	@NO_PRICE				int ,					-- 구매 가격
	@DI_ITEM_KEEP			tinyint ,				-- 캐시 보관함 저장 여부(1 - 저장 : 0 - 미저장)
	@NO_TO_USERUID			bigint ,				-- 받는 계정 UID
	@NO_TO_UNITUID			bigint ,				-- 받는 캐릭터 UID
	@ST_GIFT_MESSAGE		nvarchar(50) ,			-- 선물 메시지
	@DI_BUY_CASH			tinyint ,				-- 구매 캐시 종류(0 - 통합  : 1 - 캐시 : 2 - 보너스)(2011-09-28 추가)
	@NO_CHANNEL_CODE		tinyint = 0 ,			-- 채널링 코드 (2013-05-11 추가)
	@NO_TOTAL_CASH			int = 0 OUTPUT,			-- 총 잔여 캐시
	@CD_TRAN_NUM			bigint = 0 OUTPUT ,		-- 거래 고유번호
	@NO_REMAIN_CASH			int = 0 OUTPUT ,		-- 잔여 캐시(2011-09-28 추가)
	@NO_REMAIN_BONUS		int = 0 OUTPUT ,		-- 잔여 보너스(2011-09-28 추가)
	@DI_OUTPUT_RECORD		bit = 1					-- 결과 RecordSet 출력 여부
AS
	SET NOCOUNT ON

	-- 사용 변수 선언
	DECLARE @Result				int
	DECLARE @DT_GETDATE			datetime		-- 충전 시간 동기화용 시간

	DECLARE @NO_BEFOR_CASH		int
	,		@NO_BEFOR_BONUS		int

	DECLARE @NO_LOCKER_COUNT	int
	,		@DI_CASH_LOG_TYPE	smallint
	,		@NO_FROM_UNITUID	bigint

	-- 상품 관련
	DECLARE @DI_ISSALE			bit
	,		@DT_STARTDATE		smalldatetime
	,		@DT_ENDDATE			smalldatetime
	,		@DI_ENABLEGIFT		bit
	,		@NO_SALEPRICE		int
	,		@NO_REALPRICE		int
	,		@NO_LIMIT_USERUID	int
	,		@CD_PRODUCT_SM		bigint
	
	-- 기본 처리 결과 정상으로 설정, 현재 시간 설정
	SELECT @Result = 0, @DT_GETDATE = GETDATE()
	
	-- 현재 총 잔액 확인
	EXEC dbo.EBI_Cash_Detial_SEL @CD_USERUID, @NO_BEFOR_CASH OUTPUT, @NO_BEFOR_BONUS OUTPUT

	SELECT @NO_TOTAL_CASH = @NO_BEFOR_CASH + @NO_BEFOR_BONUS, @NO_REMAIN_CASH = @NO_BEFOR_CASH, @NO_REMAIN_BONUS = @NO_BEFOR_BONUS

	-- 상품 정보 확인
	EXEC @Result = dbo.EBI_Buy_Product_CHK @NO_PRODUCT_NUM, @DI_ISSALE OUTPUT, @DT_STARTDATE OUTPUT, @DT_ENDDATE OUTPUT, @DI_ENABLEGIFT OUTPUT, @NO_SALEPRICE OUTPUT, @NO_REALPRICE OUTPUT

	-- 판매 상품 아님
	IF @Result <> 0 BEGIN 
		SET @Result = -29
		GOTO END_PROC
	END

	-- 판매 기간 아님
	IF NOT (@DT_GETDATE BETWEEN ISNULL(@DT_STARTDATE, DATEADD(MI, -1, @DT_GETDATE)) AND ISNULL(@DT_ENDDATE, DATEADD(MI, 1, @DT_GETDATE))) OR @DI_ISSALE <> 1 BEGIN
		SET @Result = -23
		GOTO END_PROC
	END

	-- 선물 불가 상품 선물
	IF @DI_ENABLEGIFT = 0 AND @DI_CASH_LOG_TYPE = -11 BEGIN
		SET @Result = -24
		GOTO END_PROC
	END

	-- 구매 금액 확인
	IF @NO_SALEPRICE <> @NO_PRICE BEGIN
		SET @Result = -25
		GOTO END_PROC
	END
	
	-- 계정 구매 수량 제한 확인
	EXEC @Result = dbo.EBP_Buy_Product_LimitedUser_CHK @NO_PRODUCT_NUM, @NO_TO_USERUID, @NO_SERVER_SET_ID, @CD_PRODUCT_SM OUTPUT, @NO_LIMIT_USERUID OUTPUT, 0
	
	IF @Result <> 0
		GOTO END_PROC
		
	-- 캐시 인벤토리 카운트 체크
	EXEC @Result = dbo.EBP_BuyCashItemLockerCount_CHK @NO_TO_USERUID, @NO_SERVER_SET_ID
	
	IF @Result <> 0
		GOTO END_PROC
		
	
/*
	-- 구매금액 부족
	IF ((CASE @DI_BUY_CASH WHEN 1 THEN @NO_BEFOR_CASH - @NO_PRICE WHEN 2 THEN @NO_BEFOR_BONUS - @NO_PRICE ELSE @NO_TOTAL_CASH - @NO_PRICE END) < 0) BEGIN
		SET @Result = -21
		GOTO END_PROC
	END
*/
	
END_PROC:
	IF @DI_OUTPUT_RECORD = 1
		SELECT @Result
		
	RETURN @Result
GO
/*
프로시저명 : dbo.EBP_Prepare_Buy_Product_CHK
내용 : 구매 제한 상품의 구매 가능 여부 확인
작성일 : 2011-05-05
작성자 : KOG_M
-- ## 관련 테이블 ##--
	dbo.EB_BuyCashItemLimited_User / dbo.EB_Product
-- ## 관련 프로시저 ## --
	없음
-- ## 입력 ## --
	@CD_PRODUCTNO		INT				-- 상품 고유번호
	@CD_USERUID			BIGINT			-- 계정 UID
	@CD_UNITUID			BIGINT			-- 캐릭터 UID
	@NO_SERVER_SET_ID	TINYINT			-- 서버 그룹
-- ## 출력 ## --
	Output : 없음
	ReturnValue : 있음
	RecodeSet : 선택
		Result
		SP 처리 결과
-- ## 실행 ## --
*/
CREATE OR ALTER PROCEDURE [dbo].[EBP_Prepare_Buy_Product_CHK]
	@ST_SERVERORDERID		varchar(50) ,			-- 서버 발행 주문번호('20101207204029_3_24_1' / yyyymmddhhmiss_ServerUID_UserUID_구매일련번호)
	@ST_GROUPORDERID		varchar(50) ,			-- 그룹별 발행 주문번호 (2013-04-30 추가)
	@CD_USERUID				bigint ,				-- 계정 UID
	@ST_USERID				nvarchar(50) ,			-- 계정 아이디
	@NO_SERVER_SET_ID		tinyint ,				-- 서버 그룹
	@NO_UNITUID				bigint ,				-- 캐릭터 UID
	@NO_LEVEL				tinyint ,				-- 캐릭터 레벨
	@NO_PRODUCT_NUM			bigint ,				-- 아이템(상품) 번호
	@NO_QUANTITY			smallint ,				-- 구매 수량
	@NO_PRICE				int ,					-- 구매 가격
	@DI_ITEM_KEEP			tinyint ,				-- 캐시 보관함 저장 여부(1 - 저장 : 0 - 미저장)
	@NO_TO_USERUID			bigint ,				-- 받는 계정 UID
	@NO_TO_UNITUID			bigint ,				-- 받는 캐릭터 UID
	@ST_GIFT_MESSAGE		nvarchar(50) ,			-- 선물 메시지
	@DI_BUY_CASH			tinyint ,				-- 구매 캐시 종류(0 - 통합  : 1 - 캐시 : 2 - 보너스)(2011-09-28 추가)
	@NO_CHANNEL_CODE		tinyint = 0 ,			-- 채널링 코드 (2013-05-11 추가)
	@NO_TOTAL_CASH			int = 0 OUTPUT,			-- 총 잔여 캐시
	@CD_TRAN_NUM			bigint = 0 OUTPUT ,		-- 거래 고유번호
	@NO_REMAIN_CASH			int = 0 OUTPUT ,		-- 잔여 캐시(2011-09-28 추가)
	@NO_REMAIN_BONUS		int = 0 OUTPUT ,		-- 잔여 보너스(2011-09-28 추가)
	@DI_OUTPUT_RECORD		bit = 1					-- 결과 RecordSet 출력 여부
AS
	SET NOCOUNT ON

	-- 사용 변수 선언
	DECLARE @Result				int
	DECLARE @DT_GETDATE			datetime		-- 충전 시간 동기화용 시간

	DECLARE @NO_BEFOR_CASH		int
	,		@NO_BEFOR_BONUS		int

	DECLARE @NO_LOCKER_COUNT	int
	,		@DI_CASH_LOG_TYPE	smallint
	,		@NO_FROM_UNITUID	bigint

	-- 상품 관련
	DECLARE @DI_ISSALE			bit
	,		@DT_STARTDATE		smalldatetime
	,		@DT_ENDDATE			smalldatetime
	,		@DI_ENABLEGIFT		bit
	,		@NO_SALEPRICE		int
	,		@NO_REALPRICE		int
	,		@NO_LIMIT_USERUID	int
	,		@CD_PRODUCT_SM		bigint
	
	-- 기본 처리 결과 정상으로 설정, 현재 시간 설정
	SELECT @Result = 0, @DT_GETDATE = GETDATE()
	
	-- 현재 총 잔액 확인
	EXEC dbo.EBI_Cash_Detial_SEL @CD_USERUID, @NO_BEFOR_CASH OUTPUT, @NO_BEFOR_BONUS OUTPUT

	SELECT @NO_TOTAL_CASH = @NO_BEFOR_CASH + @NO_BEFOR_BONUS, @NO_REMAIN_CASH = @NO_BEFOR_CASH, @NO_REMAIN_BONUS = @NO_BEFOR_BONUS

	-- 상품 정보 확인
	EXEC @Result = dbo.EBI_Buy_Product_CHK @NO_PRODUCT_NUM, @DI_ISSALE OUTPUT, @DT_STARTDATE OUTPUT, @DT_ENDDATE OUTPUT, @DI_ENABLEGIFT OUTPUT, @NO_SALEPRICE OUTPUT, @NO_REALPRICE OUTPUT

	-- 판매 상품 아님
	IF @Result <> 0 BEGIN 
		SET @Result = -29
		GOTO END_PROC
	END

	-- 판매 기간 아님
	IF NOT (@DT_GETDATE BETWEEN ISNULL(@DT_STARTDATE, DATEADD(MI, -1, @DT_GETDATE)) AND ISNULL(@DT_ENDDATE, DATEADD(MI, 1, @DT_GETDATE))) OR @DI_ISSALE <> 1 BEGIN
		SET @Result = -23
		GOTO END_PROC
	END

	-- 선물 불가 상품 선물
	IF @DI_ENABLEGIFT = 0 AND @DI_CASH_LOG_TYPE = -11 BEGIN
		SET @Result = -24
		GOTO END_PROC
	END

	-- 구매 금액 확인
	IF @NO_SALEPRICE <> @NO_PRICE BEGIN
		SET @Result = -25
		GOTO END_PROC
	END
	
	-- 계정 구매 수량 제한 확인
	EXEC @Result = dbo.EBP_Buy_Product_LimitedUser_CHK @NO_PRODUCT_NUM, @NO_TO_USERUID, @NO_SERVER_SET_ID, @CD_PRODUCT_SM OUTPUT, @NO_LIMIT_USERUID OUTPUT, 0
	
	IF @Result <> 0
		GOTO END_PROC
		
	-- 캐시 인벤토리 카운트 체크
	EXEC @Result = dbo.EBP_BuyCashItemLockerCount_CHK @NO_TO_USERUID, @NO_SERVER_SET_ID
	
	IF @Result <> 0
		GOTO END_PROC
		
/*
	-- 구매금액 부족
	IF ((CASE @DI_BUY_CASH WHEN 1 THEN @NO_BEFOR_CASH - @NO_PRICE WHEN 2 THEN @NO_BEFOR_BONUS - @NO_PRICE ELSE @NO_TOTAL_CASH - @NO_PRICE END) < 0) BEGIN
		SET @Result = -21
		GOTO END_PROC
	END
*/
	
END_PROC:
	IF @DI_OUTPUT_RECORD = 1
		SELECT @Result
		
	RETURN @Result
GO
/*
프로시저명 : dbo.EBP_BuyCashItemTake_SET
내용 : 캐시 아이템 보관함 인출
작성일 : 2011-02-22
작성자 : 김병일
-- ## 관련 테이블 ##--
	dbo.EB_BuyCashItemLocker
	dbo.EB_BuyCashItemLockerCount
	dbo.EB_BuyCashItemTakeLog
-- ## 관련 프로시저 ## --
	dbo.EBI_SP_ErrorLog_INT
-- ## 입력 ## --
	@CD_TRAN_NUM					bigint			-- 거래 고유번호
	@CD_USERUID						bigint			-- 계정 UID
	@NO_SERVER_SET_ID				tinyint			-- 서버 그룹
	@NO_UNITUID						bigint			-- 인출 캐릭터 UID
	@NO_PRODUCT_NUM_IN_PACKAGE		int				-- 패키지 내부 상품 고유번호
-- ## 출력 ## --
	Output : 없음
	ReturnValue : 있음
	RecodeSet : 선택
		Result
		처리 결과
-- ## 실행 ## --
	DECLARE @Result						int
	,	@CD_TRAN_NUM					bigint			-- 거래 고유번호
	,	@CD_USERUID						bigint			-- 계정 UID
	,	@NO_SERVER_SET_ID				tinyint			-- 서버 그룹
	,	@NO_UNITUID						bigint			-- 인출 캐릭터 UID
	,	@NO_PRODUCT_NUM_IN_PACKAGE		int				-- 패키지 내부 상품 고유번호
	,	@DI_OUTPUT_RECORD				bit				-- 결과 RecordSet 출력 여부

	DECLARE @DI_PACKAGE		bit				-- 패키지 여부

	SELECT TOP 1 @CD_TRAN_NUM = CD_TRAN_NUM
	,	@CD_USERUID = CD_USERUID
	,	@NO_SERVER_SET_ID = NO_SERVER_SET_ID
	,	@NO_UNITUID = CAST((CAST(RAND() * 10000000000 AS bigint) / (CAST(RAND() * 100 AS tinyint) + 1)) AS bigint) + 1
	,	@DI_PACKAGE = DI_PACKAGE
	,	@NO_PRODUCT_NUM_IN_PACKAGE = 0
	FROM dbo.EB_BuyCashItemLocker WITH(NOLOCK)
	WHERE CD_TRAN_NUM > 0
	ORDER BY NEWID()

	IF @DI_PACKAGE = 1
		SELECT TOP 1 @NO_PRODUCT_NUM_IN_PACKAGE = NO_PRODUCT_NUM
		FROM dbo.EB_BuyCashItemLockerPackage WITH(NOLOCK)
		WHERE CD_TRAN_NUM = @CD_TRAN_NUM

	SET @DI_OUTPUT_RECORD	= 0

	EXEC @Result = dbo.EBP_BuyCashItemTake_SET @CD_TRAN_NUM, @CD_USERUID, @NO_SERVER_SET_ID, @NO_UNITUID, @NO_PRODUCT_NUM_IN_PACKAGE, @DI_OUTPUT_RECORD
	SELECT @Result AS Result
-- ## 참고 SP ## --
	dbo.bup_insert_cash_log
*/
CREATE OR ALTER PROCEDURE [dbo].[EBP_BuyCashItemTake_SET]
	@CD_TRAN_NUM					bigint ,			-- 거래 고유번호
	@CD_USERUID						bigint ,			-- 계정 UID
	@NO_SERVER_SET_ID				tinyint ,			-- 서버 그룹
	@NO_UNITUID						bigint ,			-- 인출 캐릭터 UID
	@NO_PRODUCT_NUM_IN_PACKAGE		bigint = 0 ,		-- 패키지 내부 상품 고유번호
	@DI_OUTPUT_RECORD				bit = 1				-- 결과 RecordSet 출력 여부
AS
	SET NOCOUNT ON

	-- 사용 변수 선언
	DECLARE @Result				int		-- 처리 결과
	DECLARE @ST_ErrorMSG		nvarchar(2048)	-- 오류 메시지

	DECLARE @NO_PRODUCT_NUM		bigint
	,	@NO_QUANTITY			smallint
	,	@DI_PACKAGE				bit
	,	@NO_NUMBER_PACKAGE		tinyint
	,	@NO_FROM_UNITUID		bigint
	,	@ST_GIFT_MESSAGE		nvarchar(100)
	,	@DI_LOCKERCOUNT			bit
	,	@GETDATE				datetime
	
	DECLARE @DI_DELETE_LOCKER	bit

	SET @ST_ErrorMSG = N'[%s] dbo.EBP_BuyCashItemTake_SET %I64d, %I64d, %d, %I64d, %d'

	SELECT @NO_PRODUCT_NUM = NO_PRODUCT_NUM, @NO_QUANTITY = NO_QUANTITY, @NO_FROM_UNITUID = NO_FROM_UNITUID, @ST_GIFT_MESSAGE = ST_GIFT_MESSAGE
	, @DI_PACKAGE = DI_PACKAGE, @NO_NUMBER_PACKAGE = NO_NUMBER_PACKAGE
	, @GETDATE = GETDATE()
	FROM dbo.EB_BuyCashItemLocker WITH(NOLOCK)
	WHERE CD_TRAN_NUM = @CD_TRAN_NUM AND CD_USERUID = @CD_USERUID
		AND NO_SERVER_SET_ID = @NO_SERVER_SET_ID

	IF @@ROWCOUNT = 1 BEGIN
		IF @DI_PACKAGE = 1 AND ISNULL(@NO_PRODUCT_NUM_IN_PACKAGE, 0) = 0 BEGIN
			-- 패키지 상품은 패키지 내부 상품 고유번호로 가져가기 처리
			SET @Result = -98
		END
		ELSE BEGIN
			BEGIN TRY
				BEGIN TRAN

				-- 패키지 내부 아이템 가져가기
				IF @DI_PACKAGE = 1 BEGIN
					DELETE dbo.EB_BuyCashItemLockerPackage
						OUTPUT DELETED.CD_TRAN_NUM, DELETED.NO_PRODUCT_NUM, @NO_SERVER_SET_ID, @NO_UNITUID, @GETDATE
						INTO dbo.EB_BuyCashItemPackageTakeLog ( CD_TRAN_NUM, NO_PRODUCT_NUM, NO_SERVER_SET_ID, NO_UNITUID, DT_LOG_DATE )
					WHERE CD_TRAN_NUM = @CD_TRAN_NUM AND NO_PRODUCT_NUM = @NO_PRODUCT_NUM_IN_PACKAGE

					IF @@ROWCOUNT = 0 BEGIN
						-- 중복
						SET @Result = -11
						RAISERROR(@ST_ErrorMSG, 15, 1, N'ItemTake LockerPackage Delete', @CD_TRAN_NUM, @CD_USERUID, @NO_SERVER_SET_ID, @NO_UNITUID, @NO_PRODUCT_NUM_IN_PACKAGE) WITH SETERROR
					END

					-- 패키지 내부 아이템을 모두 가져갔는 확인(모두 가져간 경우 캐시 아이템 보관함에서 패키지 삭제)
					SET @DI_DELETE_LOCKER = CASE WHEN EXISTS (SELECT * FROM dbo.EB_BuyCashItemLockerPackage WITH(NOLOCK) WHERE CD_TRAN_NUM = @CD_TRAN_NUM ) THEN 0 ELSE 1 END

				END
				ELSE
					SET @DI_DELETE_LOCKER = 1

				IF @DI_DELETE_LOCKER = 1 BEGIN
					-- 캐시 아이템 보관함에서 삭제
					DELETE dbo.EB_BuyCashItemLocker
						OUTPUT DELETED.CD_TRAN_NUM, DELETED.CD_USERUID, @NO_SERVER_SET_ID, DELETED.NO_PRODUCT_NUM, DELETED.NO_QUANTITY, DELETED.DI_PACKAGE, DELETED.NO_NUMBER_PACKAGE, DELETED.NO_FROM_UNITUID, DELETED.ST_GIFT_MESSAGE, @NO_UNITUID, @GETDATE
						INTO dbo.EB_BuyCashItemTakeLog ( CD_TRAN_NUM, CD_USERUID, NO_SERVER_SET_ID, NO_PRODUCT_NUM, NO_QUANTITY, DI_PACKAGE, NO_NUMBER_PACKAGE, NO_FROM_UNITUID, ST_GIFT_MESSAGE, NO_UNITUID, DT_LOG_DATE )
					WHERE CD_TRAN_NUM = @CD_TRAN_NUM

					IF @@ROWCOUNT = 0 BEGIN
						IF @DI_PACKAGE = 0 BEGIN
							-- 중복
							SET @Result = -11
							RAISERROR(@ST_ErrorMSG, 15, 1, N'ItemTake Locker Delete', @CD_TRAN_NUM, @CD_USERUID, @NO_SERVER_SET_ID, @NO_UNITUID, @NO_PRODUCT_NUM_IN_PACKAGE) WITH SETERROR
						END
						ELSE
							SET @DI_LOCKERCOUNT = 0
					END
					ELSE
						SET @DI_LOCKERCOUNT = 1	

				END

				COMMIT TRAN

				SET @Result = 0
			END TRY
			BEGIN CATCH
				DECLARE @NO_XACT_STATE		smallint
				SET @NO_XACT_STATE			= XACT_STATE()		-- 트랜잭션 상태 정보

				IF @NO_XACT_STATE <> 0
					ROLLBACK TRAN

				EXEC dbo.EBI_SP_ErrorLog_INT @NO_XACT_STATE

				SET @Result = -1
			END CATCH
		END
	END
	ELSE
		SET @Result = -99

	IF @DI_OUTPUT_RECORD = 1
		SELECT @Result AS Result

	RETURN @Result
GO
/*
프로시저명 : dbo.EBP_CouponOrder_SET
내용 : 쿠폰 사용 준비
작성일 : 2011-03-09
작성자 : KOG_M
-- ## 관련 테이블 ##--
	dbo.EB_CouponOrder
	dbo.EB_CouponOrder_UseLog
-- ## 관련 프로시저 ## --
	dbo.EBI_TransactionNumber_INT
	dbo.EBI_SP_ErrorLog_INT
-- ## 입력 ## --
	@CD_COUPON			nvarchar(40)		-- 쿠폰 번호
	@ST_TRANSACTION		varchar(21)			-- 처리열 고유 문자
	@CD_USERUID			bigint				-- 계정 UID
	@ST_USERID			nvarchar(50)		-- 계정 아이디
	@NO_SERVER_SET_ID	tinyint				-- 서버 그룹
	@NO_UNITUID			bigint				-- 캐릭터 UID
	@NO_LEVEL			tinyint				-- 캐릭터 레벨
	@ST_USER_IP			varchar(16)			-- 유저 아이피
	@DI_ORDER_TYPE		tinyint				-- 주문 종류
-- ## 출력 ## --
	Output : 없음
	ReturnValue : 있음
	RecodeSet : 선택
		Result
		SP 처리 결과
-- ## 실행 ## --
	DECLARE @Result			int
	,	@CD_COUPON			nvarchar(40)		-- 쿠폰 번호
	,	@ST_TRANSACTION		varchar(21)			-- 처리열 고유 문자
	,	@CD_USERUID			bigint				-- 계정 UID
	,	@ST_USERID			nvarchar(50)		-- 계정 아이디
	,	@NO_SERVER_SET_ID	tinyint				-- 서버 번호
	,	@NO_UNITUID			bigint				-- 캐릭터 UID
	,	@NO_LEVEL			tinyint				-- 캐릭터 레벨
	,	@ST_USER_IP			varchar(16)			-- 유저 아이피
	,	@DI_ORDER_TYPE		tinyint				-- 주문 종류
	,	@DI_OUTPUT_RECORD	bit					-- 결과 RecordSet 출력 여부

	SELECT @CD_COUPON		= NEWID()
	,	@CD_USERUID			= CAST((CAST(RAND() * 10000000000 AS bigint) / (CAST(RAND() * 100 AS tinyint) + 1)) AS bigint) + 1
	,	@NO_SERVER_SET_ID	= CAST(RAND() * 10 / 2 AS tinyint) + 1
	,	@NO_UNITUID			= CAST((CAST(RAND() * 10000000000 AS bigint) / (CAST(RAND() * 100 AS tinyint) + 1)) AS bigint) + 1
	,	@NO_LEVEL			= CAST(RAND() * 58 AS tinyint) + 1
	,	@ST_USER_IP			= '127.0.0.1'
	,	@DI_ORDER_TYPE		= CASE WHEN CAST(RAND() * 2 AS tinyint) = 0 THEN 2 ELSE 5 END

	DECLARE @NO_DATE_TRAN_NUM	int					-- 일별 발행 번호
	EXEC dbo.EBP_TranNumberServer_INT @NO_DATE_TRAN_NUM OUTPUT, 0

	SET @ST_TRANSACTION		= LEFT(N'C'+RIGHT(REPLACE(REPLACE(REPLACE(REPLACE(CONVERT(varchar(23), GETDATE(), 121), '-', ''), ' ', ''), ':', ''), '.', ''), 14) + RIGHT('0000' + CAST(@NO_DATE_TRAN_NUM AS varchar(4)), 9) + RIGHT(CAST(@CD_USERUID AS varchar(10)), 10), 21)
	SET @ST_USERID			= 'TestAcc' + CAST(@CD_USERUID AS varchar(12))

	SET @DI_OUTPUT_RECORD	= 0

	EXEC @Result = dbo.EBP_CouponOrder_SET @CD_COUPON, @ST_TRANSACTION, @CD_USERUID, @ST_USERID, @NO_SERVER_SET_ID, @NO_UNITUID, @NO_LEVEL, @ST_USER_IP, @DI_ORDER_TYPE, @DI_OUTPUT_RECORD

	IF @DI_OUTPUT_RECORD = 0
		SELECT @Result AS Result
*/
CREATE OR ALTER PROCEDURE [dbo].[EBP_CouponOrder_SET]
	@CD_COUPON			nvarchar(40) ,			-- 쿠폰 번호
	@ST_TRANSACTION		varchar(21) ,			-- 처리열 고유 문자
	@CD_USERUID			bigint ,				-- 계정 UID
	@ST_USERID			nvarchar(50) ,			-- 계정 아이디
	@NO_SERVER_SET_ID	tinyint ,				-- 서버 그룹
	@NO_UNITUID			bigint ,				-- 캐릭터 UID
	@NO_LEVEL			tinyint ,				-- 캐릭터 레벨
	@ST_USER_IP			varchar(16) ,			-- 유저 아이피
	@DI_ORDER_TYPE		tinyint ,				-- 주문 종류
	@DI_OUTPUT_RECORD	bit = 1					-- 결과 RecordSet 출력 여부
AS
	SET NOCOUNT ON

	-- 사용 변수 선언
	DECLARE @Result				int

	IF NOT EXISTS ( SELECT * FROM dbo.EB_CouponOrder WITH(NOLOCK) WHERE CD_COUPON = @CD_COUPON ) BEGIN
		BEGIN TRY
			INSERT INTO dbo.EB_CouponOrder_UseLog ( CD_COUPON, ST_TRANSACTION, CD_USERUID, ST_USERID, NO_SERVER_SET_ID, NO_UNITUID, NO_LEVEL, NO_CHARGE_CASH, NO_CHARGE_BONUS, NO_CHARGE_ITEM, ST_USER_IP, DI_ORDER_TYPE, DT_ORDER_DATE, DI_ORDER_RESULT, DT_RESULT_DATE )
			VALUES ( @CD_COUPON, @ST_TRANSACTION, @CD_USERUID, @ST_USERID, @NO_SERVER_SET_ID, @NO_UNITUID, @NO_LEVEL, 0, 0, 0, @ST_USER_IP, @DI_ORDER_TYPE, GETDATE(), 1, GETDATE() )

			SET @Result = 0
		END TRY
		BEGIN CATCH
			DECLARE @NO_XACT_STATE		smallint
			SET @NO_XACT_STATE			= XACT_STATE()		-- 트랜잭션 상태 정보

			IF @NO_XACT_STATE <> 0
				ROLLBACK TRAN

			EXEC dbo.EBI_SP_ErrorLog_INT @NO_XACT_STATE
			SET @Result = -1
		END CATCH
	END
	ELSE
		SET @Result = -11			-- 처리 완료 주문(중복 처리)

	IF @DI_OUTPUT_RECORD = 1
		SELECT @Result AS Result

	RETURN @Result
GO
/*
프로시저명 : dbo.EBP_CouponOrder_Result
내용 : 쿠폰 사용 결과
작성일 : 2011-03-09
작성자 : 김병일
-- ## 관련 테이블 ##--
	dbo.EB_CouponOrder
	dbo.EB_CouponOrder_UseLog
-- ## 관련 프로시저 ## --
	dbo.EBI_Cash_Charge_SET
	dbo.EBI_Cash_Detial_SEL
	dbo.EBI_BuyCashItemLocker_SET
	dbo.EBI_CashLog_INT
	dbo.EBP_Cash_Total_USERUID_SEL
	dbo.EBI_SP_ErrorLog_INT
-- ## 입력 ## --
	@ST_TRANSACTION			varchar(21)			-- 처리열 고유 문자
	@DI_ORDER_RESULT		smallint			-- 주문 결과
	@NO_CHARGE_ITEM			int					-- 지급할 아이템
	@NO_CHARGE_CASH			int					-- 충전할 캐시
	@NO_CHARGE_BONUS		int					-- 충전할 보너스
	@CD_USERUID				bigint			-- 충전 계정 UID
-- ## 출력 ## --
	Output :
		@NO_TOTAL_CASH			int					-- 총 잔여 캐시
	ReturnValue : 있음
	RecodeSet : 있음
		Result, NO_TOTAL_CASH, CD_USERUID
		SP 처리 결과, 총 잔여 캐시, 충전 계정 UID
-- ## 실행 ## --
	DECLARE @Result				int
	,	@ST_TRANSACTION			varchar(21)			-- 처리열 고유 문자
	,	@DI_ORDER_RESULT		smallint			-- 주문 결과
	,	@NO_CHARGE_ITEM			int					-- 지급할 아이템
	,	@NO_CHARGE_CASH			int					-- 충전할 캐시
	,	@NO_CHARGE_BONUS		int					-- 충전할 보너스
	,	@NO_TOTAL_CASH			int					-- 총 잔여 캐시
	,	@CD_USERUID				bigint				-- 충전 계정 UID
	,	@DI_OUTPUT_RECORD		bit					-- 결과 RecordSet 출력 여부

	SELECT TOP 1
		@ST_TRANSACTION = ST_TRANSACTION
	,	@DI_ORDER_RESULT = CAST(RAND() * 2 AS tinyint) * -1
	,	@NO_CHARGE_ITEM = CAST(RAND() * 10000 AS int)
	,	@NO_CHARGE_CASH = CAST(RAND() * 2 AS int) * 10
	,	@NO_CHARGE_BONUS = CAST(RAND() * 2 AS int) * 10
	FROM dbo.EB_CouponOrder_UseLog WITH(NOLOCK)
	WHERE CD_TRAN_NUM > 0
		AND DI_ORDER_RESULT = CASE WHEN CAST(RAND() * 10 AS int) > 0 THEN 1 ELSE 0 END
	ORDER BY NEWID()

	IF @@ROWCOUNT = 1 BEGIN
		SET @DI_OUTPUT_RECORD	= 0

		EXEC @Result = dbo.EBP_CouponOrder_Result @ST_TRANSACTION, @DI_ORDER_RESULT, @NO_CHARGE_ITEM, @NO_CHARGE_CASH, @NO_CHARGE_BONUS, @NO_TOTAL_CASH OUTPUT, @CD_USERUID OUTPUT, @DI_OUTPUT_RECORD

		IF @DI_OUTPUT_RECORD = 0
			SELECT @Result AS Result, @NO_TOTAL_CASH AS NO_TOTAL_CASH, @CD_USERUID AS CD_USERUID
	END
*/
CREATE OR ALTER PROCEDURE [dbo].[EBP_CouponOrder_Result]
	@ST_TRANSACTION			varchar(21) ,			-- 처리열 고유 문자
	@DI_ORDER_RESULT		smallint ,				-- 주문 결과
	@NO_CHARGE_ITEM			bigint = 0 ,			-- 지급할 아이템
	@NO_CHARGE_CASH			int = 0 ,				-- 충전할 캐시
	@NO_CHARGE_BONUS		int = 0 ,				-- 충전할 보너스
	@NO_TOTAL_CASH			int = 0 OUTPUT ,		-- 총 잔여 캐시
	@CD_USERUID				bigint = 0 OUTPUT ,		-- 충전 계정 UID
	@DI_OUTPUT_RECORD		bit = 1					-- 결과 RecordSet 출력 여부
AS
	SET NOCOUNT ON

	-- 사용 변수 선언
	DECLARE @Result				int
	DECLARE @DT_GETDATE			datetime		-- 시간 동기화용 시간
	DECLARE @ST_ErrorMSG		nvarchar(2048)	-- 오류 메시지

	DECLARE @CD_TRAN_NUM		bigint			-- 거래 고유번호

	DECLARE @CD_COUPON			nvarchar(40)	-- 쿠폰 번호
	,	@ST_USERID				nvarchar(50)	-- 계정 아이디
	,	@NO_SERVER_SET_ID		tinyint			-- 서버 그룹
	,	@NO_UNITUID				bigint			-- 캐릭터 UID
	,	@NO_LEVEL				tinyint			-- 캐릭터 레벨
	,	@ST_USER_IP				varchar(16)		-- 유저 아이피
	,	@DI_ORDER_TYPE			smallint		-- 주문 종류
	,	@DI_ORDER_RESULT_ORG	smallint		-- 처리 전 주문 번호
	,	@DT_ORDER_DATE			datetime		-- 주문 등록일시

	DECLARE @NO_REMAIN_CASH		int				-- 잔여 캐시
	,	@NO_REMAIN_BONUS		int				-- 잔여 보너스

	DECLARE @CD_PRODUCTNO		bigint			-- 지급 상품 코유번호

	SELECT @CD_COUPON = CD_COUPON
	, @CD_USERUID = CD_USERUID, @ST_USERID = ST_USERID, @NO_SERVER_SET_ID = NO_SERVER_SET_ID
	, @NO_UNITUID = NO_UNITUID, @NO_LEVEL = NO_LEVEL, @ST_USER_IP = ST_USER_IP
	, @DI_ORDER_TYPE = DI_ORDER_TYPE, @DI_ORDER_RESULT_ORG = DI_ORDER_RESULT
	, @DT_ORDER_DATE = DT_ORDER_DATE
	FROM dbo.EB_CouponOrder_UseLog WITH(NOLOCK)
	WHERE ST_TRANSACTION = @ST_TRANSACTION

	-- 주문에 없는 경우 예외 처리
	IF @@ROWCOUNT = 0 BEGIN
		-- 주문 없음
		SET @Result = -99
		GOTO END_PROC
	END

	-- 주문이 이미 처리된 경우 예외 처리
	IF @DI_ORDER_RESULT_ORG <> 1 BEGIN
		-- 처리 완료 주문(중복 처리)
		SET @Result = -11
		GOTO END_PROC
	END

	-- 정상 처리된 쿠폰이 있는 경우 예외 처리
	IF EXISTS (SELECT * FROM dbo.EB_CouponOrder WITH(NOLOCK) WHERE CD_COUPON = @CD_COUPON ) BEGIN
		-- 처리 완료 주문(중복 처리)
		SET @Result = -11
		GOTO END_PROC
	END

	-- 기본 처리 결과 정상으로 설정, 현재 시간 설정
	SELECT @Result = 0, @DT_GETDATE = GETDATE()
	SET @ST_ErrorMSG = N'[%s] dbo.EBP_CouponOrder_Result ''%s'', %d, %d, %d, %d, @NO_TOTAL_CASH = %d OUTPUT'

	SELECT @CD_PRODUCTNO = CD_PRODUCTNO FROM dbo.EB_Coupon_GiantNoToProductID WITH(NOLOCK) WHERE CD_GIANTNO = @NO_CHARGE_ITEM

	IF @@ROWCOUNT = 0
		SET @CD_PRODUCTNO = 0

	BEGIN TRY
		EXEC @Result = dbo.EBI_TransactionNumber_INT @DI_ORDER_TYPE, @CD_TRAN_NUM OUTPUT

		BEGIN TRAN

		UPDATE dbo.EB_CouponOrder_UseLog
		SET NO_CHARGE_CASH = @NO_CHARGE_CASH
		,	NO_CHARGE_BONUS = @NO_CHARGE_BONUS
		,	NO_CHARGE_ITEM = @CD_PRODUCTNO
		,	DI_ORDER_RESULT = @DI_ORDER_RESULT
		,	DT_RESULT_DATE = @DT_GETDATE
		WHERE DT_ORDER_DATE = @DT_ORDER_DATE AND ST_TRANSACTION = @ST_TRANSACTION
			AND DI_ORDER_RESULT = 1

		-- 처리된 주문이 있으면 충전 없으면 예외 처리
		IF @@ROWCOUNT = 1 BEGIN
			-- 쿠폰이 정상 처리 되었으면
			IF @DI_ORDER_RESULT = 0 BEGIN
				-- 쿠폰 사용 등록
				INSERT INTO dbo.EB_CouponOrder ( CD_TRAN_NUM, CD_COUPON, ST_TRANSACTION, CD_USERUID, ST_USERID, NO_SERVER_SET_ID, NO_UNITUID, NO_LEVEL, NO_CHARGE_CASH, NO_CHARGE_BONUS, NO_CHARGE_ITEM, ST_USER_IP, DI_ORDER_TYPE, DT_ORDER_DATE, DI_ORDER_RESULT, DT_RESULT_DATE )
				VALUES ( @CD_TRAN_NUM, @CD_COUPON, @ST_TRANSACTION, @CD_USERUID, @ST_USERID, @NO_SERVER_SET_ID, @NO_UNITUID, @NO_LEVEL, @NO_CHARGE_CASH, @NO_CHARGE_BONUS, @CD_PRODUCTNO, @ST_USER_IP, @DI_ORDER_TYPE, @DT_ORDER_DATE, @DI_ORDER_RESULT, @DT_GETDATE )

				-- 충전 캐시 또는 보너스
				IF @NO_CHARGE_CASH > 0 OR @NO_CHARGE_BONUS > 0 BEGIN
					EXEC @Result = dbo.EBI_Cash_Charge_SET @CD_USERUID, @ST_USERID, @NO_CHARGE_CASH, @NO_CHARGE_BONUS, @DT_GETDATE, @NO_REMAIN_CASH OUTPUT, @NO_REMAIN_BONUS OUTPUT

					IF @Result <> 0 BEGIN
						-- 캐시 충전 실패
						SET @Result = -1
						RAISERROR(@ST_ErrorMSG, 15, 1, 'Coupon Set', @ST_TRANSACTION, @DI_ORDER_RESULT, @CD_PRODUCTNO, @NO_CHARGE_CASH, @NO_CHARGE_BONUS, @NO_TOTAL_CASH) WITH SETERROR
					END
				END
				ELSE BEGIN
					-- 잔여 캐시확인(@NO_BEFOR_CASH, @NO_BEFOR_BONUS는 이후 프로세스에서 미 사용 변수로 프로시저 처리를 위해 임의 사용)
					EXEC dbo.EBI_Cash_Detial_SEL @CD_USERUID, @NO_REMAIN_CASH OUTPUT, @NO_REMAIN_BONUS OUTPUT
				END

				-- 아이템 지급
				IF @CD_PRODUCTNO > 0 BEGIN
					EXEC @Result = dbo.EBI_BuyCashItemLocker_SET @CD_TRAN_NUM, @CD_USERUID, @NO_SERVER_SET_ID, @CD_PRODUCTNO, 1, 0, @CD_COUPON, 0

					IF @Result <> 0 BEGIN
						RAISERROR(@ST_ErrorMSG, 15, 1, 'Coupon ItemLocker', @ST_TRANSACTION, @DI_ORDER_RESULT, @CD_PRODUCTNO, @NO_CHARGE_CASH, @NO_CHARGE_BONUS, @NO_TOTAL_CASH) WITH SETERROR
					END
				END

				-- 캐시 로그 기록
				EXEC @Result = dbo.EBI_CashLog_INT @CD_TRAN_NUM, @ST_TRANSACTION, @CD_COUPON, @CD_USERUID, @ST_USERID, @NO_SERVER_SET_ID, @NO_UNITUID, @NO_LEVEL, @CD_USERUID, @NO_UNITUID, @DI_ORDER_TYPE, @CD_PRODUCTNO, 1, @NO_CHARGE_CASH, @NO_CHARGE_BONUS, @NO_REMAIN_CASH, @NO_REMAIN_BONUS, @DT_GETDATE

				IF @Result <> 0 BEGIN
					-- 캐시로그 기록 실패
					SET @Result = -1
					RAISERROR(@ST_ErrorMSG, 15, 1, 'Coupon CashLog IN', @ST_TRANSACTION, @DI_ORDER_RESULT, @CD_PRODUCTNO, @NO_CHARGE_CASH, @NO_CHARGE_BONUS, @NO_TOTAL_CASH) WITH SETERROR
				END
			END
		END
		ELSE BEGIN
			-- 처리 완료 주문(중복 처리)
			SET @Result = -11
			RAISERROR(@ST_ErrorMSG, 15, 1, 'Coupon Duplication Result', @ST_TRANSACTION, @DI_ORDER_RESULT, @CD_PRODUCTNO, @NO_CHARGE_CASH, @NO_CHARGE_BONUS, @NO_TOTAL_CASH) WITH SETERROR
		END

		COMMIT TRAN

		SET @Result = 0
	END TRY
	BEGIN CATCH
		DECLARE @NO_XACT_STATE		smallint
		SET @NO_XACT_STATE			= XACT_STATE()		-- 트랜잭션 상태 정보

		IF @NO_XACT_STATE <> 0
			ROLLBACK TRAN

		EXEC dbo.EBI_SP_ErrorLog_INT @NO_XACT_STATE
		SET @Result = -1
	END CATCH

END_PROC:
	-- 현재 총 잔액 확인
	EXEC dbo.EBP_Cash_Total_USERUID_SEL @CD_USERUID, @NO_TOTAL_CASH OUTPUT, 0

	IF @DI_OUTPUT_RECORD = 1
		SELECT @Result AS Result, @NO_TOTAL_CASH AS NO_TOTAL_CASH, @CD_USERUID AS CD_USERUID

	RETURN @Result
GO
CREATE OR ALTER PROCEDURE [dbo].[EBP_CouponOrder_WEB_BR]
	@ST_USERID				nvarchar(40),	-- 주문 계정
	@NO_COUPONID			int,			-- 지급할 아이템
	@ST_TRANSACTION			varchar(21) 	-- 처리열 고유 문자
AS
	SET NOCOUNT ON

	-- 사용 변수 선언
	DECLARE @Result				int
	DECLARE @DT_GETDATE			datetime		-- 시간 동기화용 시간
	DECLARE @ST_ErrorMSG		nvarchar(2048)	-- 오류 메시지

	DECLARE @CD_TRAN_NUM		bigint			-- 거래 고유번호

	DECLARE @CD_COUPON			nvarchar(40)	-- 쿠폰 번호
	,	@NO_SERVER_SET_ID		tinyint			-- 서버 그룹
	,	@DI_ORDER_TYPE			smallint		-- 주문 종류
	,	@DT_ORDER_DATE			datetime		-- 주문 등록일시
	,	@CD_USERUID				bigint
	,	@DI_ORDER_RESULT		smallint		-- 주문 결과
	
	DECLARE @NO_REMAIN_CASH		int				-- 잔여 캐시
	,	@NO_REMAIN_BONUS		int				-- 잔여 보너스

	BEGIN TRY

		DECLARE @CD_PRODUCTNO		bigint			-- 지급 상품 코유번호

		SELECT @CD_USERUID = UserUID
		FROM [Account].[dbo].[MUser] AS A WITH(NOLOCK)
		WHERE UserID = @ST_USERID
		
		IF @@ROWCOUNT = 0 BEGIN
			-- 존재하지 않는 캐릭터
			SET @Result = -100
			RAISERROR('dbo.EBP_CouponOrder_Result Coupon Not Exists User %s, %d, %s', 15, 1, @ST_USERID, @NO_COUPONID, @ST_TRANSACTION) WITH SETERROR
		END



		-- 기본 처리 결과 정상으로 설정, 현재 시간 설정
		SELECT @Result = 0, @DT_GETDATE = GETDATE()
		SET @ST_ErrorMSG = N'[%s] dbo.EBP_CouponOrder_Result ''%s'', %d, %d'

		SELECT @CD_PRODUCTNO = CD_PRODUCTNO FROM dbo.EB_Coupon_GiantNoToProductID WITH(NOLOCK) WHERE CD_GIANTNO = @NO_COUPONID

		IF @@ROWCOUNT = 0
		BEGIN
			SET @CD_PRODUCTNO = 0
			RAISERROR('dbo.EBP_CouponOrder_Result Coupon Not Exists Coupon %s, %d, %s', 15, 1, @ST_USERID, @NO_COUPONID, @ST_TRANSACTION) WITH SETERROR
		END

		SET @DI_ORDER_TYPE = 9
		
		SET @DT_ORDER_DATE = @DT_GETDATE
		SET @NO_SERVER_SET_ID = 0
		SET @DI_ORDER_RESULT = 0
		
	
		EXEC @Result = dbo.EBI_TransactionNumber_INT @DI_ORDER_TYPE, @CD_TRAN_NUM OUTPUT
		
		SET @CD_COUPON = @CD_TRAN_NUM
		

		BEGIN TRAN

			-- 쿠폰이 정상 처리 되었으면
			IF @DI_ORDER_RESULT = 0 BEGIN
				-- 쿠폰 사용 등록
				INSERT INTO dbo.EB_CouponOrder ( CD_TRAN_NUM, CD_COUPON, ST_TRANSACTION, CD_USERUID, ST_USERID, NO_SERVER_SET_ID, NO_UNITUID, NO_LEVEL, NO_CHARGE_CASH, NO_CHARGE_BONUS, NO_CHARGE_ITEM, ST_USER_IP, DI_ORDER_TYPE, DT_ORDER_DATE, DI_ORDER_RESULT, DT_RESULT_DATE )
				VALUES ( @CD_TRAN_NUM, @CD_COUPON, @ST_TRANSACTION, @CD_USERUID, @ST_USERID, @NO_SERVER_SET_ID, 0, 0, 0, 0, @CD_PRODUCTNO, N'', @DI_ORDER_TYPE, @DT_ORDER_DATE, @DI_ORDER_RESULT, @DT_GETDATE )

				
				-- 아이템 지급
				IF @CD_PRODUCTNO > 0 BEGIN
					EXEC @Result = dbo.EBI_BuyCashItemLocker_SET @CD_TRAN_NUM, @CD_USERUID, @NO_SERVER_SET_ID, @CD_PRODUCTNO, 1, 0, @CD_COUPON, 0

					IF @Result <> 0 BEGIN
						RAISERROR(@ST_ErrorMSG, 15, 1, 'Coupon ItemLocker', @ST_TRANSACTION, @DI_ORDER_RESULT, @CD_PRODUCTNO) WITH SETERROR
					END
				END
				
				-- 잔여 캐시확인(@NO_BEFOR_CASH, @NO_BEFOR_BONUS는 이후 프로세스에서 미 사용 변수로 프로시저 처리를 위해 임의 사용)
				EXEC dbo.EBI_Cash_Detial_SEL @CD_USERUID, @NO_REMAIN_CASH OUTPUT, @NO_REMAIN_BONUS OUTPUT

				-- 캐시 로그 기록
				EXEC @Result = dbo.EBI_CashLog_INT @CD_TRAN_NUM, @ST_TRANSACTION, @CD_COUPON, @CD_USERUID, @ST_USERID, @NO_SERVER_SET_ID, 0, 0, @CD_USERUID, 0, @DI_ORDER_TYPE, @CD_PRODUCTNO, 1, 0, 0, @NO_REMAIN_CASH, @NO_REMAIN_BONUS, @DT_GETDATE

				IF @Result <> 0 BEGIN
					-- 캐시로그 기록 실패
					SET @Result = -1
					RAISERROR(@ST_ErrorMSG, 15, 1, 'Coupon CashLog IN', @ST_TRANSACTION, @DI_ORDER_RESULT, @CD_PRODUCTNO) WITH SETERROR					
				END
			END

		COMMIT TRAN

		SET @Result = 0
	END TRY
	BEGIN CATCH
		DECLARE @NO_XACT_STATE		smallint
		SET @NO_XACT_STATE			= XACT_STATE()		-- 트랜잭션 상태 정보

		IF @NO_XACT_STATE <> 0
			ROLLBACK TRAN

		EXEC dbo.EBI_SP_ErrorLog_INT @NO_XACT_STATE
		IF @Result = 0 SET @Result = -1
	END CATCH

END_PROC:
	RETURN @Result
GO
/*
프로시저명 : dbo.EBP_CouponOrder_USE
내용 : 쿠폰 사용
작성일 : 2012-09-04
작성자 : KOG_M
수정일 :
수정자 :
수정내용 :
-- ## 관련 테이블 ##--
	dbo.EB_Coupon_GroupList
	dbo.EB_Coupon_List
	dbo.EB_Coupon_Group_UseCount
-- ## 관련 프로시저 ## --
	dbo.EBI_Cash_Detial_SEL
	dbo.EBI_TransactionNumber_INT
	dbo.EBI_Cash_Charge_SET
	dbo.EBI_BuyCashItemLocker_SET
	dbo.EBI_CashLog_INT
	dbo.EBI_SP_ErrorLog_INT
-- ## 입력 ## --
	@CD_COUPON				nvarchar(40)			-- 쿠폰 번호
	@CD_USERUID				bigint					-- 계정 UID
	@ST_USERID				nvarchar(50)			-- 계정 아이디
	@NO_SERVER_SET_ID		tinyint					-- 서버 그룹
	@NO_UNITUID				bigint					-- 캐릭터 UID
	@NO_LEVEL				tinyint					-- 캐릭터 레벨
-- ## 출력 ## --
	Output :
		@NO_TOTAL_CASH			int					-- 총 잔여 캐시
		@NO_CHARGE_ITEM			int					-- 지급 아이템(상품) 번호
		@NO_CHARGE_BONUS		int					-- 지급 보너스 캐시
		@NO_CHARGE_CASH			int					-- 지급 캐시
		@CD_TRAN_NUM			bigint				-- 거래 고유번호
		@NO_REMAIN_CASH			int					-- 잔여 캐시
		@NO_REMAIN_BONUS		int					-- 잔여 보너스
	ReturnValue : 있음
	RecodeSet : 선택
		Result, NO_TOTAL_CASH, NO_CHARGE_ITEM, NO_CHARGE_BONUS, NO_CHARGE_CASH, CD_TRAN_NUM, NO_REMAIN_CASH, NO_REMAIN_BONUS, DI_OUTPUT_RECORD
		SP 처리 결과, 총 잔여 캐시, 지급 아이템(상품) 번호, 지급 보너스 캐시, 지급 캐시, 거래 고유번호, 잔여 캐시, 잔여 보너스
-- ## 실행 ## --
	DECLARE @Result		int
	,	@CD_COUPON				nvarchar(40)			-- 쿠폰 번호
	,	@CD_USERUID				bigint					-- 계정 UID
	,	@ST_USERID				nvarchar(50)			-- 계정 아이디
	,	@NO_SERVER_SET_ID		tinyint					-- 서버 그룹
	,	@NO_UNITUID				bigint					-- 캐릭터 UID
	,	@NO_LEVEL				tinyint					-- 캐릭터 레벨

	,	@NO_TOTAL_CASH			int						-- 총 잔여 캐시
	,	@NO_CHARGE_ITEM			int						-- 지급 아이템(상품) 번호
	,	@NO_CHARGE_BONUS		int						-- 지급 보너스 캐시
	,	@NO_CHARGE_CASH			int						-- 지급 캐시
	,	@CD_TRAN_NUM			bigint					-- 거래 고유번호
	,	@NO_REMAIN_CASH			int						-- 잔여 캐시
	,	@NO_REMAIN_BONUS		int						-- 잔여 보너스
	,	@DI_OUTPUT_RECORD		bit						-- 결과 RecordSet 출력 여부

	SET @DI_OUTPUT_RECORD = 0

	SELECT TOP 1
		@CD_USERUID			= A.UserUID
	,	@ST_USERID			= A.UserID
	,	@NO_SERVER_SET_ID	= 1
	,	@NO_UNITUID			= B.UnitUID
	,	@NO_LEVEL			= B.[Level]
	FROM [Account].[dbo].[MUser] AS A WITH(NOLOCK)
	JOIN [Game01].[dbo].[GUnit] AS B WITH(NOLOCK)
		ON A.UserUID = B.UserUID
	--WHERE EXISTS (SELECT * FROM [Game01].[dbo].[GUnitNickName] WITH(NOLOCK) WHERE NickName = N'AAA')
	--WHERE A.UserID = N''
	WHERE B.Deleted = 0
	ORDER BY NEWID()

	IF @@ROWCOUNT = 1 BEGIN
		SELECT TOP 1 @CD_COUPON = CD_COUPON
		FROM dbo.EB_Coupon_List WITH(NOLOCK)
		WHERE CD_USERUID IS NULL
		--WHERE CD_USERUID IS NOT NULL
		ORDER BY NEWID()

		IF @@ROWCOUNT = 1 BEGIN
			EXEC @Result = dbo.EBP_CouponOrder_USE @CD_COUPON, @CD_USERUID, @ST_USERID, @NO_SERVER_SET_ID, @NO_UNITUID, @NO_LEVEL, @NO_TOTAL_CASH OUTPUT, @NO_CHARGE_ITEM OUTPUT, @NO_CHARGE_BONUS OUTPUT, @NO_CHARGE_CASH OUTPUT, @CD_TRAN_NUM OUTPUT, @NO_REMAIN_CASH OUTPUT, @NO_REMAIN_BONUS OUTPUT, @DI_OUTPUT_RECORD
			SELECT @Result AS Result, @NO_TOTAL_CASH AS NO_TOTAL_CASH, @NO_CHARGE_ITEM AS NO_CHARGE_ITEM, @NO_CHARGE_BONUS AS NO_CHARGE_BONUS, @NO_CHARGE_CASH AS NO_CHARGE_CASH, @CD_TRAN_NUM AS CD_TRAN_NUM, @NO_REMAIN_CASH AS NO_REMAIN_CASH, @NO_REMAIN_BONUS AS NO_REMAIN_BONUS
		END
	END
	SELECT @CD_COUPON, @CD_USERUID, @ST_USERID, @NO_SERVER_SET_ID, @NO_UNITUID, @NO_LEVEL
	SELECT @@TRANCOUNT
*/


CREATE OR ALTER PROCEDURE [dbo].[EBP_CouponOrder_USE]
	@CD_COUPON				nvarchar(40) ,			-- 쿠폰 번호
	@CD_USERUID				bigint ,				-- 계정 UID
	@ST_USERID				nvarchar(50) ,			-- 계정 아이디dhd
	@NO_SERVER_SET_ID		tinyint ,				-- 서버 그룹
	@NO_UNITUID				bigint ,				-- 캐릭터 UID
	@NO_LEVEL				tinyint ,				-- 캐릭터 레벨
	@NO_CHANNEL_CODE		tinyint = 0 ,			-- 채널링 코드 (2013-05-11 추가)
	@NO_COUNT				int,					-- 아이템 수량?
	@NO_TOTAL_CASH			int = 0	OUTPUT ,		-- 총 잔여 캐시
	@NO_CHARGE_ITEM			bigint = 0 OUTPUT ,		-- 지급 아이템(상품) 번호
	@NO_CHARGE_BONUS		int = 0	OUTPUT ,		-- 지급 보너스 캐시
	@NO_CHARGE_CASH			int = 0	OUTPUT ,		-- 지급 캐시
	@CD_TRAN_NUM			bigint = 0 OUTPUT ,		-- 거래 고유번호
	@NO_REMAIN_CASH			int = 0 OUTPUT ,		-- 잔여 캐시
	@NO_REMAIN_BONUS		int = 0 OUTPUT ,		-- 잔여 보너스
	@DI_OUTPUT_RECORD		bit = 1					-- 결과 RecordSet 출력 여부
AS
	SET NOCOUNT ON

	-- 사용 변수 선언
	DECLARE @Result				int
	DECLARE @DT_GETDATE			datetime		-- 충전 시간 동기화용 시간
	DECLARE @ST_ErrorMSG		nvarchar(2048)	-- 오류 메시지
	DECLARE @CouponGroup		int
	DECLARE @CouponGroup1		int

	DECLARE @NO_USE_CASH		int
	,	@NO_USE_BONUS			int

	DECLARE @DI_CASH_LOG_TYPE	smallint

	-- 상품 관련
	DECLARE @CD_COUPON_GROUP_NUM	int
	,		@DI_FLAG				CHAR(1)
	,		@DI_DUPLICATE_USE		bit
	,		@DT_USE_START_DATE		smalldatetime
	,		@DT_USE_END_DATE		smalldatetime
	,		@NO_USABLE_COUNT_CASH	int
	,		@NO_USABLE_COUNT_BONUS	int
	,		@NO_USABLE_COUNT_ITEM	int
	,		@CD_USERUID_COUPON		bigint
	,		@DI_FLAG_COUPON			char(1)

	-- 기본 처리 결과 정상으로 설정, 현재 시간 설정
	SELECT @Result = 0, @DT_GETDATE = GETDATE()
	SET @ST_ErrorMSG = N'[%s] dbo.EBP_CouponOrder_USE ''%s'', %I64d, ''%s'', %d, %I64d, %d, @NO_TOTAL_CASH = %d OUTPUT, @NO_CHARGE_ITEM = %d OUTPUT, @NO_CHARGE_BONUS = %d OUTPUT, @NO_CHARGE_CASH = %d OUTPUT, @CD_TRAN_NUM = %I64d OUTPUT, @NO_REMAIN_CASH = %d OUTPUT, @NO_REMAIN_BONUS = %d OUTPUT'

	-- 현재 총 잔액 확인
	EXEC dbo.EBI_Cash_Detial_SEL @CD_USERUID, @NO_REMAIN_CASH OUTPUT, @NO_REMAIN_BONUS OUTPUT

	SET @NO_TOTAL_CASH = @NO_REMAIN_CASH + @NO_REMAIN_BONUS

	-- 쿠폰 정보 확인
	SELECT @CD_COUPON_GROUP_NUM = A.CD_COUPON_GROUP_NUM
	, @DI_FLAG = A.DI_FLAG
	, @DI_DUPLICATE_USE = A.DI_DUPLICATE_USE
	, @DT_USE_START_DATE = A.DT_USE_START_DATE
	, @DT_USE_END_DATE = A.DT_USE_END_DATE
	, @NO_CHARGE_CASH = A.NO_CHARGE_CASH
	, @NO_CHARGE_BONUS = A.NO_CHARGE_BONUS
	, @NO_CHARGE_ITEM = A.NO_CHARGE_ITEM
	, @NO_USABLE_COUNT_CASH = A.NO_USABLE_COUNT_CASH
	, @NO_USABLE_COUNT_BONUS = A.NO_USABLE_COUNT_BONUS
	, @NO_USABLE_COUNT_ITEM = A.NO_USABLE_COUNT_ITEM
	, @CD_USERUID_COUPON = B.CD_USERUID
	, @DI_FLAG_COUPON = B.DI_FLAG
	, @DI_CASH_LOG_TYPE = 9									-- 쿠폰 사용 타입 9
	FROM dbo.EB_Coupon_GroupList AS A WITH(NOLOCK)
	JOIN dbo.EB_Coupon_List AS B WITH(NOLOCK)
		ON A.CD_COUPON_GROUP_NUM = B.CD_COUPON_GROUP_NUM
	WHERE B.CD_COUPON = @CD_COUPON
	
	--SET @CD_COUPON_GROUP_NUM = @CouponGroup

	-- 사용 상품 아님
	IF @@ROWCOUNT <> 1 BEGIN
		SET @Result = -29
		GOTO END_PROC
	END
	
	-- 수량이 잘못 됨
	IF @NO_COUNT <> 1 BEGIN
		SET @Result = -30
		GOTO END_PROC
	END

	IF @CD_USERUID_COUPON IS NOT NULL BEGIN
		SET @Result = -11
		GOTO END_PROC
	END

	IF @DI_FLAG_COUPON <> 'A' OR @DI_FLAG <> 'A' BEGIN
		SET @Result = -99
		GOTO END_PROC
	END
	
	-- 중복사용 가능 여부 확인
	IF @DI_DUPLICATE_USE = 0
	BEGIN
		-- 같은 그룹의 쿠폰 한번만 사용 가능하게 처리 
		IF EXISTS (SELECT CD_COUPON_GROUP_NUM  FROM dbo.EB_Coupon_Group_UseCount WITH(NOLOCK)
					WHERE CD_USERUID = @CD_USERUID AND CD_COUPON_GROUP_NUM = @CD_COUPON_GROUP_NUM) 
		BEGIN	
				SET @Result = -38
				GOTO END_PROC
		END
	END

	-- 사용 기간 아님
	IF NOT (@DT_GETDATE BETWEEN ISNULL(@DT_USE_START_DATE, DATEADD(MI, -1, @DT_GETDATE)) AND ISNULL(@DT_USE_END_DATE, DATEADD(MI, 1, @DT_GETDATE))) BEGIN
		SET @Result = -23
		GOTO END_PROC
	END


	-- 처리 고유번호 발행
	EXEC @Result = dbo.EBI_TransactionNumber_INT @DI_CASH_LOG_TYPE, @CD_TRAN_NUM OUTPUT

	IF @Result = 0 BEGIN
		BEGIN TRY
			BEGIN TRAN

				-- 쿠폰 사용 처리
				UPDATE dbo.EB_Coupon_List
				SET CD_USERUID = @CD_USERUID
				,	DI_FLAG = 'E'
				WHERE CD_COUPON = @CD_COUPON
					AND CD_USERUID IS NULL
					AND DI_FLAG = 'A'

				IF @@ROWCOUNT = 0 BEGIN
					-- 구매 수량 제한
					SET @Result = -11
					RAISERROR(@ST_ErrorMSG, 15, 1, N'Order Coupon Set', @CD_COUPON, @CD_USERUID, @ST_USERID, @NO_SERVER_SET_ID, @NO_UNITUID, @NO_LEVEL, @NO_TOTAL_CASH, @NO_CHARGE_ITEM, @NO_CHARGE_BONUS, @NO_CHARGE_CASH, @CD_TRAN_NUM, @NO_REMAIN_CASH, @NO_REMAIN_BONUS) WITH SETERROR
				END

				IF NOT EXISTS (SELECT * FROM dbo.EB_Coupon_Group_UseCount WITH(NOLOCK) WHERE CD_COUPON_GROUP_NUM = @CD_COUPON_GROUP_NUM AND CD_USERUID = @CD_USERUID ) BEGIN
					INSERT INTO dbo.EB_Coupon_Group_UseCount ( CD_COUPON_GROUP_NUM, CD_USERUID, NO_USE_COUNT_CASH, NO_USE_COUNT_BONUS, NO_USE_COUNT_ITEM )
					SELECT @CD_COUPON_GROUP_NUM, @CD_USERUID
					, CASE WHEN @NO_CHARGE_CASH > 0 THEN 1 ELSE 0 END
					, CASE WHEN @NO_CHARGE_BONUS > 0 THEN 1 ELSE 0 END
					, CASE WHEN @NO_CHARGE_ITEM > 0 THEN 1 ELSE 0 END
				END
				ELSE BEGIN
					UPDATE dbo.EB_Coupon_Group_UseCount
					SET NO_USE_COUNT_CASH = NO_USE_COUNT_CASH + CASE WHEN (NO_USE_COUNT_CASH < @NO_USABLE_COUNT_CASH OR @NO_USABLE_COUNT_CASH = 0) AND @NO_CHARGE_CASH > 0 THEN 1 ELSE 0 END
					, NO_USE_COUNT_BONUS = NO_USE_COUNT_BONUS + CASE WHEN (NO_USE_COUNT_BONUS < @NO_USABLE_COUNT_BONUS OR @NO_USABLE_COUNT_BONUS = 0) AND @NO_CHARGE_BONUS > 0 THEN 1 ELSE 0 END
					, NO_USE_COUNT_ITEM = NO_USE_COUNT_ITEM + CASE WHEN (NO_USE_COUNT_ITEM < @NO_USABLE_COUNT_ITEM OR @NO_USABLE_COUNT_ITEM = 0) AND @NO_CHARGE_ITEM > 0 THEN 1 ELSE 0 END
					, @NO_CHARGE_CASH = CASE WHEN (NO_USE_COUNT_CASH < @NO_USABLE_COUNT_CASH OR @NO_USABLE_COUNT_CASH = 0) THEN @NO_CHARGE_CASH ELSE 0 END
					, @NO_CHARGE_BONUS = CASE WHEN (NO_USE_COUNT_BONUS < @NO_USABLE_COUNT_BONUS OR @NO_USABLE_COUNT_BONUS = 0) THEN @NO_CHARGE_BONUS ELSE 0 END
					, @NO_CHARGE_ITEM = CASE WHEN (NO_USE_COUNT_ITEM < @NO_USABLE_COUNT_ITEM OR @NO_USABLE_COUNT_ITEM = 0) THEN @NO_CHARGE_ITEM ELSE 0 END
					WHERE CD_COUPON_GROUP_NUM = @CD_COUPON_GROUP_NUM
						AND CD_USERUID = @CD_USERUID

					IF @NO_CHARGE_ITEM = 0 AND @NO_CHARGE_BONUS = 0 AND @NO_CHARGE_ITEM = 0 BEGIN
						-- 구매 수량 제한
						SET @Result = -26
						RAISERROR(@ST_ErrorMSG, 15, 1, N'Order Coupon UseCountSet', @CD_COUPON, @CD_USERUID, @ST_USERID, @NO_SERVER_SET_ID, @NO_UNITUID, @NO_LEVEL, @NO_TOTAL_CASH, @NO_CHARGE_ITEM, @NO_CHARGE_BONUS, @NO_CHARGE_CASH, @CD_TRAN_NUM, @NO_REMAIN_CASH, @NO_REMAIN_BONUS) WITH SETERROR
					END
				END

				IF (@NO_CHARGE_CASH > 0 OR @NO_CHARGE_BONUS > 0) BEGIN
					-- 캐시 충전
					EXEC @Result = dbo.EBI_Cash_Charge_SET @CD_USERUID, @ST_USERID, @NO_CHARGE_CASH, @NO_CHARGE_BONUS, @DT_GETDATE, @NO_REMAIN_CASH OUTPUT, @NO_REMAIN_BONUS OUTPUT

					IF @Result <> 0 BEGIN
						-- 캐시 충전 실패
						SET @Result = -1
						RAISERROR(@ST_ErrorMSG, 15, 1, N'Order Coupon ChargeCash', @CD_COUPON, @CD_USERUID, @ST_USERID, @NO_SERVER_SET_ID, @NO_UNITUID, @NO_LEVEL, @NO_TOTAL_CASH, @NO_CHARGE_ITEM, @NO_CHARGE_BONUS, @NO_CHARGE_CASH, @CD_TRAN_NUM, @NO_REMAIN_CASH, @NO_REMAIN_BONUS) WITH SETERROR
					END
					SET @NO_TOTAL_CASH = @NO_REMAIN_CASH + @NO_REMAIN_BONUS
				END

				IF @NO_CHARGE_ITEM > 0 BEGIN
					EXEC @Result = dbo.EBI_BuyCashItemLocker_SET @CD_TRAN_NUM, @CD_USERUID, @NO_SERVER_SET_ID, @NO_CHARGE_ITEM, 1, 0, @CD_COUPON

					IF @Result <> 0 BEGIN
						-- 아이템 지급 실패
						SET @Result = -1
						RAISERROR(@ST_ErrorMSG, 15, 1, N'Order Coupon Insert Item', @CD_COUPON, @CD_USERUID, @ST_USERID, @NO_SERVER_SET_ID, @NO_UNITUID, @NO_LEVEL, @NO_TOTAL_CASH, @NO_CHARGE_ITEM, @NO_CHARGE_BONUS, @NO_CHARGE_CASH, @CD_TRAN_NUM, @NO_REMAIN_CASH, @NO_REMAIN_BONUS) WITH SETERROR
					END
				END

				-- 캐시 로그 기록(구매 완료시)
				EXEC @Result = dbo.EBI_CashLog_INT @CD_TRAN_NUM, @CD_COUPON, @CD_COUPON, @CD_USERUID, @ST_USERID, @NO_SERVER_SET_ID, @NO_UNITUID, @NO_LEVEL, @CD_USERUID, @NO_UNITUID, @DI_CASH_LOG_TYPE, @NO_CHARGE_ITEM, 1, @NO_CHARGE_CASH, @NO_CHARGE_BONUS, @NO_REMAIN_CASH, @NO_REMAIN_BONUS, @DT_GETDATE, @NO_CHANNEL_CODE

				IF @Result <> 0 BEGIN
					-- 캐시로그 기록 실패
					SET @Result = -1
					RAISERROR(@ST_ErrorMSG, 15, 1, N'Order Coupon Insert Log', @CD_COUPON, @CD_USERUID, @ST_USERID, @NO_SERVER_SET_ID, @NO_UNITUID, @NO_LEVEL, @NO_TOTAL_CASH, @NO_CHARGE_ITEM, @NO_CHARGE_BONUS, @NO_CHARGE_CASH, @CD_TRAN_NUM, @NO_REMAIN_CASH, @NO_REMAIN_BONUS) WITH SETERROR
				END

				-- 총 사용 쿠폰 수 갱신
				UPDATE dbo.EB_Coupon_GroupList
				SET NO_USE_COUPON_COUNT = NO_USE_COUPON_COUNT + 1
				WHERE CD_COUPON_GROUP_NUM = @CD_COUPON_GROUP_NUM
			COMMIT TRAN

		END TRY
		BEGIN CATCH
			DECLARE @NO_XACT_STATE		smallint
			SET @NO_XACT_STATE			= XACT_STATE()		-- 트랜잭션 상태 정보

			IF @NO_XACT_STATE <> 0
				ROLLBACK TRAN

			EXEC dbo.EBI_SP_ErrorLog_INT @NO_XACT_STATE

			-- 별도 예외 처리가 아닌경우 DB오류
			IF @Result = 0
				SET @Result = -1
		END CATCH
	END

END_PROC:
	IF @Result <> 0
		SELECT @NO_CHARGE_ITEM = 0, @NO_CHARGE_BONUS = 0, @NO_CHARGE_CASH = 0

	IF @DI_OUTPUT_RECORD = 1
		SELECT @Result AS Result, @NO_TOTAL_CASH AS NO_TOTAL_CASH, @NO_CHARGE_ITEM AS NO_CHARGE_ITEM, @NO_CHARGE_BONUS AS NO_CHARGE_BONUS, @NO_CHARGE_CASH AS NO_CHARGE_CASH, @CD_TRAN_NUM AS CD_TRAN_NUM, @NO_REMAIN_CASH AS NO_REMAIN_CASH, @NO_REMAIN_BONUS AS NO_REMAIN_BONUS

	RETURN @Result
GO
/*
프로시저명 : dbo.EBP_BillOrder_GameServer_SET
내용 : 주문 등록
작성일 : 2011-02-15
작성자 : 김병일
-- ## 관련 테이블 ##--
	없음
-- ## 관련 프로시저 ## --
	dbo.EBI_TransactionNumber_INT
	dbo.EBI_BillOrder_SET
	dbo.EBI_SP_ErrorLog_INT
-- ## 입력 ## --
	@ST_TRANSACTION		varchar(21)			-- 처리열 고유 문자
	@CD_USERUID			bigint				-- 계정 UID
	@ST_USERID			nvarchar(50)		-- 계정 아이디
	@NO_SERVER_SET_ID	tinyint				-- 서버 그룹
	@NO_UNITUID			bigint				-- 캐릭터 UID
	@NO_LEVEL			tinyint				-- 캐릭터 레벨
	@NO_CHARGE_CASH		int					-- 충전 캐시
	@ST_USER_IP			varchar(16)			-- 유저 아이피
	@DI_ORDER_TYPE		tinyint				-- 주문 종류
-- ## 출력 ## --
	Output : 없음
	ReturnValue : 있음
	RecodeSet : 선택
		Result
		SP 처리 결과
-- ## 실행 ## --
	DECLARE @Result			int
	,	@ST_TRANSACTION		varchar(21)			-- 처리열 고유 문자
	,	@CD_USERUID			bigint				-- 계정 UID
	,	@ST_USERID			nvarchar(50)		-- 계정 아이디
	,	@NO_SERVER_SET_ID	tinyint				-- 서버 그룹
	,	@NO_UNITUID			bigint				-- 캐릭터 UID
	,	@NO_LEVEL			tinyint				-- 캐릭터 레벨
	,	@NO_CHARGE_CASH		int					-- 충전 캐시
	,	@ST_USER_IP			varchar(16)			-- 유저 아이피
	,	@DI_ORDER_TYPE		tinyint				-- 주문 종류
	,	@DI_OUTPUT_RECORD	bit					-- 결과 RecordSet 출력 여부


	SELECT @CD_USERUID		= CAST((CAST(RAND() * 10000000000 AS bigint) / (CAST(RAND() * 100 AS tinyint) + 1)) AS bigint) + 1
	,	@NO_SERVER_SET_ID	= CAST(RAND() * 10 / 2 AS tinyint) + 1
	,	@NO_UNITUID			= CAST((CAST(RAND() * 10000000000 AS bigint) / (CAST(RAND() * 100 AS tinyint) + 1)) AS bigint) + 1
	,	@NO_LEVEL			= CAST(RAND() * 58 AS tinyint) + 1
	,	@NO_CHARGE_CASH		= CAST(RAND() * 100 AS INT) * 10 + 10
	,	@ST_USER_IP			= '127.0.0.1'
	,	@DI_ORDER_TYPE		= CAST(RAND() * 7 AS tinyint) + 1


	SET @DI_OUTPUT_RECORD	= 0

	DECLARE @NO_DATE_TRAN_NUM	int					-- 일별 발행 번호
	EXEC dbo.EBP_TranNumberServer_INT @NO_DATE_TRAN_NUM OUTPUT, @DI_OUTPUT_RECORD

	SET @ST_TRANSACTION		= LEFT(N'O'+ RIGHT(REPLACE(REPLACE(REPLACE(REPLACE(CONVERT(varchar(23), GETDATE(), 121), '-', ''), ' ', ''), ':', ''), '.', ''), 14) + RIGHT('0000' + CAST(@NO_DATE_TRAN_NUM AS varchar(4)), 4) + RIGHT(CAST(@CD_USERUID AS varchar(10)), 10), 21)
	SET @ST_USERID			= 'TestAcc' + CAST(@CD_USERUID AS varchar(12))

	SET @DI_OUTPUT_RECORD	= 0

	EXEC @Result = dbo.EBP_BillOrder_GameServer_SET @ST_TRANSACTION, @CD_USERUID, @ST_USERID, @NO_SERVER_SET_ID, @NO_UNITUID, @NO_LEVEL, @NO_CHARGE_CASH, @ST_USER_IP, @DI_ORDER_TYPE, @DI_OUTPUT_RECORD
	SELECT @Result AS Result
*/
CREATE OR ALTER PROCEDURE [dbo].[EBP_BillOrder_GameServer_SET]
	@ST_TRANSACTION		varchar(21) ,			-- 처리열 고유 문자
	@CD_USERUID			bigint ,				-- 계정 UID
	@ST_USERID			nvarchar(50) ,			-- 계정 아이디
	@NO_SERVER_SET_ID	tinyint ,				-- 서버 그룹
	@NO_UNITUID			bigint ,				-- 캐릭터 UID
	@NO_LEVEL			tinyint ,				-- 캐릭터 레벨
	@NO_CHARGE_CASH		int ,					-- 충전 캐시
	@ST_USER_IP			varchar(16) ,			-- 유저 아이피
	@DI_ORDER_TYPE		tinyint ,				-- 주문 종류
	@DI_OUTPUT_RECORD	bit = 1					-- 결과 RecordSet 출력 여부
AS
	SET NOCOUNT ON

	-- 사용 변수 선언
	DECLARE @Result				int
	DECLARE @CD_TRAN_NUM		bigint			-- 거래 고유번호

	-- 10으로 나누어 나머지가 있으면 오류
	IF @NO_CHARGE_CASH % 10 <> 0 BEGIN
		SET @Result = -13
	END
	ELSE BEGIN
		-- 1:10(엘소드캐시:자이언트 캐시) 충전 비율 적용
		SET @NO_CHARGE_CASH = @NO_CHARGE_CASH / 10

		-- 처리 고유번호 발행
		EXEC @Result = dbo.EBI_TransactionNumber_INT @DI_ORDER_TYPE, @CD_TRAN_NUM OUTPUT

		IF @Result = 0 BEGIN
			BEGIN TRY
				BEGIN TRAN


				EXEC dbo.EBI_BillOrder_SET @CD_TRAN_NUM, @ST_TRANSACTION, @CD_USERUID, @ST_USERID, @NO_SERVER_SET_ID, @NO_UNITUID, @NO_LEVEL, @NO_CHARGE_CASH, @ST_USER_IP, @DI_ORDER_TYPE

				COMMIT TRAN
			END TRY
			BEGIN CATCH
				DECLARE @NO_XACT_STATE		smallint
				SET @NO_XACT_STATE			= XACT_STATE()		-- 트랜잭션 상태 정보

				IF @NO_XACT_STATE <> 0
					ROLLBACK TRAN

				EXEC dbo.EBI_SP_ErrorLog_INT @NO_XACT_STATE
				SET @Result = -1
			END CATCH
		END
	END

	IF @DI_OUTPUT_RECORD = 1
		SELECT @Result AS Result

	RETURN @Result
GO
/*
프로시저명 : dbo.EBP_BillOrder_Bonus_SET
내용 : 보너스 캐시 충전 전용
작성일 : 2011-11-11
작성자 : KOG_M
-- ## 관련 테이블 ##--
	dbo.EB_BillOrder
-- ## 관련 프로시저 ## --
	dbo.EBI_TransactionNumber_INT
	dbo.EBI_Cash_Charge_SET
	dbo.EBI_CashLog_INT
	dbo.EBI_SP_ErrorLog_INT
-- ## 입력 ## --
	@ST_TRANSACTION_BASE	varchar(21)				-- 처리열 고유 문자
	@CD_USERUID				bigint					-- 계정 UID
	@ST_USERID				nvarchar(50)			-- 계정 아이디
	@NO_SERVER_SET_ID		tinyint					-- 서버 그룹
	@ST_USER_IP				varchar(16)				-- 유저 아이피
	@NO_CHARGE_BONUS		int						-- 충전 보너스
	@DI_ORDER_TYPE			tinyint					-- 보너스 종류 (51:충전 / 52:이벤트 / 53:보상 / 61:테스트)
	@NO_TOTAL_CASH			int						-- 충전 후 총 캐시
	@DI_OUTPUT_RECORD		bit						-- 결과 RecordSet 출력 여부
-- ## 출력 ## --
	Output : 없음
	ReturnValue : 있음
	RecodeSet : 선택
		Result
		SP 처리 결과[기본 결과 외 [-1001 : 충전 횟수 이상(5회 이상)]]
-- ## 실행 ## --
	DECLARE @Result				int
	,	@ST_TRANSACTION_BASE	varchar(20)				-- 처리열 고유 문자
	,	@CD_USERUID				bigint					-- 계정 UID
	,	@ST_USERID				nvarchar(50)			-- 계정 아이디
	,	@NO_SERVER_SET_ID		tinyint					-- 서버 그룹
	,	@ST_USER_IP				varchar(16)				-- 유저 아이피
	,	@NO_CHARGE_BONUS		int						-- 충전된 캐시
	,	@DI_ORDER_TYPE			tinyint					-- 보너스 종류 (51:충전 / 52:이벤트 / 53:보상 / 61:테스트)
	,	@NO_TOTAL_CASH			int						-- 충전 후 총 캐시
	,	@DI_OUTPUT_RECORD		bit						-- 결과 RecordSet 출력 여부

	SELECT @CD_USERUID = UserUID, @ST_USERID = USERID
	,	@NO_SERVER_SET_ID =
	,	@ST_USER_IP = ''
	,	@NO_CHARGE_BONUS = 0
	,	@DI_ORDER_TYPE = 61
	FROM [Account].[dbo].[MUser] WITH(NOLOCK)
	WHERE UserID = ''
	
	IF @@ROWCOUNT = 1 BEGIN
		SET @DI_OUTPUT_RECORD	= 0

		DECLARE @NO_DATE_TRAN_NUM	int					-- 일별 발행 번호
		EXEC dbo.EBP_TranNumberServer_INT @NO_DATE_TRAN_NUM OUTPUT, @DI_OUTPUT_RECORD

		SET @ST_TRANSACTION_BASE		= 'TEST'
		
		SET @DI_OUTPUT_RECORD	= 0

		EXEC @Result = dbo.EBP_BillOrder_Bonus_SET @ST_TRANSACTION_BASE, @CD_USERUID, @ST_USERID, @NO_SERVER_SET_ID, @ST_USER_IP, @NO_CHARGE_BONUS, @DI_ORDER_TYPE, @NO_TOTAL_CASH OUTPUT, @DI_OUTPUT_RECORD
	END
	SELECT @Result AS Result, @NO_TOTAL_CASH AS NO_TOTAL_CASH
*/
CREATE OR ALTER PROCEDURE [dbo].[EBP_BillOrder_Bonus_SET]
	@ST_TRANSACTION_BASE		varchar(20)				-- 처리열 고유 문자
,	@CD_USERUID					bigint					-- 계정 UID
,	@ST_USERID					nvarchar(50)			-- 계정 아이디
,	@NO_SERVER_SET_ID			tinyint					-- 서버 그룹
,	@ST_USER_IP					varchar(16)				-- 유저 아이피
,	@NO_CHARGE_BONUS			int						-- 충전 보너스
,	@DI_ORDER_TYPE				tinyint					-- 보너스 종류 (51:충전 / 52:이벤트 / 53:보상 / 61:테스트)
,	@NO_TOTAL_CASH				int = 0	OUTPUT			-- 충전 후 총 캐시
,	@DI_OUTPUT_RECORD			bit = 1					-- 결과 RecordSet 출력 여부
AS
	SET NOCOUNT ON

	-- 사용 변수 선언
	DECLARE @Result				int
	DECLARE @DT_GETDATE			datetime		-- 충전 시간 동기화용 시간

	DECLARE @CD_TRAN_NUM		bigint			-- 거래 고유번호
	,		@NO_UNITUID			bigint			-- 캐릭터 UID
	,		@NO_LEVEL			tinyint			-- 캐릭터 레벨
	,		@ST_TRANSACTION		varchar(60)		-- 처리열 고유 문자

	DECLARE @NO_REMAIN_CASH		int
	,		@NO_REMAIN_BONUS	int

	IF @DI_ORDER_TYPE NOT IN (51, 52, 53, 61) AND @NO_CHARGE_BONUS < 1
		SET @Result = -98
	ELSE BEGIN
		IF @DI_ORDER_TYPE = 51 BEGIN
			SELECT @ST_TRANSACTION = ST_TRANSACTION + '_'+ CAST(@DI_ORDER_TYPE AS varchar(2)) +'_Bonus'
			, @CD_USERUID = CD_USERUID, @ST_USERID = ST_USERID
			, @NO_UNITUID = NO_UNITUID, @NO_LEVEL = NO_LEVEL
			, @NO_SERVER_SET_ID = NO_SERVER_SET_ID, @DT_GETDATE = DT_LOG_DATE
			FROM dbo.EB_CashLog WITH(NOLOCK)
			WHERE CD_TRAN_NUM = CAST(@ST_TRANSACTION_BASE AS bigint)
		END
		ELSE BEGIN
			SET @DT_GETDATE = GETDATE()
			
			SELECT @ST_TRANSACTION = CASE 
				WHEN ISNULL(@ST_TRANSACTION_BASE, '') = '' THEN ''
				ELSE ISNULL(@ST_TRANSACTION_BASE, '') + '_' END +
					CAST(@DI_ORDER_TYPE AS varchar(2)) +'_'+ REPLACE(REPLACE(REPLACE(CONVERT(varchar(20), @DT_GETDATE, 120), '-', ''), ' ', ''), ':', '') +'_'+ CAST(@CD_USERUID AS varchar(19)), @DT_GETDATE = GETDATE()
				, @NO_UNITUID = 0, @NO_LEVEL = 0
		END

		IF @@ROWCOUNT = 1 BEGIN
			EXEC @Result = dbo.EBI_TransactionNumber_INT @DI_ORDER_TYPE, @CD_TRAN_NUM OUTPUT

			IF @Result = 0 BEGIN
				BEGIN TRY
					BEGIN TRAN

					INSERT INTO dbo.EB_BillOrder (
						CD_TRAN_NUM, ST_TRANSACTION, CD_USERUID, ST_USERID, NO_SERVER_SET_ID, NO_UNITUID, NO_LEVEL, NO_CHARGE_CASH, NO_CHARGE_BONUS, NO_CHARGE_ITEM, ST_USER_IP, DI_ORDER_TYPE, DT_ORDER_DATE, DI_ORDER_RESULT, DT_RESULT_DATE
					) VALUES (
						@CD_TRAN_NUM, @ST_TRANSACTION, @CD_USERUID, @ST_USERID, @NO_SERVER_SET_ID, @NO_UNITUID, @NO_LEVEL, 0, @NO_CHARGE_BONUS, 0, @ST_USER_IP, @DI_ORDER_TYPE, @DT_GETDATE, 0, @DT_GETDATE
					)

					EXEC dbo.EBI_Cash_Charge_SET @CD_USERUID, @ST_USERID, 0, @NO_CHARGE_BONUS, @DT_GETDATE, @NO_REMAIN_CASH OUTPUT, @NO_REMAIN_BONUS OUTPUT
					EXEC dbo.EBI_CashLog_INT @CD_TRAN_NUM, @ST_TRANSACTION, NULL, @CD_USERUID, @ST_USERID, @NO_SERVER_SET_ID, @NO_UNITUID, @NO_LEVEL, @CD_USERUID, @NO_UNITUID, @DI_ORDER_TYPE, 0, 1, 0, @NO_CHARGE_BONUS, @NO_REMAIN_CASH, @NO_REMAIN_BONUS, @DT_GETDATE

					COMMIT TRAN
				END TRY
				BEGIN CATCH
					DECLARE @NO_XACT_STATE		smallint
					SET @NO_XACT_STATE			= XACT_STATE()		-- 트랜잭션 상태 정보

					IF @NO_XACT_STATE <> 0
						ROLLBACK TRAN

					EXEC dbo.EBI_SP_ErrorLog_INT @NO_XACT_STATE

					IF @Result = 0
						SET @Result = -1
				END CATCH
			END
		END
	END
	
	IF @Result <> 0
		EXEC dbo.EBI_Cash_Detial_SEL @CD_USERUID, @NO_REMAIN_CASH OUTPUT, @NO_REMAIN_BONUS OUTPUT
	
	SET @NO_TOTAL_CASH = @NO_REMAIN_CASH + @NO_REMAIN_BONUS
	
	IF @DI_OUTPUT_RECORD = 1
		SELECT @Result AS Result, @NO_TOTAL_CASH AS NO_TOTAL_CASH

	RETURN @Result
GO
/*
프로시저명 : dbo.EBP_BuyItem
내용 : 아이템 구매
작성일 : 2011-02-22
작성자 : KOG_M
수정일 : 2011-09-28
수정자 : KOG_M
수정내용 : 캐시를 선택(통합, 캐시, 보너스) 사용 하도록 조정
-- ## 관련 테이블 ##--
	없음
-- ## 관련 프로시저 ## --
	dbo.EBI_TransactionNumber_INT
	dbo.EBI_Cash_UseFirstCash
	dbo.EBI_Cash_Detial_SEL
	dbo.EBI_CashLog_INT
	dbo.EBI_Cash_Detial_SEL
	dbo.EBI_SP_ErrorLog_INT
-- ## 입력 ## --
	@ST_SERVERORDERID	varchar(50)			-- 서버 발행 주문번호('20101207204029_3_24_1' / yyyymmddhhmiss_ServerUID_UserUID_구매일련번호)
	@CD_USERUID			bigint				-- 계정 UID
	@ST_USERID			nvarchar(50)		-- 계정 아이디
	@NO_SERVER_SET_ID	tinyint				-- 서버 그룹
	@NO_UNITUID			bigint				-- 캐릭터 UID
	@NO_LEVEL			tinyint				-- 캐릭터 레벨
	@NO_PRODUCT_NUM		int					-- 아이템(상품) 번호
	@NO_QUANTITY		smallint			-- 구매 수량
	@NO_PRICE			smallint			-- 구매 가격
	@DI_ITEM_KEEP		tinyint				-- 캐시 보관함 저장 여부(1 - 저장 : 0 - 미저장)
	@NO_TO_USERUID		bigint				-- 받는 계정 UID
	@NO_TO_UNITUID		bigint				-- 받는 캐릭터 UID
	@ST_GIFT_MESSAGE	nvarchar(50)		-- 선물 메시지
	@DI_BUY_CASH		tinyint				-- 구매 캐시 종류(0 - 통합  : 1 - 캐시 : 2 - 보너스)(2011-09-28 추가)
-- ## 출력 ## --
	Output :
		@NO_TOTAL_CASH		int					-- 총 잔여 캐시
		@CD_TRAN_NUM		bigint				-- 거래 고유번호
		@NO_REMAIN_CASH		int					-- 잔여 캐시(2011-09-28 추가)
		@NO_REMAIN_BONUS	int					-- 잔여 보너스(2011-09-28 추가)
	ReturnValue : 있음
	RecodeSet : 선택
		Result, NO_TOTAL_CASH, NO_REMAIN_CASH, NO_REMAIN_BONUS
		SP 처리 결과, 총 잔여 캐시, 잔여 캐시, 잔여 보너스
-- ## 실행 ## --
	DECLARE @Result		int
	,	@ST_SERVERORDERID	varchar(50)			-- 서버 발행 주문번호('20101207204029_3_24_1' / yyyymmddhhmiss_ServerUID_UserUID_구매일련번호)
	,	@CD_USERUID			bigint				-- 계정 UID
	,	@ST_USERID			nvarchar(50)		-- 계정 아이디
	,	@NO_SERVER_SET_ID	tinyint				-- 서버 그룹
	,	@NO_UNITUID			bigint				-- 캐릭터 UID
	,	@NO_LEVEL			tinyint				-- 캐릭터 레벨
	,	@NO_PRODUCT_NUM		int					-- 아이템(상품) 번호
	,	@NO_QUANTITY		smallint			-- 구매 수량
	,	@NO_PRICE			smallint			-- 구매 가격
	,	@DI_ITEM_KEEP		tinyint				-- 캐시 보관함 저장 여부(1 - 저장 : 0 - 미저장)
	,	@NO_TO_USERUID		bigint				-- 받는 계정 UID
	,	@NO_TO_UNITUID		bigint				-- 받는 캐릭터 UID
	,	@ST_GIFT_MESSAGE	nvarchar(50)		-- 선물 메시지
	,	@DI_BUY_CASH		tinyint				-- 구매 캐시 종류(0 - 통합  : 1 - 캐시 : 2 - 보너스)(2011-09-28 추가)
	,	@NO_TOTAL_CASH		int					-- 총 잔여 캐시
	,	@CD_TRAN_NUM		bigint				-- 거래 고유번호
	,	@NO_REMAIN_CASH		int					-- 잔여 캐시(2011-09-28 추가)
	,	@NO_REMAIN_BONUS	int					-- 잔여 보너스(2011-09-28 추가)
	,	@DI_OUTPUT_RECORD	bit					-- 결과 RecordSet 출력 여부

	SELECT TOP 1
		@CD_USERUID			= CD_USERUID
	,	@ST_USERID			= ST_USERID
	,	@NO_SERVER_SET_ID	= CAST(RAND() * 10 / 2 AS tinyint) + 1
	,	@NO_UNITUID			= CAST((CAST(RAND() * 10000000000 AS bigint) / (CAST(RAND() * 100 AS tinyint) + 1)) AS bigint) + 1
	,	@NO_LEVEL			= CAST(RAND() * 58 AS tinyint) + 1
	,	@NO_QUANTITY		= 1
	,	@DI_ITEM_KEEP		= CAST(RAND() * 2 AS tinyint)
	,	@NO_TO_USERUID		= CD_USERUID
	FROM dbo.EB_Cash WITH(NOLOCK)
	WHERE CD_USERUID > 0
	ORDER BY NEWID()

	SET @DI_OUTPUT_RECORD = 0

	IF @@ROWCOUNT = 1 BEGIN
		SELECT TOP 1 @NO_PRODUCT_NUM = CD_PRODUCTNO, @NO_PRICE = NO_SALEPRICE
		FROM dbo.EB_Product WITH(NOLOCK)
		WHERE DI_ISSALE = 1
		ORDER BY NEWID()

		IF @@ROWCOUNT = 1 BEGIN
			IF CAST(RAND() * 2 AS tinyint) = 1 BEGIN
				SET @NO_TO_UNITUID	= @NO_UNITUID
			END
			ELSE BEGIN
				SET @NO_TO_USERUID	= CAST((CAST(RAND() * 10000000000 AS bigint) / (CAST(RAND() * 100 AS tinyint) + 1)) AS bigint) + 1
				SET @NO_TO_UNITUID	= CAST((CAST(RAND() * 10000000000 AS bigint) / (CAST(RAND() * 100 AS tinyint) + 1)) AS bigint) + 1
				SET @ST_GIFT_MESSAGE = N'From ' + CAST(@ST_USERID AS nvarchar(50))
			END



			DECLARE @NO_DATE_TRAN_NUM	int					-- 일별 발행 번호
			EXEC dbo.EBP_TranNumberServer_INT @NO_DATE_TRAN_NUM OUTPUT, @DI_OUTPUT_RECORD

			SET @ST_SERVERORDERID		= LEFT(N'B'+REPLACE(REPLACE(REPLACE(REPLACE(CONVERT(varchar(23), GETDATE(), 121), '-', ''), ' ', ''), ':', ''), '.', '') + RIGHT(CAST(@CD_USERUID AS varchar(10)), 10) + RIGHT('000000000' + CAST(@NO_DATE_TRAN_NUM AS varchar(20)), 9), 50)

			SET @DI_BUY_CASH		= 2
			EXEC @Result = dbo.EBP_BuyItem @ST_SERVERORDERID, @CD_USERUID, @ST_USERID, @NO_SERVER_SET_ID, @NO_UNITUID, @NO_LEVEL, @NO_PRODUCT_NUM, @NO_QUANTITY, @NO_PRICE, @DI_ITEM_KEEP, @NO_TO_USERUID, @NO_TO_UNITUID, @ST_GIFT_MESSAGE, @DI_BUY_CASH, @NO_TOTAL_CASH OUTPUT, @CD_TRAN_NUM OUTPUT, @NO_REMAIN_CASH OUTPUT, @NO_REMAIN_BONUS OUTPUT, @DI_OUTPUT_RECORD
		END
	END
	SELECT @Result AS Result, @NO_TOTAL_CASH AS NO_TOTAL_CASH, @CD_TRAN_NUM AS CD_TRAN_NUM, @NO_REMAIN_CASH AS NO_REMAIN_CASH, @NO_REMAIN_BONUS AS NO_REMAIN_BONUS
*/
CREATE OR ALTER PROCEDURE [dbo].[EBP_BuyItem]
	@ST_SERVERORDERID		varchar(50) ,			-- 서버 발행 주문번호('20101207204029_3_24_1' / yyyymmddhhmiss_ServerUID_UserUID_구매일련번호)
	@ST_GROUPORDERID		varchar(50) ,			-- 그룹별 발행 주문번호 (2013-04-30 추가)
	@CD_USERUID				bigint ,				-- 계정 UID
	@ST_USERID				nvarchar(50) ,			-- 계정 아이디
	@NO_SERVER_SET_ID		tinyint ,				-- 서버 그룹
	@NO_UNITUID				bigint ,				-- 캐릭터 UID
	@NO_LEVEL				tinyint ,				-- 캐릭터 레벨
	@NO_PRODUCT_NUM			bigint ,				-- 아이템(상품) 번호
	@NO_QUANTITY			smallint ,				-- 구매 수량
	@NO_PRICE				int ,					-- 구매 가격
	@DI_ITEM_KEEP			tinyint ,				-- 캐시 보관함 저장 여부(1 - 저장 : 0 - 미저장)
	@NO_TO_USERUID			bigint ,				-- 받는 계정 UID
	@NO_TO_UNITUID			bigint ,				-- 받는 캐릭터 UID
	@ST_GIFT_MESSAGE		nvarchar(50) ,			-- 선물 메시지
	@DI_BUY_CASH			tinyint ,				-- 구매 캐시 종류(0 - 통합  : 1 - 캐시 : 2 - 보너스)(2011-09-28 추가)
	@NO_CHANNEL_CODE		tinyint = 0 ,			-- 채널링 코드 (2013-05-11 추가)
	@NO_TOTAL_CASH			int = 0 OUTPUT ,		-- 총 잔여 캐시
	@CD_TRAN_NUM			bigint = 0 OUTPUT ,		-- 거래 고유번호
	@NO_REMAIN_CASH			int = 0 OUTPUT ,		-- 잔여 캐시(2011-09-28 추가)
	@NO_REMAIN_BONUS		int = 0 OUTPUT ,		-- 잔여 보너스(2011-09-28 추가)
	@DI_OUTPUT_RECORD		bit = 1					-- 결과 RecordSet 출력 여부
AS
	SET NOCOUNT ON

	-- 사용 변수 선언
	DECLARE @Result				int
	DECLARE @DT_GETDATE			datetime		-- 충전 시간 동기화용 시간
	DECLARE @ST_ErrorMSG		nvarchar(2048)	-- 오류 메시지

	DECLARE @NO_USE_CASH		int
	,	@NO_USE_BONUS			int
	,	@NO_BEFOR_CASH			int
	,	@NO_BEFOR_BONUS			int

	DECLARE @NO_LOCKER_COUNT	int
	,	@DI_CASH_LOG_TYPE		smallint
	,	@NO_FROM_UNITUID		bigint

	-- 상품 관련
	DECLARE @DI_ISSALE			bit
	,		@DT_STARTDATE		smalldatetime
	,		@DT_ENDDATE			smalldatetime
	,		@DI_ENABLEGIFT		bit
	,		@NO_SALEPRICE		int
	,		@NO_REALPRICE		int
	,		@NO_LIMIT_USERUID	int
	,		@NO_BUY_COUNT		int
	,		@CD_PRODUCT_SM		bigint

	-- 기본 처리 결과 정상으로 설정, 현재 시간 설정
	SELECT @Result = 0, @DT_GETDATE = GETDATE()
	SET @ST_ErrorMSG = N'[%s] dbo.EBP_ItemBuy ''%s'', %I64d, ''%s'', %d, %I64d, %d, %d, %d, %d, %d, %I64d, %I64d, ''%s'', %d, @NO_TOTAL_CASH = %d OUTPUT, @CD_TRAN_NUM = %I64d OUTPUT, @NO_REMAIN_CASH = %d OUTPUT, @NO_REMAIN_BONUS = %d OUTPUT'

	SET @DI_CASH_LOG_TYPE = CASE WHEN @CD_USERUID = @NO_TO_USERUID THEN -1 ELSE -11 END
	SET @NO_FROM_UNITUID = CASE WHEN @CD_USERUID = @NO_TO_USERUID THEN 0 ELSE @NO_UNITUID END
	IF @ST_GIFT_MESSAGE IS NULL
		SET @ST_GIFT_MESSAGE = N''

	-- 구매 전 체크
	EXEC @Result = dbo.EBP_Prepare_Buy_Product_CHK @ST_SERVERORDERID, @ST_GROUPORDERID, @CD_USERUID, @ST_USERID, @NO_SERVER_SET_ID,
						@NO_UNITUID, @NO_LEVEL, @NO_PRODUCT_NUM, @NO_QUANTITY, @NO_PRICE, @DI_ITEM_KEEP, @NO_TO_USERUID, 
						@NO_TO_UNITUID, @ST_GIFT_MESSAGE, @DI_BUY_CASH, @NO_CHANNEL_CODE,
						@NO_TOTAL_CASH OUTPUT, @CD_TRAN_NUM OUTPUT, @NO_REMAIN_CASH OUTPUT, @NO_REMAIN_BONUS OUTPUT, 0

	IF @Result <> 0 BEGIN
		GOTO END_PROC
	END
		
	-- 계정 구매 수량 제한 확인
	EXEC @Result = dbo.EBP_Buy_Product_LimitedUser_CHK @NO_PRODUCT_NUM, @NO_TO_USERUID, @NO_SERVER_SET_ID, @CD_PRODUCT_SM OUTPUT, @NO_LIMIT_USERUID OUTPUT, 0
	
	IF @Result <> 0
		GOTO END_PROC
		
	-- 충전 방식에 대한 CASH_LOG_TYPE 수정
	SET @DI_CASH_LOG_TYPE = @DI_CASH_LOG_TYPE - @DI_BUY_CASH

	-- 처리 고유번호 발행
	EXEC @Result = dbo.EBI_TransactionNumber_INT @DI_CASH_LOG_TYPE, @CD_TRAN_NUM OUTPUT

	IF @Result = 0 BEGIN
		BEGIN TRY
			BEGIN TRAN
			/*
				-- 구매 금액이 있으며(판매금액이 0인 상품도 있음[이벤트 등])
				IF @NO_PRICE > 0 BEGIN
					IF @DI_BUY_CASH = 1 BEGIN
						-- 리얼 캐시 차감 (리얼 캐시만)
						EXEC @Result = dbo.EBI_Cash_UseRealCashOnly @CD_USERUID, @ST_USERID, @NO_PRICE, @DT_GETDATE, @NO_REMAIN_CASH OUTPUT, @NO_REMAIN_BONUS OUTPUT, @NO_BEFOR_CASH OUTPUT, @NO_BEFOR_BONUS OUTPUT
					END
					ELSE IF @DI_BUY_CASH = 2 BEGIN
						-- 보너스 캐시 사용 (보너스 캐시만)
						EXEC @Result = dbo.EBI_Cash_UseBonusCashOnly @CD_USERUID, @ST_USERID, @NO_PRICE, @DT_GETDATE, @NO_REMAIN_CASH OUTPUT, @NO_REMAIN_BONUS OUTPUT, @NO_BEFOR_CASH OUTPUT, @NO_BEFOR_BONUS OUTPUT
					END
					ELSE BEGIN
						-- 캐시 차감 (캐시 우선)
						EXEC @Result = dbo.EBI_Cash_UseFirstCash @CD_USERUID, @ST_USERID, @NO_PRICE, @DT_GETDATE, @NO_REMAIN_CASH OUTPUT, @NO_REMAIN_BONUS OUTPUT, @NO_BEFOR_CASH OUTPUT, @NO_BEFOR_BONUS OUTPUT
					END

					IF @NO_REMAIN_CASH < 0 OR @NO_REMAIN_BONUS < 0 BEGIN
						-- 잔액 부족
						SET @Result = -21
						RAISERROR(@ST_ErrorMSG, 15, 1, N'BuyItem Buy', @ST_SERVERORDERID, @CD_USERUID, @ST_USERID, @NO_SERVER_SET_ID, @NO_UNITUID, @NO_LEVEL, @NO_PRODUCT_NUM, @NO_QUANTITY, @NO_PRICE, @DI_ITEM_KEEP, @NO_TO_USERUID, @NO_TO_UNITUID, @ST_GIFT_MESSAGE, @DI_BUY_CASH, @NO_TOTAL_CASH, @CD_TRAN_NUM, @NO_REMAIN_CASH, @NO_REMAIN_BONUS) WITH SETERROR
					END

					-- 사용 캐시 계산
					SELECT @NO_USE_CASH = -(@NO_BEFOR_CASH - @NO_REMAIN_CASH), @NO_USE_BONUS = -(@NO_BEFOR_BONUS - @NO_REMAIN_BONUS)
				END
				ELSE BEGIN
					-- 잔여 캐시확인(@NO_BEFOR_CASH, @NO_BEFOR_BONUS는 이후 프로세스에서 미 사용 변수로 프로시저 처리를 위해 임의 사용)
					EXEC dbo.EBI_Cash_Detial_SEL @CD_USERUID, @NO_REMAIN_CASH OUTPUT, @NO_REMAIN_BONUS OUTPUT
					SELECT @NO_USE_CASH = 0, @NO_USE_BONUS = 0
				END
*/
				-- 잔여 캐시확인(@NO_BEFOR_CASH, @NO_BEFOR_BONUS는 이후 프로세스에서 미 사용 변수로 프로시저 처리를 위해 임의 사용)
				EXEC dbo.EBI_Cash_Detial_SEL @CD_USERUID, @NO_REMAIN_CASH OUTPUT, @NO_REMAIN_BONUS OUTPUT
				SELECT @NO_USE_CASH = 0, @NO_USE_BONUS = 0
				
				-- 캐시 아이템 인벤에 저장하는 경우
				IF @DI_ITEM_KEEP = 1 BEGIN
					EXEC @Result = dbo.EBI_BuyCashItemLocker_SET @CD_TRAN_NUM, @NO_TO_USERUID, @NO_SERVER_SET_ID, @NO_PRODUCT_NUM, @NO_QUANTITY, @NO_FROM_UNITUID, @ST_GIFT_MESSAGE

					IF @Result <> 0 BEGIN
						RAISERROR(@ST_ErrorMSG, 15, 1, N'BuyItem ItemLocker', @ST_SERVERORDERID, @ST_GROUPORDERID, @CD_USERUID, @ST_USERID, @NO_SERVER_SET_ID, @NO_UNITUID, @NO_LEVEL, @NO_PRODUCT_NUM, @NO_QUANTITY, @NO_PRICE, @DI_ITEM_KEEP, @NO_TO_USERUID, @NO_TO_UNITUID, @ST_GIFT_MESSAGE, @DI_BUY_CASH, @NO_TOTAL_CASH, @CD_TRAN_NUM, @NO_REMAIN_CASH, @NO_REMAIN_BONUS) WITH SETERROR
					END
				END

				-- 계정 구매 수량 제한 상품 구매 수량 증가
				IF @NO_LIMIT_USERUID > 0 BEGIN
					EXEC @Result = dbo.EBI_Buy_Product_LimitedUser_Set @CD_PRODUCT_SM, @NO_TO_USERUID, @NO_SERVER_SET_ID, @NO_LIMIT_USERUID

					IF @Result <> 0 BEGIN
						RAISERROR(@ST_ErrorMSG, 15, 1, N'BuyItem LimitedUser', @ST_SERVERORDERID, @ST_GROUPORDERID, @CD_USERUID, @ST_USERID, @NO_SERVER_SET_ID, @NO_UNITUID, @NO_LEVEL, @NO_PRODUCT_NUM, @NO_QUANTITY, @NO_PRICE, @DI_ITEM_KEEP, @NO_TO_USERUID, @NO_TO_UNITUID, @ST_GIFT_MESSAGE, @DI_BUY_CASH, @NO_TOTAL_CASH, @CD_TRAN_NUM, @NO_REMAIN_CASH, @NO_REMAIN_BONUS) WITH SETERROR
					END
				END
				
				-- 캐시 로그 기록(구매 완료시)
				EXEC dbo.EBI_CashLog_INT @CD_TRAN_NUM, @ST_SERVERORDERID, @ST_GROUPORDERID, @CD_USERUID, @ST_USERID, @NO_SERVER_SET_ID, @NO_UNITUID, @NO_LEVEL, @NO_TO_USERUID, @NO_TO_UNITUID, @DI_CASH_LOG_TYPE, @NO_PRODUCT_NUM, @NO_QUANTITY, @NO_PRICE, @NO_USE_BONUS, @NO_REMAIN_CASH, @NO_REMAIN_BONUS, @DT_GETDATE
				-- 구입 단계별 로그 기록 (완료)
				EXEC dbo.EBP_BuyItemLog_INS @ST_SERVERORDERID, @ST_GROUPORDERID, @CD_USERUID, @ST_USERID, @NO_SERVER_SET_ID, @NO_UNITUID, @NO_LEVEL, @NO_PRODUCT_NUM, @NO_QUANTITY, @NO_PRICE, @DI_ITEM_KEEP, @NO_TO_USERUID, @NO_TO_UNITUID, @ST_GIFT_MESSAGE, @DI_BUY_CASH, @NO_CHANNEL_CODE, @NO_TOTAL_CASH, @CD_TRAN_NUM, @NO_REMAIN_CASH, @NO_REMAIN_BONUS, 0
			COMMIT TRAN

			-- 현재 총 잔액 확인
			EXEC dbo.EBI_Cash_Detial_SEL @CD_USERUID, @NO_REMAIN_CASH OUTPUT, @NO_REMAIN_BONUS OUTPUT
			SET @NO_TOTAL_CASH = @NO_REMAIN_CASH + @NO_REMAIN_BONUS
		END TRY
		BEGIN CATCH
			DECLARE @NO_XACT_STATE		smallint
			SET @NO_XACT_STATE			= XACT_STATE()		-- 트랜잭션 상태 정보

			IF @NO_XACT_STATE <> 0
				ROLLBACK TRAN

			EXEC dbo.EBI_SP_ErrorLog_INT @NO_XACT_STATE

			-- 별도 예외 처리가 아닌경우 DB오류
			IF @Result = 0
				SET @Result = -1
		END CATCH
	END

END_PROC:
	IF @DI_OUTPUT_RECORD = 1
		SELECT @Result AS Result, @NO_TOTAL_CASH AS NO_TOTAL_CASH, @CD_TRAN_NUM AS CD_TRAN_NUM, @NO_REMAIN_CASH AS NO_REMAIN_CASH, @NO_REMAIN_BONUS AS NO_REMAIN_BONUS
	
	
		
	RETURN @Result
GO
/*
프로시저명 : dbo.EBP_BillOrder_Result
내용 : 주문 완료(주문 결과 처리)
작성일 : 2011-02-18
작성자 : KOG_M
수정일 : 2011-09-28
수정자 : KOG_M
수정내용 : 캐시, 보너스 구분하여 출력 추가
-- ## 관련 테이블 ##--
	dbo.EB_BillOrder
-- ## 관련 프로시저 ## --
	dbo.EBI_BillEvent_CHK
	dbo.EBI_BillEvent_JOIN
	dbo.EBI_Bonus_Expire_INT
	dbo.EBI_Cash_Charge_SET
	dbo.EBI_CashLog_INT
	dbo.EBI_Cash_Detial_SEL
	dbo.EBI_SP_ErrorLog_INT
-- ## 입력 ## --
	@ST_TRANSACTION		varchar(21)		-- 처리열 고유 문자
	@DI_ORDER_RESULT	smallint		-- 주문 결과
-- ## 출력 ## --
	Output :
		@NO_TOTAL_CASH		int				-- 총 잔여 캐시
		@NO_CHARGE_CASH		int				-- 충전 한 캐시
		@NO_CHARGE_BONUS	int				-- 충전 한 보너스
		@NO_BONUS_ITEM		int				-- 충전 후 지급할 아이템
		@NO_UNITUID			bigint			-- 충전 캐릭터 UID
		@CD_USERUID			bigint			-- 충전 계정 UID
		@NO_REMAIN_CASH		int				-- 잔여 캐시(2011-09-28 추가)
		@NO_REMAIN_BONUS	int				-- 잔여 보너스(2011-09-28 추가)
	ReturnValue : 있음
	RecodeSet : 선택
		Result, NO_TOTAL_CASH, NO_CHARGE_CASH, NO_CHARGE_BONUS, NO_BONUS_ITEM, NO_UNITUID, CD_USERUID, NO_REMAIN_CASH, NO_REMAIN_BONUS
		SP 처리 결과, 충전 후 총 잔여 엘소드 캐시, 충전 한 엘소드 캐시, 충전 한 엘소드 보너스 캐시, 충전 후 지급할 아이템, 충전 캐릭터 UID, 충전 계정 UID, 잔여 캐시, 잔여 보너스
-- ## 실행 ## --
	DECLARE @Result			int
	,	@ST_TRANSACTION		varchar(21)		-- 처리열 고유 문자
	,	@CD_USERUID			bigint			-- 계정 UID
	,	@ST_USERID			nvarchar(50)	-- 계정 아이디
	,	@NO_SERVER_SET_ID	tinyint			-- 서버 그룹
	,	@NO_UNITUID			bigint			-- 캐릭터 UID
	,	@NO_LEVEL			tinyint			-- 캐릭터 레벨
	,	@NO_CHARGE_CASH		int				-- 충전 캐시
	,	@ST_USER_IP			varchar(16)		-- 유저 아이피
	,	@DI_ORDER_TYPE		tinyint			-- 주문 종류
	,	@DI_OUTPUT_RECORD	bit				-- 결과 RecordSet 출력 여부

	DECLARE @DI_ORDER_RESULT	smallint	-- 주문 결과
	,	@NO_TOTAL_CASH			int			-- 총 잔여 캐시
	,	@NO_CHARGE_BONUS		int			-- 충전 한 보너스
	,	@NO_BONUS_ITEM			int			-- 충전 후 지급할 아이템
	,	@NO_REMAIN_CASH			int			-- 잔여 캐시(2011-09-28 추가)
	,	@NO_REMAIN_BONUS		int			-- 잔여 보너스(2011-09-28 추가)

	SELECT @CD_USERUID		= CAST((CAST(RAND() * 10000000000 AS bigint) / (CAST(RAND() * 100 AS tinyint) + 1)) AS bigint) + 1
	,	@NO_UNITUID			= CAST((CAST(RAND() * 10000000000 AS bigint) / (CAST(RAND() * 100 AS tinyint) + 1)) AS bigint) + 1
	,	@NO_LEVEL			= CAST(RAND() * 58 AS tinyint) + 1
	,	@NO_SERVER_SET_ID	= 1
	,	@NO_CHARGE_CASH		= 100
	,	@ST_USER_IP			= '127.0.0.1'
	,	@DI_ORDER_TYPE		= 1
	,	@DI_ORDER_RESULT	= 0

	SET @DI_OUTPUT_RECORD	= 0
	
	-- 계정 정보
	SET @ST_USERID = N'darkstarbt'
	SET @CD_USERUID = 2
	
	--SELECT TOP 1 @ST_USERID = UserID
	--,	@CD_USERUID = UserUID
	--FROM [Account].[dbo].[MUser] WITH(NOLOCK)
	--ORDER BY NEWID()
	
	IF @@ROWCOUNT = 1 BEGIN
		-- 캐릭터 정보
		SELECT TOP 1 @NO_UNITUID = UnitUID, @NO_LEVEL = [Level]
		FROM [Game01].[dbo].[GUnit] WITH(NOLOCK)
		WHERE UserUID = @CD_USERUID
			AND Deleted = 0
		ORDER BY NEWID()
		
		IF @@ROWCOUNT = 1 BEGIN
			SELECT TOP 1 * FROM dbo.EB_CashLog WITH(NOLOCK)
			WHERE CD_USERUID = @CD_USERUID
			ORDER BY CD_TRAN_NUM DESC
			
			SELECT * FROM dbo.EB_Cash WITH(NOLOCK)
			WHERE CD_USERUID = @CD_USERUID
			
			DECLARE @NO_DATE_TRAN_NUM	int					-- 일별 발행 번호
			,	@NO_DATE_SECOND			int			-- 1970-01-01 부터 지난 초
			
			EXEC dbo.EBP_TranNumberServer_INT @NO_DATE_TRAN_NUM OUTPUT, @NO_DATE_SECOND OUTPUT, 0

			SET @ST_TRANSACTION		= LEFT(N'O'+RIGHT(REPLACE(REPLACE(REPLACE(REPLACE(CONVERT(varchar(23), GETDATE(), 121), '-', ''), ' ', ''), ':', ''), '.', ''), 14) + RIGHT('0000' + CAST(@NO_DATE_TRAN_NUM AS varchar(4)), 4) + RIGHT(CAST(@CD_USERUID AS varchar(10)), 10), 21)

			EXEC @Result = dbo.EBP_BillOrder_GameServer_SET @ST_TRANSACTION, @CD_USERUID, @ST_USERID, @NO_SERVER_SET_ID, @NO_UNITUID, @NO_LEVEL, @NO_CHARGE_CASH, @ST_USER_IP, @DI_ORDER_TYPE, 0
			IF @Result = 0 BEGIN
				EXEC @Result = dbo.EBP_BillOrder_Result @ST_TRANSACTION, @DI_ORDER_RESULT, @NO_TOTAL_CASH OUTPUT, @NO_CHARGE_CASH OUTPUT, @NO_CHARGE_BONUS OUTPUT, @NO_BONUS_ITEM OUTPUT, @NO_UNITUID OUTPUT, @CD_USERUID OUTPUT, @NO_REMAIN_CASH OUTPUT, @NO_REMAIN_BONUS OUTPUT, @DI_OUTPUT_RECORD

				IF @DI_OUTPUT_RECORD = 0
					SELECT @Result AS Result, @NO_TOTAL_CASH AS NO_TOTAL_CASH, @NO_CHARGE_CASH AS NO_CHARGE_CASH, @NO_CHARGE_BONUS AS NO_CHARGE_BONUS, @NO_BONUS_ITEM AS NO_BONUS_ITEM, @NO_UNITUID AS NO_UNITUID, @CD_USERUID AS CD_USERUID
				
				SELECT TOP 2 * FROM dbo.EB_CashLog WITH(NOLOCK)
				WHERE CD_USERUID = @CD_USERUID
				ORDER BY CD_TRAN_NUM DESC
				
				SELECT * FROM dbo.EB_Cash WITH(NOLOCK)
				WHERE CD_USERUID = @CD_USERUID
			END
		END
		ELSE
			SELECT 'E1', @ST_USERID, @CD_USERUID, @NO_UNITUID, @NO_LEVEL
	END
	ELSE
		SELECT 'E0', @ST_USERID, @CD_USERUID
*/
CREATE OR ALTER PROCEDURE [dbo].[EBP_BillOrder_Result]
	@ST_TRANSACTION			varchar(21) ,			-- 처리열 고유 문자
	@DI_ORDER_RESULT		smallint ,				-- 주문 결과
	@NO_TOTAL_CASH			int = 0 OUTPUT ,		-- 총 잔여 캐시
	@NO_CHARGE_CASH			int = 0 OUTPUT ,		-- 충전 한 캐시
	@NO_CHARGE_BONUS		int = 0 OUTPUT ,		-- 충전 한 보너스
	@NO_BONUS_ITEM			bigint = 0 OUTPUT ,		-- 충전 후 지급할 아이템
	@NO_UNITUID				bigint = 0 OUTPUT ,		-- 충전 캐릭터 UID
	@CD_USERUID				bigint = 0 OUTPUT ,		-- 충전 계정 UID
	@NO_REMAIN_CASH			int = 0 OUTPUT ,		-- 잔여 캐시(2011-09-28 추가)
	@NO_REMAIN_BONUS		int = 0 OUTPUT ,		-- 잔여 보너스(2011-09-28 추가)
	@DI_OUTPUT_RECORD		bit = 1					-- 결과 RecordSet 출력 여부
AS
	SET NOCOUNT ON

	-- 사용 변수 선언
	DECLARE @Result				int
	DECLARE @DT_GETDATE			datetime		-- 충전 시간 동기화용 시간
	DECLARE @ST_ErrorMSG		nvarchar(2048)	-- 오류 메시지

	DECLARE @CD_TRAN_NUM		bigint
	,	@ST_USERID				nvarchar(50)
	,	@NO_SERVER_SET_ID		tinyint
	,	@NO_LEVEL				tinyint			-- 캐릭터 레벨
	,	@DI_ORDER_TYPE			smallint		-- 주문 종류
	,	@DI_ORDER_RESULT_ORG	smallint		-- 처리 전 주문 번호
	,	@ST_USER_IP				varchar(16)		-- 유저 아이피

	DECLARE @CD_EVENT			int				-- 이벤트 고유번호
	,	@NO_EVENT_BONUS			int				-- 이벤트 보너스 캐시
	,	@DT_BONUS_EXPIRE		smalldatetime	-- 보너스 만료일시
	,	@NO_LIMIT_BONUS_JOIN	smallint		-- 보너스 지급 제한
	,	@NO_LIMIT_ITEM_JOIN		smallint		-- 보너스 아이템 지급 제한

	-- 주문 정보 확인
	SELECT @CD_TRAN_NUM = CD_TRAN_NUM, @ST_USERID = ST_USERID, @CD_USERUID = CD_USERUID, @NO_SERVER_SET_ID = NO_SERVER_SET_ID
	, @NO_UNITUID = NO_UNITUID, @NO_LEVEL = NO_LEVEL
	, @NO_CHARGE_CASH = NO_CHARGE_CASH, @NO_CHARGE_BONUS = NO_CHARGE_BONUS
	, @DI_ORDER_TYPE = DI_ORDER_TYPE, @DI_ORDER_RESULT_ORG = DI_ORDER_RESULT
	, @ST_USER_IP = ST_USER_IP
	, @NO_BONUS_ITEM = 0
	FROM dbo.EB_BillOrder WITH(NOLOCK) WHERE ST_TRANSACTION = @ST_TRANSACTION

	-- 주문에 없는 경우 예외 처리
	IF @@ROWCOUNT = 0 BEGIN
		-- 주문 없음
		SET @Result = -99
		GOTO END_PROC
	END

	-- 주문이 이미 처리된 경우 예외 처리
	IF @DI_ORDER_RESULT_ORG <> 1 BEGIN
		-- 처리 완료 주문(중복 처리)
		SET @Result = -11
		GOTO END_PROC
	END

	-- 기본 처리 결과 정상으로 설정, 현재 시간 설정
	SELECT @Result = 0, @DT_GETDATE = GETDATE()
	SET @ST_ErrorMSG = N'[%s] dbo.EBP_BillOrder_Result ''%s'', %d, @NO_TOTAL_CASH = %d OUTPUT, @NO_CHARGE_CASH = %d OUTPUT, @NO_CHARGE_BONUS = %d OUTPUT, @NO_BONUS_ITEM = %d OUTPUT, @NO_UNITUID = %I64d OUTPUT'

	-- 프로세스 시작
	BEGIN TRY
		-- 트랙잭션 시작
		BEGIN TRAN
			-- 충전 결과 기록 저장
			UPDATE dbo.EB_BillOrder
			SET	NO_CHARGE_BONUS = @NO_CHARGE_BONUS
			,	NO_CHARGE_ITEM = @NO_BONUS_ITEM
			,	DI_ORDER_RESULT = @DI_ORDER_RESULT
			,	DT_RESULT_DATE = @DT_GETDATE
			WHERE CD_TRAN_NUM = @CD_TRAN_NUM
				AND DI_ORDER_RESULT = 1

			-- 처리된 주문이 있으면 충전 없으면 예외 처리
			IF @@ROWCOUNT = 1 BEGIN
				-- 충전 성공이면 충전
				IF @DI_ORDER_RESULT = 0 BEGIN
					-- 캐시 충전
					EXEC @Result = dbo.EBI_Cash_Charge_SET @CD_USERUID, @ST_USERID, @NO_CHARGE_CASH, @NO_CHARGE_BONUS, @DT_GETDATE, @NO_REMAIN_CASH OUTPUT, @NO_REMAIN_BONUS OUTPUT

					IF @Result <> 0 BEGIN
						-- 캐시 충전 실패
						SET @Result = -1
						RAISERROR(@ST_ErrorMSG, 15, 1, N'Order Cash Set', @ST_TRANSACTION, @DI_ORDER_RESULT, @NO_TOTAL_CASH, @NO_CHARGE_CASH, @NO_CHARGE_BONUS, @NO_BONUS_ITEM, @NO_UNITUID) WITH SETERROR
					END
					
					-- 총 잔여 캐시
					SET @NO_TOTAL_CASH = @NO_REMAIN_CASH + @NO_REMAIN_BONUS
					
					-- 캐시 로그 기록
					EXEC @Result = dbo.EBI_CashLog_INT @CD_TRAN_NUM, @ST_TRANSACTION, NULL, @CD_USERUID, @ST_USERID, @NO_SERVER_SET_ID, @NO_UNITUID, @NO_LEVEL, @CD_USERUID, @NO_UNITUID, @DI_ORDER_TYPE, 0, 1, @NO_CHARGE_CASH, @NO_CHARGE_BONUS, @NO_REMAIN_CASH, @NO_REMAIN_BONUS, @DT_GETDATE

					IF @Result <> 0 BEGIN
						-- 캐시로그 기록 실패
						SET @Result = -1
						RAISERROR(@ST_ErrorMSG, 15, 1, N'Order CashLog IN', @ST_TRANSACTION, @DI_ORDER_RESULT, @NO_TOTAL_CASH, @NO_CHARGE_CASH, @NO_CHARGE_BONUS, @NO_BONUS_ITEM, @NO_UNITUID) WITH SETERROR
					END
				END
			END
			ELSE BEGIN
				-- 처리 완료 주문(중복 처리)
				SET @Result = -11
				RAISERROR(@ST_ErrorMSG, 15, 1, N'Order Duplication Result', @ST_TRANSACTION, @DI_ORDER_RESULT, @NO_TOTAL_CASH, @NO_CHARGE_CASH, @NO_CHARGE_BONUS, @NO_BONUS_ITEM, @NO_UNITUID) WITH SETERROR
			END

		COMMIT TRAN
		
		-- 현재 진행중인 이벤트가 있으면
		IF @DI_ORDER_RESULT = 0 AND @Result = 0 BEGIN
			EXEC dbo.EBI_BillEvent_CHK @NO_CHARGE_CASH, @CD_EVENT OUTPUT, @NO_EVENT_BONUS OUTPUT, @DT_BONUS_EXPIRE OUTPUT, @NO_BONUS_ITEM OUTPUT, @NO_LIMIT_BONUS_JOIN OUTPUT, @NO_LIMIT_ITEM_JOIN OUTPUT
			
			IF @CD_EVENT > 0 BEGIN
				DECLARE @EventResult		int
				,	@ST_TRANSACTION_BASE	varchar(20)
				
				SET @ST_TRANSACTION_BASE = CAST(@CD_TRAN_NUM AS varchar(20))
				
				EXEC @EventResult = dbo.EBI_BillEvent_JOIN @CD_EVENT, @CD_TRAN_NUM, @CD_USERUID, @NO_LIMIT_BONUS_JOIN, @NO_LIMIT_ITEM_JOIN, @NO_EVENT_BONUS OUTPUT, @NO_BONUS_ITEM OUTPUT, @DT_GETDATE

				-- 이벤트 참여 오류 예외 처리
				IF @EventResult <> 0 BEGIN
					-- 이벤트 참여 오류
					SET @EventResult = -12
					--RAISERROR(@ST_ErrorMSG, 15, 1, N'Order Evnet Join', @ST_TRANSACTION, @DI_ORDER_RESULT, @NO_TOTAL_CASH, @NO_CHARGE_CASH, @NO_CHARGE_BONUS, @NO_BONUS_ITEM, @NO_UNITUID) WITH SETERROR
				END

				-- 충전 보너스가 있고 만료일이 있으면
				IF @EventResult = 0 AND @NO_EVENT_BONUS > 0 AND @DT_BONUS_EXPIRE IS NOT NULL BEGIN
					EXEC @EventResult = dbo.EBI_Bonus_Expire_INT @CD_TRAN_NUM, @CD_USERUID, @NO_EVENT_BONUS, @DT_BONUS_EXPIRE

					-- 만료 등록 오류 예외 처리
					IF @EventResult <> 0 BEGIN
						-- 이벤트 참여 오류
						SET @EventResult = -12
						--RAISERROR(@ST_ErrorMSG, 15, 1, N'Order Expire INT', @ST_TRANSACTION, @DI_ORDER_RESULT, @NO_TOTAL_CASH, @NO_CHARGE_CASH, @NO_CHARGE_BONUS, @NO_BONUS_ITEM, @NO_UNITUID) WITH SETERROR
					END
				END
				
				IF @EventResult = 0 AND @NO_EVENT_BONUS > 0 BEGIN
					EXEC @EventResult = dbo.EBP_BillOrder_Bonus_SET @ST_TRANSACTION_BASE, @CD_USERUID, @ST_USERID, @NO_SERVER_SET_ID, @ST_USER_IP, @NO_EVENT_BONUS, 51, @NO_TOTAL_CASH OUTPUT, 0
					
					IF @EventResult = 0
						SET @NO_CHARGE_BONUS = @NO_EVENT_BONUS
				END
			END
		END
	END TRY
	BEGIN CATCH
		DECLARE @NO_XACT_STATE		smallint
		SET @NO_XACT_STATE			= XACT_STATE()		-- 트랜잭션 상태 정보

		IF @NO_XACT_STATE <> 0
			ROLLBACK TRAN

		EXEC dbo.EBI_SP_ErrorLog_INT @NO_XACT_STATE

		-- 별도 예외 처리가 아닌경우 DB오류
		IF @Result = 0
			SET @Result = -1
	END CATCH

END_PROC:
	IF @DI_ORDER_RESULT <> 0 OR (@DI_ORDER_RESULT = 0 AND (@NO_TOTAL_CASH = 0 OR @NO_TOTAL_CASH IS NULL)) BEGIN
		-- 현재 총 잔액 확인
		EXEC dbo.EBI_Cash_Detial_SEL @CD_USERUID, @NO_REMAIN_CASH OUTPUT, @NO_REMAIN_BONUS OUTPUT

		SET @NO_TOTAL_CASH = @NO_REMAIN_CASH + @NO_REMAIN_BONUS
	END
	
	-- 처리 결과가 정상이 아니면
	IF @Result <> 0
		SELECT @NO_CHARGE_CASH = 0, @NO_CHARGE_BONUS = 0, @NO_BONUS_ITEM = 0, @NO_UNITUID = 0

	IF @DI_OUTPUT_RECORD = 1
		SELECT @Result AS Result, @NO_TOTAL_CASH AS NO_TOTAL_CASH, @NO_CHARGE_CASH AS NO_CHARGE_CASH, @NO_CHARGE_BONUS AS NO_CHARGE_BONUS, @NO_BONUS_ITEM AS NO_BONUS_ITEM, @NO_UNITUID AS NO_UNITUID, @CD_USERUID AS CD_USERUID, @NO_REMAIN_CASH AS NO_REMAIN_CASH, @NO_REMAIN_BONUS AS NO_REMAIN_BONUS

	RETURN @Result
GO
